(window.GIM_TS=window.GIM_TS||{})["Bava Kamma.7"]={"from":168,"a":[["\u0003חייב בכולן,\u0004 כלומר, בכל חמשת התשלומים של החובל בחבירו.","ונברר: \u0003האי\u0004 \u0005[זה]\u0006 החובל בהוריו באופן ש\u0003לא עשה בו חבורה, היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003כגון שהכהו על ידו\u0004 ונפגעה ידו ואינו יכול לעבוד בה \u0003וסופו לחזור\u0004 ולהירפא, \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003חייב בכולן\u0004 ואף בנזק, אף שהוא זמני. ואם כן יש מכאן תשובה לשאלה ששאל רבה.","\u0003אמרי\u0004 \u0005[אומרים\u0006 בדחייה\u0005]:\u0006 \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — \u0003כגון שחירשו\u0004 (עשה את אחד מהוריו חרש) על ידי מכה, \u0003ולא עשה בו חבורה,\u0004 שהוא נזק שאינו חוזר ומשום כך משלם את כל חמשת התשלומים. ומקשים: כיצד ניתן להעמיד במקרה כזה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה\u0004 עצמו: \u0003החורש\u0004 (העושה חרש) \u0003את אביו\u0004 על ידי שמכה אותו — \u0003נהרג,\u0004 אף על פי שאין רואים חבורה, \u0003לפי שאי אפשר לחרישה בלא חבורה,\u0004 מדוע? ודאי \u0003טיפתא דדמא נפלה ליה באודניה\u0004 \u0005[טיפת דם נפלה לו באוזנו]\u0006 והיא שגרמה לו את החרשות, אף על פי שאין הדבר נראה מבחוץ!","\u0003אלא\u0004 יש לומר כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שגילחו,\u0004 שגילח את שערו ולא גרם לו לחבורה. ואומרים: אם \u0003גילחו מהדר הדר\u0004 \u0005[הרי חוזר הדבר],\u0006 \u0003והיינו בעיין\u0004 \u0005[והרי זו שאלתנו]\u0006 ששאלנו מה קורה בנזק שסופו להיתקן? ואם כן, נמצא פתרון לשאלת רבה.","\u0003אמרי\u0004 \u0005[אומרים\u0006 בדחייה\u0005]:\u0006 \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שסכו נשא\u0004 \u0005[\u0006ב\u0005סם]\u0006 שגורם לכך שהשערות \u0003לא הדר\u0004 \u0005[יחזרו]\u0006 ויצמחו.","ומסבירים כיצד בענין זה יכול להיות שחייב בחמישה דברים: \u0003צער\u0004 — כגון \u0003דאית ליה קרטופני ברישיה\u0004 \u0005[שיש לו פצעים בראשו]\u0006 \u0003וצווחי מהנהו קרטופני\u0004 \u0005[ו\u0006יש לו \u0005כאבים מאותם הפצעים]\u0006 בגלל הסם. \u0003ריפוי\u0004 — \u0003דבעיא אסויי\u0004 \u0005[שצריך לרפא אותו]\u0006 מהפצעים הללו. \u0003שבת\u0004 — \u0003דהוה מרקיד בי כובי, דבעיא מחוי גוני ארישא\u0004 \u0005[שהיה\u0006 זה אדם \u0005שרוקד\u0006 בשכר \u0005בבית המרזח, שהיה רוצה להראות\u0006 תוך כדי ריקוד \u0005דברים בראשו\u0006 ושערותיו\u0005],\u0006 \u0003ו\u0004עתה \u0003לא מחוי מהנהו קרטופני\u0004 \u0005[מראה מ\u0006חמת \u0005הפצעים הללו].\u0006 \u0003בושת\u0004 — \u0003אין לך בושת גדול מזה\u0004 שגילח אותו ונראים על ראשו אותם פצעים.","ומעירים: \u0003ומילתא דבעיא ליה\u0004 \u0005[ודבר שהיה מסופק לו]\u0006 \u0003לרבה,\u0004 \u0003פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 \u0003לאביי\u0004 \u0003להך גיסא\u0004 \u0005[כצד זה]\u0006 של הבעיה, \u0003ולרבא להך גיסא\u0004 \u0005[כצד האחר]\u0006 של הבעיה, כלומר, שכל אחד מהם פתר את הבעיה, אבל כל אחד פתרה באופן אחר. \u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בבעיה זו של רבה מה הדין אם \u0003הכהו על ידו וצמתה\u0004 (יבשה, שותקה) \u0003וסופה לחזור, אביי אמר: נותן לו שבת גדולה,\u0004 כלומר, נזק, דמי היד, \u0003ושבת קטנה\u0004 דמי ביטול מלאכה. \u0003ורבא אמר: אינו נותן לו אלא דמי שבתו שבכל יום ויום,\u0004 שמשלם רק את השבת במשך הימים שבפועל אינו עובד בהם, אבל לא את דמי היד. ושניהם פתרו איפוא שאלה זו.","ועוד נחלקו אביי ורבא בתשלומי נזק ושבת. \u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003הקוטע יד עבד עברי של חבירו, אביי אמר: נותן לו שבת גדולה\u0004 (נזק) \u0003לעבד, ושבת קטנה\u0004 את דמי ביטול המלאכה שלו בזמן חוליו \u0003לרב\u0004 (לאדון). \u0003רבא אמר: הכל ינתן לעבד,\u0004 אבל \u0003ילקח\u0004 (יקנה) \u0003בהן קרקע והרב אוכל\u0004 את \u0003פירות\u0004 הקרקע כל תקופת עבדותו של העבד, ונמצא על ידי זה ששניהם מקבלים את המגיע להם.","ומעירים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005],\u0006 אם \u0003פיחת\u0004 שגרם לעבד נזק שפוחת ערכו \u0003אצל עצמו, ואצל רבו לא פיחת\u0004 שבשביל אדוניו אין בזה פחת, \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 — כגון \u0003דפסקיה לריש אוניה\u0004 \u0005[שחתך את תחילת אוזנו]\u0006 \u0003או לריש נחיריה\u0004 \u0005[את תחילת נחירו],\u0006 שלענין מלאכה לרבו אין בזה הבדל, אבל יש בזה נזק לעבד עצמו, במקרה כזה \u0003הכל,\u0004 כל מה שיש לשלם הרי זה ניתן \u0003לעצמו,\u0004 לעבד, ואולם אם \u0003פיחת אצל רבו\u0004 שהיה נזק גם אצל רבו — בזה \u0003פלוגתא\u0004 \u0005[המחלוקת]\u0006 של \u0003אביי ורבא.\u0004","שנינו במשנה: שתשלום \u0003בושת\u0004 — \u0003הכל לפי המבייש והמתבייש.\u0004 ומסבירים: \u0003מני מתניתין\u0004 \u0005[כ\u0006שיטת \u0005מי היא משנתנו]\u0006 — \u0003לא\u0004 כדעת \u0003ר' מאיר ולא\u0004 כדעת \u0003ר' יהודה, אלא\u0004 כדעת \u0003ר' שמעון היא.\u0004","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 בברייתא: \u0003וכולן\u0004 כל אלו שבוישו על ידי אחרים \u0003רואין אותן\u0004 (מתייחסים אליהם) לענין חישוב דמי הבושת \u0003כאילו הם בני חורין ש\u0004היו עשירים ו\u0003ירדו מנכסיהם,\u0004 אף על פי שאינם עשירים כעת. ומדוע? — \u0003שהן בני אברהם יצחק ויעקב\u0004 ומגיע להם. אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 אומדים כל אדם לפי מה שהוא: \u0003הגדול לפי גודלו, והקטן לפי קטנו. ר' שמעון אומר: עשירים\u0004 — \u0003רואין אותן כאילו הם בני חורין שירדו מנכסיהם, עניים\u0004 — רואים אותן \u0003כפחותין שבהן\u0004 שבעניים, וכל זאת כדי להקל בתשלום הבושת על המבייש.","ומעתה נברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא\u0006 משנתנו\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' מאיר\u0004 הלא \u0003מתניתין קתני\u0004 \u0005[משנתנו שונה]:\u0006 \u0003הכל לפי המבייש והמתבייש,\u0004 לשיטת \u0003ר' מאיר: כולהו בהדי הדדי נינהו\u0004 \u0005[כולם\u0006 כל המבוישים \u0005זה כמו זה הם].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 כדעת \u0003ר' יהודה,\u0004 הלא \u0003מתניתין קתני\u0004 \u0005[משנתנו שונה]\u0006 להלן (עמוד ב): \u0003המבייש את הסומא\u0004 — \u0003חייב, ואילו ר' יהודה אומר: סומא אין לו\u0004 תשלום \u0003בושת. אלא לאו\u0004 \u0005[האם לא]\u0006 כשיטת \u0003ר' שמעון היא?\u0004","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיא כדעת \u0003ר' יהודה, כי אמר\u0004 \u0005[כאשר אומר]\u0006 \u0003ר' יהודה סומא אין לו בושת,\u0004 הכוונה היא לסומא שבייש אדם פיקח \u0003למשקל מיניה\u0004 \u0005[לקחת ממנו]\u0006 דמי בושתו של המבוייש, שמפני שהוא סומא אינו רואה מה הוא עושה, ואין אדם מתחייב בתשלום בושת אלא אם נתכוון, \u0003אבל למיתבא ליה\u0004 \u0005[לתת לו\u0006 לסומא\u0005]\u0006 כאשר ביישו אותו — \u0003יהבינן ליה\u0004 \u0005[נותנים לו]\u0006 דמי בושתו.","ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי ממה ש\u0006הוא \u0005שונה\u0006 ב\u0005סוף\u0006 המשנה\u0005]:\u0006 \u0003המבייש את הישן\u0004 — \u0003חייב, וישן שבייש\u0004 — \u0003פטור,\u0004 ודווקא בזה מחלקת המשנה \u0003ולא קתני\u0004 \u0005[ואינה שונה]\u0006 חילוק נוסף בין סומא שבויש, שחייב המבייש, ו\u0003סומא שבייש\u0004 אחר שהוא \u0003פטור, מכלל\u0004 הדברים אתה למד ש\u0003לא שנא הכי\u0004 \u0005[שונה כך]\u0006 \u0003ולא שנא הכי\u0004 \u0005[שונה כך]\u0006 ואין לחלק בסומא ובכל מקרה פטור! \u0003אלא מחוורתא\u0004 \u0005[מחוור,\u0006 ברור\u0005]\u0006 כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 כשיטת \u0003ר' שמעון היא.\u0004","ומנסים לברר לפי ברייתא זו גם ברייתא שנאמרה בסתם. ובאותו ענין שואלים עוד: \u0003מאן תנא להא דתנו רבנן\u0004 \u0005[מי שנה את זו ששנו חכמים]:\u0006 \u0003נתכוון לבייש את הקטן ובייש את הגדול\u0004 — \u0003נותן לגדול דמי בושתו של קטן.\u0004 התכוון \u0003לבייש את העבד ובייש את בן חורין\u0004 — \u0003נותן לבן חורין דמי בושתו של עבד.\u0004 ונברר: \u0003מני\u0004 \u0005[כ\u0006שיטת \u0005מי היא]?\u0006 \u0003לא\u0004 כשיטת \u0003ר' מאיר ולא\u0004 כשיטת \u0003ר' יהודה ולא\u0004 כשיטת \u0003ר' שמעון!\u0004","ומסבירים מדוע אין זה כשיטת כל אלו התנאים: \u0003קא סלקא דעתך\u0004 \u0005[עלה על דעתך]\u0006 מתחילה לומר ש\u0003קטן\u0004 זה הנזכר בברייתא — הכוונה למי שהוא \u0003קטן בנכסים\u0004 (עני), \u0003גדול\u0004 — \u0003גדול בנכסים\u0004 (עשיר), ומעתה \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' מאיר\u0004 אי אפשר לומר זאת כי \u0003האמר\u0004 \u0005[הרי\u0006 הוא \u0005אומר]:\u0006 \u0003כולהו בהדי הדדי נינהו\u0004 \u0005[כולם זה כמו זה הם],\u0006 שדנים בכולם דין אחד של בן חורין שירד מנכסיו, ואין הבדל בין עני לעשיר! \u0003ואי\u0004 \u0005[ואם]\u0006 כשיטת \u0003ר' יהודה, האמר\u0004 \u0005[הרי\u0006 הוא \u0005אומר]:\u0006 \u0003אין לעבדים בושת,\u0004 וממילא אין ענין של בושת בעבד ואין בן החורין מקבל דבר אם התכוון המבייש לבייש עבד! \u0003ואי\u0004 \u0005[ואם]\u0006 כשיטת \u0003ר' שמעון, האמר\u0004 \u0005[הרי\u0006 הוא \u0005אומר]:\u0006 \u0003נתכוון לבייש את זה ובייש את זה\u0004 — \u0003פטור\u0004 לגמרי,","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — הרי זה \u0003כקטלא\u0004 \u0005[כ\u0006מו דין \u0005מיתה],\u0006 \u0003מה קטלא\u0004 \u0005[מיתה]\u0006 אין ממיתים אותו \u0003עד\u0004 שהרג את האדם ש\u0003מתכוון ליה\u0004 \u0005[לו]\u0006 דווקא, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וארב לו וקם עליו\"\u0004 (דברים יט, יא) שכוונתו: \u0003עד שיתכוון לו,\u0004 לזה שהרג, \u0003בושת נמי\u0004 \u0005[גם כן]\u0006 \u0003עד דמיכוין ליה\u0004 \u0005[שמתכוון לו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושלחה ידה והחזיקה במבשיו\"\u0004 (דברים כה, יא), שאין משלם עבור הבושת \u0003עד שיתכוון לו!\u0004","ודוחים: \u0003לעולם\u0004 שיטת \u0003ר' יהודה\u0004 היא, \u0003וכי קאמר\u0004 \u0005[וכאשר אומר]\u0006 \u0003ר' יהודה אין לעבדים בושת\u0004 — הרי זה \u0003למיתבא להו\u0004 \u0005[לתת להם],\u0006 \u0003אבל למישם, שיימינן בהו\u0004 \u0005[לאמוד, אומדים אותם]\u0006 כמה בושת יש להם, ואותו שיעור בושת ישלם לבן החורין שביישו מתוך מחשבה שהוא עבד.","\u0003ואי בעית אימא ד\u0004\u0005[ואם תרצה אמור]:\u0006 \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיא כשיטת \u0003ר' מאיר,\u0004 שכן \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 ש\u0003גדול\u0004 — \u0003גדול בנכסים, קטן\u0004 — \u0003קטן בנכסים? לא, גדול\u0004 — \u0003גדול ממש\u0004 (מבוגר), \u0003וקטן\u0004 — \u0003קטן ממש\u0004 שעדיין לא הגיע לבגרות.","ושואלים: \u0003ו\u0004כי \u0003קטן בר\u0004 \u0005[בן]\u0006 \u0003בושת הוא,\u0004 הרי אין בו דעת? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003רב פפא\u0004 בענין אחר: שמדובר בקטן בגיל \u0003דמיכלמו ליה ומיכלם\u0004 \u0005[שכשמביישים אותו ו\u0006הוא \u0005מתבייש]\u0006 שיש לו בושת, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 —"],["מדובר באופן \u0003דמיכלמו ליה ומיכלם\u0004 \u0005[שמביישים אותו ומתבייש]\u0006 ולכן צריך לשלם לגדול כשיעור בושתו של קטן כזה.","\u0003המבייש את הערום,\u0004 וכן \u0003המבייש את הסומא, והמבייש את הישן\u0004 — על כל אלה \u0003חייב,\u0004 \u0003ו\u0004אולם \u0003ישן שבייש\u0004 — \u0003פטור. נפל מן הגג\u0004 על אדם \u0003והזיק\u0004 את מי שנפל עליו \u0003ו\u0004בתוך כך גם \u0003בייש\u0004 אותו — \u0003חייב על הנזק,\u0004 שאדם מועד לעולם, \u0003ופטור על הבושת,\u0004 לפי שאין משלמים על הבושת \u0003עד שיהא\u0004 המבייש \u0003מתכוין\u0004 לבייש.","ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ביישו ערום\u0004 אם בייש אדם מסויים כשהיה אותו אדם ערום — \u0003חייב, ו\u0004אולם \u0003אינו דומה\u0004 מידת הבושה, ולכן גם מידת התשלומים של מי ש\u0003ביישו\u0004 כשהוא \u0003ערום ל\u0004מי ש\u0003ביישו\u0004 כשהוא \u0003לבוש,\u0004 שכשהוא ערום בושתו פחותה. וכן אם \u0003ביישו בבית המרחץ\u0004 — \u0003חייב,\u0004 \u0003ו\u0004אולם \u0003אינו דומה ביישו בבית המרחץ לביישו בשוק,\u0004 כלומר, מקום ציבורי בו מהלכים אנשים.","ומבררים את הברייתא: \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ביישו ערום\u0004 — \u0003חייב.\u0004 ושואלים: וכי \u0003ערום בר\u0004 \u0005[בן]\u0006 \u0003בושת הוא?\u0004 הרי הוא עכשיו נמצא במצב שאי אפשר לבייש אותו! \u0003אמר רב פפא: מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"ערום\"\u0004 שאמרנו? — \u0003דאתא זיקא כרכינהו למאניה\u0004 \u0005[שבאה רוח\u0006 ו\u0005הרימה את בגדיו],\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003הוא דלינהו טפי וביישיה\u0004 \u0005[\u0006ו\u0005הרים אותם יותר ובייש אותו]\u0006 בכך.","עוד שנינו שאם \u0003ביישו בבית המרחץ\u0004 — \u0003חייב.\u0004 ושואלים: וכי אדם הנמצא ב\u0003בית המרחץ בר\u0004 \u0005[בן]\u0006 \u0003בושת הוא?\u0004 האם מקום זה הוא מקום שמתביישים בו באופן של הסרת בגדים? \u0003אמר רב פפא:\u0004 כאן מדובר כ\u0003שביישו\u0004 לא בבית המרחץ ממש אלא \u0003על גב\u0004 (שפת) \u0003הנהר,\u0004 שאף שרוחצים שם ומתפשטים — נוהגים שם ביתר צניעות.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אבא בר ממל: ביישו\u0004 את האדם כשהוא \u0003ישן, ומת\u0004 אותו האיש שביישו אותו, בתוך שנתו, ולא ידע כלל שביישוהו \u0003מהו\u0004 הדין? ושואלים: \u0003מאי קמבעיא ליה\u0004 \u0005[מה נשאלה לו],\u0006 מה הם צדדי השאלה הזו? \u0003אמר רב זביד, הכי קמבעיא ליה\u0004 \u0005[כך נשאלה לו]:\u0006 האם תשלום בושת \u0003משום כיסופא\u0004 \u0005[בושה],\u0006 \u0003הוא\u0004 שהוא מתבייש וסובל מחמת מה שביזהו קודם, \u0003והא מית ליה ולית ליה כיסופא\u0004 \u0005[והרי מת לו ואין לו בושה],\u0006 שלא ידע כלל שביישו אותו. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003משום זילותא\u0004 \u0005[זלזול\u0006 פגיעה בכבודו\u0005]\u0006 בפני אנשים אחרים \u0003הוא,\u0004 \u0003והא אוזליה\u0004 \u0005[והרי זלזל בו]?\u0006","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ממה ששנינו בברייתא, \u0003ר' מאיר אומר: חרש וקטן יש להן\u0004 תשלומי \u0003בושת, שוטה אין לו בושת.\u0004 ומעתה נברר: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שהוא \u0003משום זילותא, היינו דקתני\u0004 \u0005[זהו ששנה]\u0006 \u0003קטן,\u0004 שאף על פי שאינו מתבייש — יש בו זלזול, \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 שהוא \u0003משום כיסופא\u0004 \u0005[בושה]\u0006 וכי \u0003קטן בר\u0004 \u0005[בן]\u0006 \u0003בושת הוא?\u0004","ודוחים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 אתה אומר, \u0003משום זילותא\u0004 \u0005[זלזול]?\u0006 \u0003אפילו שוטה נמי\u0004 \u0005[גם כן]!\u0006 \u0003אמרי\u0004 \u0005[אומרים]\u0006 על כך: אדם שהוא \u0003שוטה\u0004 — \u0003אין לך בושת גדולה מזו,\u0004 כלומר, אי אפשר לזלזל בו, שמחמת שטותו הוא כבר מזולזל כמה שאפשר.","וחוזרים ואומרים: \u0003מכל מקום ניפשוט מינה\u0004 \u0005[נפתור מכאן]\u0006 ש\u0003משום זילותא\u0004 \u0005[זלזול]\u0006 \u0003הוא,\u0004 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003משום כיסופא\u0004 \u0005[בושה],\u0006 וכי \u0003קטן בר כיסופא\u0004 \u0005[בן בושה]\u0006 \u0003הוא?\u0004 וראיה זו דוחים: כפי ש\u0003אמר רב פפא,\u0004 שמדובר בקטן \u0003דמיכלמו ליה ומיכלם\u0004 \u0005[שמביישים אותו ומתבייש],\u0006 \u0003הכא נמי דמיכלמו ליה ומיכלם\u0004 \u0005[כאן\u0006 בברייתא זו \u0005גם כן מדובר בקטן\u0006 \u0005שמביישים אותו ומתבייש].\u0006 זו היתה שיטת רב זביד בהבנת שאלתו של ר' אבא בר ממל.","ואילו \u0003רב פפא אמר: הכי קמבעיא ליה\u0004 \u0005[כך נשאלה לו],\u0006 זו היתה שאלתו של ר' אבא בר ממל במי שביישוהו כשהוא ישן ומת אחר כך: האם תשלום בושת רגיל הוא \u0003משום כיסופא דידיה\u0004 \u0005[בושה שלו עצמו]\u0006 \u0003הוא,\u0004 \u0003והא מיית ליה\u0004 \u0005[והרי\u0006 הוא \u0005מת לו\u0006 ולא התבייש\u0005],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003משום בושת משפחה\u0004 ואם כן צריכים לתת דמי בושתו לבני המשפחה?","ומציעים פתרון: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בברייתא: \u0003חרש וקטן יש לו\u0004 תשלומי \u0003בושת, שוטה אין לו\u0004 תשלומי \u0003בושת.\u0004 ומעתה נברר: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 \u0003משום בושת משפחה, היינו דקתני\u0004 \u0005[זהו ששנה]\u0006 \u0003קטן\u0004 שיש לו בושת, משום שבני משפחתו מתביישים מכך. \u0003אלא אי אמרת\u0004 \u0005[אם אתה]\u0006 שהוא \u0003משום כיסופא דידיה\u0004 \u0005[בושה שלו],\u0006 וכי \u0003קטן בר\u0004 \u0005[בן]\u0006 \u0003בושת הוא?\u0004","ודוחים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 אתה אומר? \u0003משום בושת\u0004 של \u0003בני משפחה?\u0004 אם כן \u0003אפילו\u0004 בושתו של \u0003שוטה נמי\u0004 \u0005[גם כן]\u0006 ישלמו משום בושת משפחתו! ומשיבים: \u0003שוטה\u0004 — \u0003אין לך בושת גדולה מזו.\u0004","וחוזרים ושואלים: \u0003מכל מקום ניפשוט מינה\u0004 \u0005[נפתור מכך]\u0006 ש\u0003משום בושת משפחה, דאי\u0004 \u0005[שאם]\u0006 \u0003משום כיסופא\u0004 \u0005[בושה],\u0006 וכי \u0003קטן בר כיסופא\u0004 \u0005[בן בושה]\u0006 \u0003הוא? אמר רב פפא: אין\u0004 \u0005[כן],\u0006 מדובר פה בקטן \u0003דמיכלמו ליה ומיכלם\u0004 \u0005[שמביישים אותו ומתבייש].\u0006","ומוסיפים: \u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אומר: חרש יש לו בושת, שוטה אין לו בושת, קטן\u0004 — \u0003פעמים יש לו, פעמים אין לו.\u0004 כיצד יש להסביר דבר זה? \u0003הא דמיכלמו ליה ומיכלם\u0004 \u0005[זה\u0006 שיש לו הוא מי \u0005שמביישים אותו ומתבייש],\u0006 \u0003הא דמיכלמו ליה ולא מיכלם\u0004 \u0005[זה\u0006 שאין לו הוא מי \u0005שמביישים אותו ואינו מתבייש]\u0006 ובמקרה זה אין צריך לתת לו דמי בושת.","שנינו במשנה שם: \u0003המבייש את הסומא\u0004 — חייב בבושת. ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 היא ש\u0003לא כ\u0004שיטת \u0003ר' יהודה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: סומא\u0004 שבייש אדם \u0003אין לו\u0004 (עליו) תשלומי \u0003בושת, וכך היה ר' יהודה פוטר\u0004 את הסומא \u0003מ\u0004להיכלל בכלל \u0003חייבי גליות\u0004 אם רצח בשוגג \u0003ומחייבי מלקיות ומחייבי מיתות בית דין\u0004 אם עבר עבירות כאלה שפיקח חייב עליהם עונשים אלה.","ומבררים: \u0003מאי טעמא\u0004 \u0005[מהו הטעם]\u0006 של \u0003ר' יהודה\u0004 לענין בושת — \u0003גמר\u0004 \u0005[למד]\u0006 בגזירה שווה \u0003\"עינך\" \"עינך\" מעדים זוממין,\u0004 שנאמר בבושת \"לא תחוס עינך\" (דברים כה, יב) ונאמר בעדים זוממים \"ולא תחוס עינך\" (דברים יט, כא) ללמדנו: \u0003מה התם\u0004 \u0005[שם]\u0006 בדין עדים זוממים \u0003סומין לא\u0004 נכללים, שהרי אם סומים הם לא ראו דבר ואינם יכולים להעיד, \u0003אף הכא\u0004 \u0005[כאן]\u0006 \u0003סומין לא\u0004 בכלל דין בושת.","ומסבירים: \u0003מחייבי גליות,\u0004 מדוע ר' יהודה פוטר סומא? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב ברוצח בשגגה שגולה: \u0003\"בלא ראות\"\u0004 (במדבר לה, כג), ומלשון זה למדו — \u0003פרט לסומא,\u0004 אלו \u0003דברי ר' יהודה. ר' מאיר אומר:\u0004 להיפך, בא הכתוב \u0003לרבות את הסומא.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 למעט סומא מגלות? \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך:\u0004 מה שנאמר בדין רוצח בשגגה \u0003\"ואשר יבא את רעהו ביער לחטב עצים\"\u0004 (דברים יט, ה) הרי זה כלל, \u0003ו\u0004בכלל זה \u0003אפילו סומא, כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"בלא ראות\"\u0004 (במדבר לה, כג) \u0003למעוטי\u0004 \u0005[למעט]\u0006 את הסומא.","ושואלים: \u0003ור' מאיר\u0004 מה הוא סבור? — \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"בלא ראות\" למעוטי\u0004 \u0005[למעט]\u0006 מי שאינו רואה, \u0003וכתב רחמנא\u0004 \u0005[וכתבה התורה]\u0006 גם \u0003\"\u0004אשר יכה את רעהו \u0003בבלי דעת\"\u0004 (דברים יט, ד), \u0003למעוטי\u0004 \u0005[למעט]\u0006 סומא, שהרי סומא בכל מקרה אינו יודע היכן חבירו, אם כן \u0003הוי\u0004 \u0005[הרי זה]\u0006 \u0003מיעוט אחר מיעוט,\u0004 \u0003ו\u0004כלל בידינו: \u0003אין מיעוט אחר מיעוט אלא לרבות,\u0004 ולכן אף סומא בכלל דין גלות.","ושואלים: \u0003ור' יהודה\u0004 מה אומר הוא על כך? ומסבירים: לדעתו הכתוב \u0003ההוא \"בבלי דעת\"\u0004 אין עניינו למעט מי שאינו יודע כגון רואה, אלא \u0003פרט למתכוין הוא דאתא\u0004 \u0005[שבא],\u0006 שמי שאכן התכוון להרוג אבל לא אדם זה אלא אדם אחר — אינו גולה.","ושבים להסביר את שיטת ר' יהודה: \u0003חייבי מיתות בית דין\u0004 מנין שאין הסומא חייב? — \u0003אתיא\u0004 \u0005[באה]\u0006 נלמדת הלכה זו בגזירה שווה \u0003\"רצח\"\u0004 שנאמר שחייב מיתה (\"וימות רוצח הוא מות יומת הרוצח\". במדבר לה, טז) מ\u0003\"רצח\"\u0004 שנאמר ב\u0003חייבי גליות\u0004 (\"ונס שמה רוצח\". במדבר לה, יא).","\u0003חייבי מלקיות\u0004 מניין שסומא פטור לדעת ר' יהודה? — \u0003אתיא\u0004 \u0005[באה]\u0006 נלמדת הלכה דזו בגזירה שווה של \u0003\"רשע\" \"רשע\" מחייבי מיתות בית דין,\u0004 שנאמר בחייבי מלקות \"והיה אם בן הכות הרשע\" (דברים כה, ב) ונאמר בחייבי מיתות בית דין \"אשר הוא רשע למות\" (במדבר לה, לא).","ומציעים עוד בשיטת ר' יהודה בדין סומא, \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003ר' יהודה אומר: סומא אין לו בושת,\u0004"],["\u0003וכן היה ר' יהודה פוטרו\u0004 את הסומא \u0003מכל דינים\u0004 (דיני ממונות) \u0003שבתורה.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 בענין זה? — \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ושפטו העדה בין המכה ובין גאל הדם על המשפטים האלה\"\u0004 (במדבר לה, כד), ללמדנו: \u0003כל שישנו ב\u0004דין \u0003מכה\u0004 (מלקות) \u0003וב\u0004דין \u0003גואל הדם\u0004 — \u0003ישנו במשפטים\u0004 כולם, ואילו \u0003כל שאינו במכה ובגואל הדם\u0004 כגון סומא — \u0003אינו במשפטים,\u0004 שאינו בכלל ענין משפטי.","ומציעים עוד בשיטת ר' יהודה בדין סומא: \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת],\u0006 \u0003ר' יהודה אומר: סומא אין לו בושת, וכן היה ר' יהודה פוטרו מכל מצו‍ת האמורות בתורה. אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה? אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואלה המצו‍ת החקים והמשפטים\"\u0004 (ראה דברים ו, א) ללמדנו: \u0003כל שישנו במשפטים\u0004 — \u0003ישנו\u0004 גם \u0003במצו‍ת וחקים, וכל שאינו במשפטים,\u0004 כגון סומא (כאמור בברייתא הקודמת) — \u0003אינו\u0004 גם \u0003במצו‍ת וחקים.\u0004","\u0003אמר רב יוסף\u0004 שהיה עיוור: \u0003מריש הוה אמינא\u0004 \u0005[מתחילה הייתי אומר]:\u0006 \u0003מאן דאמר\u0004 \u0005[מי שיאמר]\u0006 ויקבע ש\u0003הלכה כ\u0004שיטת \u0003ר' יהודה,\u0004 ש\u0003אמר: סומא פטור מן המצו‍ת, קא עבדינא יומא טבא לרבנן\u0004 \u0005[אעשה\u0006 אז לכבוד זאת \u0005יום טוב\u0006 סעודה ומשתה \u0005לחכמים],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]?\u0006 — \u0003דלא מפקדינא וקא עבדינא\u0004 \u0005[שאיני מצווה ו\u0006בכל זאת \u0005אני עושה]\u0006 \u0003מצו‍ת.\u0004","\u0003והשתא דשמעית להא\u0004 \u0005[ו\u0006אולם \u0005עכשיו\u0006 אחרי \u0005ששמעתי את זו]\u0006 שאמר \u0003ר' חנינא,\u0004 ש\u0003אמר ר' חנינא: גדול המצווה\u0004 בדבר \u0003ועושה\u0004 אותו יותר \u0003ממי שאינו מצווה ועושה,\u0004 משום כך \u0003מאן דאמר\u0004 \u0005[מי שיאמר]\u0006 \u0003לי\u0004 ש\u0003אין הלכה כ\u0004שיטת \u0003ר' יהודה, עבדינא יומא טבא לרבנן\u0004 \u0005[אעשה\u0006 אז \u0005יום טוב לחכמים],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]?\u0006 — \u0003דכי מפקדינא אית\u0004 \u0005[שכאשר אני מצווה יש]\u0006 \u0003לי אגרא טפי\u0004 \u0005[שכר יותר]\u0006 על עשייתי את המצוות.","\u0003זה חומר\u0004 (חומרה) שיש בהלכה \u0003באדם\u0004 המזיק \u0003מבשור\u0004 המזיק, \u0003שהאדם\u0004 המזיק \u0003משלם נזק, צער, ריפוי, שבת ובושת, ומשלם דמי ולדות\u0004 אם גרם לאשה שתפיל כפי שנאמר בתורה (שמות כא, כב), \u0003ו\u0004אילו \u0003שור\u0004 שהזיק — \u0003אינו משלם אלא נזק, ופטור מדמי ולדות.\u0004","בן \u0003המכה את אביו ואת אמו ולא עשה בהן חבורה\u0004 (פצע שיש בו דם), ובמקרה זה אינו חייב מיתה, \u0003ו\u0004כן מי ש\u0003חובל בחבירו ביום הכפורים,\u0004 כיון שאינו מחוייב על מעשהו זה בעונש בדיני אדם החמור יותר — \u0003חייב בכולן,\u0004 בכל התשלומים שמשלם אדם החובל בחבירו.","\u0003החובל בעבד עברי\u0004 — \u0003חייב ב\u0004כל התשלומים \u0003כולן, חוץ מן\u0004 תשלום \u0003השבת בזמן ש\u0004העבד שחבל בו \u0003הוא שלו,\u0004 שהרי עבודתו שייכת לאדוניו, והוא עצמו האדון זה שהפסיד מבטלת עבדו ממלאכה. \u0003החובל בעבד כנעני של אחרים\u0004 — \u0003חייב בכולן. ר' יהודה אומר: אין לעבדים בושת\u0004 ולכן עבור הבושת אינו צריך לשלם.","ועוד: \u0003חרש שוטה וקטן פגיעתן רעה,\u0004 כלומר, כל מי שמגיע לידי היתקלות עימם לא טוב לו הדבר בכל אופן שהוא, כי \u0003החובל בהן\u0004 — \u0003חייב\u0004 בכל התשלומים, \u0003והם שחבלו באחרים\u0004 — \u0003פטורין,\u0004 שהרי אין הם נחשבים כבעלי דעת ואין הם בעלי אחריות למעשיהם.","וכן \u0003העבד והאשה פגיעתן רעה, החובל בהם\u0004 — \u0003חייב, והם שחבלו באחרים\u0004 — \u0003פטורין,\u0004 שהרי אין להם כעת כסף לשלם, \u0003אבל משלמין לאחר זמן,\u0004 כלומר, אין זה פטור מוחלט, אלא לשעתו. שאם \u0003נתגרשה האשה\u0004 או \u0003נשתחרר העבד\u0004 ויש להם עתה כסף משלהם — \u0003חייבין לשלם.\u0004","\u0003המכה אביו ואמו ועשה בהן חבורה, והחובל בחבירו בשבת\u0004 — \u0003פטור מ\u0004כל עונשי הממון \u0003כולן, מפני שהוא נדון בנפשו,\u0004 שחייב מיתה על מעשהו זה, ואין מענישים אותו עונש נוסף.","\u0003והחובל בעבד כנעני שלו\u0004 — \u0003פטור מכולן,\u0004 מכל תשלום של ממון לעבד, שהרי העבד קניינו הוא.","ודנים בשאלה הנוגעת לתשלום חבלה \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' אלעזר מרב: החובל בבת קטנה של אחרים,\u0004 דמי \u0003חבלה למי,\u0004 לאב או לבת?","וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003כיון דאקני ליה רחמנא\u0004 \u0005[שהקנתה לו התורה]\u0006 \u0003שבח נעורים\u0004 של בתו \u0003לאב,\u0004 שהוא מקבל את כסף קידושיה, דמי \u0003חבלה נמי דאבוה הוי\u0004 \u0005[גם כן של אביה הוא];\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 — \u0003דהא אפחתה\u0004 \u0005[שהרי הפחית אותה]\u0006 \u0003מכספה,\u0004 מערכה, שמפני החבלה שיש בה לא יתנו לו מוהר כמו שנותנים לבת שלימה ובריאה, ונמצא שהאב הוא המפסיד בזה. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003שבח נעורים הוא דאקני ליה רחמנא\u0004 \u0005[שהקנתה לו התורה],\u0006 ומדוע? — \u0003דאי בעי לממסר לה למוכה שחין מצי מסר\u0004 \u0005[ש\u0006הרי \u0005אם\u0006 הוא \u0005רוצה למסור אותה למוכה שחין יכול\u0006 הוא \u0005למסור\u0006 אותה\u0005],\u0006 ואם כן יש לו זכות בלעדית בכל מה שנוגע לקידושיה, \u0003אבל חבלה, כיון דאי בעי מתחבל\u0004 \u0005[שאם ירצה לחבול]\u0006 \u0003בה\u0004 בעצמו \u0003לא מצי חביל\u0004 \u0005[אינו יכול לחבול\u0006 בה\u0005],\u0006 שאסור לו לחבול בילדיו כשם שאסור לחבול בכל אדם, אם כן \u0003לא קנייה ליה רחמנא\u0004 \u0005[הקנתה לו התורה\u0006 זכות ממונית זו\u0005]?\u0006"],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב בתשובה: \u0003לא זכתה\u0004 ה\u0003תורה לאב\u0004 בבתו \u0003אלא שבח נעורים בלבד,\u0004 ולא דבר אחר, ולכן תשלומי הנזק יינתנו לבת. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 לשיטת רב ממה ששנינו במשנתנו: \u0003החובל בעבד עברי\u0004 — \u0003חייב בכולן, חוץ מן השבת בזמן שהוא שלו,\u0004 ואם כן, אף בתו כיון שמעשה ידיה שלו — צריך אף תשלום השבת להיות שלו! \u0003אמר אביי:\u0004 אכן, \u0003מודה רב ב\u0004תשלום ה\u0003שבת\u0004 שנותן אותו המזיק אותה לאביה, שכן \u0003מעשה ידיה עד שעת בגרות דאבוה הוי\u0004 \u0005[של אביה הם]\u0006 ודמי השבת — דמי ביטול מעשה ידיה הם.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 לשיטת רב ממה ששנינו בברייתא: אב \u0003החובל בבנו גדול\u0004 — \u0003יתן לו מיד\u0004 מה שחייב לשלם לו, חבל \u0003בבנו קטן\u0004 — \u0003יעשה לו\u0004 בדמי החבלה שחייב לו \u0003סגולה\u0004 (שעניינה יבואר להלן). \u0003החובל בבתו קטנה\u0004 — \u0003פטור, ולא עוד אלא אחרים שחבלו בה\u0004 — \u0003חייבין ליתן לאביה!\u0004 ומשיבים: \u0003הכי נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003ב\u0004תשלומי \u0003שבת\u0004 בלבד, אבל לא לגבי תשלום שאר נזקים שהם ניתנים לבת.","ועל האמור בברייתא זו שהובאה עתה תמהים: \u0003ובבנו גדול\u0004 — \u0003יתן לו מיד? ורמינהו\u0004 \u0005[ומשליכים\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא אחרת: \u0003החובל בבניו ובבנותיו של אחרים,\u0004 אם היו \u0003גדולים\u0004 — \u0003יתן להם מיד\u0004 את תשלומי החבלה, \u0003קטנים\u0004 — \u0003יעשה להם סגולה. בבניו ובבנותיו שלו\u0004 (ומשמע, אפילו גדולים) — \u0003פטור!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 בברייתא ששנינו שפטור מדובר \u0003כש\u0004הבנים הגדולים \u0003סמוכים על שלחנו,\u0004 כלומר, שמתפרנסים וניזונים ממנו, \u0003כאן\u0004 ששנינו שחייב מדובר \u0003כשאין\u0004 הבנים הגדולים \u0003סמוכין על שלחנו.\u0004","על תירוץ זה מקשים: \u0003במאי אוקימתא לקמייתא\u0004 \u0005[במה העמדת את\u0006 הברייתא \u0005הראשונה\u0006 שחייב\u0005]?\u0006 — \u0003בשאין סמוכין על שלחנו; אי הכי, אימא סיפא\u0004 \u0005[אם כך, אמור\u0006 את \u0005סופה]:\u0006 \u0003החובל בבתו הקטנה\u0004 — \u0003פטור, ולא עוד אלא אחרים שחבלו בה\u0004 — \u0003חייבין ליתן לאביה.\u0004 ואם מדובר כאן שאינו מפרנס את בתו הלא \u0003לדידה בעי למיתב\u0004 \u0005[לה עצמה צריך לתת]\u0006 \u0003לה\u0004 את התשלום, \u0003דבעיא מזוני\u0004 \u0005[שצריכה\u0006 היא \u0005מזונות],\u0006 שהרי אינה סמוכה על שולחן אביה!","\u0003ואפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003יכול הרב לומר לעבד \"עשה עמי\u0004 (עבוד בשבילי) \u0003ואיני זנך\"\u0004 לפי שאיני חייב לפרנסך, \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים \u0003בעבד כנעני, דאמר ליה\u0004 \u0005[ש\u0006יכול האדון \u0005לומר לו]:\u0006 \u0003עביד עבידתא כולי יומא\u0004 \u0005[עבוד עבודה כל היום]\u0006 \u0003ולאורתא זיל סחר\u0004 \u0005[ולערב לך חזר]\u0006 על הפתחים לבקש צדקה \u0003ואכול\u0004 ממה שיתנו לך, \u0003אבל עבד עברי, דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"כי טוב לו עמך\"\u0004 (דברים טו, טז), ולמדו חכמים מכאן שצריך להיות שווה \u0003עמך במאכל, עמך במשתה\u0004 — \u0003לא,\u0004 וחייב לספק לו מזונות, ו\u0003כל שכן בתו!\u0004","ומשיבים: \u0003כ\u0004דרך ש\u0003אמר רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב עולא\u0004 בקשר לענין דומה: \u0003לא נצרכה\u0004 הלכה זו \u0003אלא להעדפה,\u0004 כלומר, לסכום העודף על מזונותיה ההכרחיים. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003לא נצרכה אלא להעדפה,\u0004 שאותו מקבל האב מן החובל בבתו הקטנה.","ועוד שואלים על דרך זו של יישוב הסתירה בין הברייתות: \u0003במאי אוקימתא לבתרייתא\u0004 \u0005[במה העמדת את\u0006 הברייתא \u0005האחרונה]\u0006 — \u0003בסמוכין על שלחנו,\u0004 ואמרנו בברייתא ש\u0003גדולים\u0004 — \u0003יתן להם מיד, קטנים\u0004 — \u0003יעשה להם סגולה, אמאי\u0004 \u0005[מדוע]\u0006 יעשה להם סגולה? \u0003לאביהם בעי למיתבי\u0004 \u0005[צריך\u0006 הוא \u0005לתת]!\u0006","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003כי קא קפיד\u0004 \u0005[כאשר\u0006 האב \u0005מקפיד]\u0006 לקבל דבר השייך לילדיו, הרי זה דווקא \u0003במידי דקא חסר\u0004 \u0005[בדבר ש\u0006הוא \u0005חסר\u0006 ממנו\u0005]\u0006 שהוא מפסיד בגללו כגון במקרה שחבל בבניו, שיצטרך לשלם לבניו, ואולם \u0003במידי דאתא מעלמא\u0004 \u0005[בדבר שבא מן העולם,\u0006 מן החוץ\u0005]\u0006 שחבלו בהם אחרים — \u0003לא קפיד\u0004 \u0005[מקפיד].\u0006","ומקשים על כך: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מציאה דמעלמא קאתי להו\u0004 \u0005[שמהחוץ באה להם]\u0006 \u0003וקא קפיד\u0004 \u0005[ו\u0006האב \u0005מקפיד]\u0006 על כך ולכן אומרים שמציאת הקטנים לאביהם! \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003רווחא דקאתי להו מעלמא, ולית להו צערא דגופייהו בגווה\u0004 \u0005[רווח שבא להם מהחוץ, ואין להם צער של גופם בו]\u0006 — \u0003קפיד\u0004 \u0005[מקפיד]\u0006 האב לקבל, \u0003אבל חבלה\u0004 של ילדיו \u0003דאית להו צערא דגופייהו\u0004 \u0005[שיש להם צער של גופם\u0006 בכך\u0005]\u0006 \u0003ומעלמא קאתי להו\u0004 \u0005[ו\u0006גם \u0005מהחוץ בא להם]\u0006 — \u0003לא קפיד\u0004 \u0005[מקפיד]\u0006 לקבל מילדיו.","ומקשים: \u0003והא התם\u0004 \u0005[והרי שם]\u0006 בברייתא הראשונה מדובר במקרה \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003לה\u0004 לבתו \u0003צערא דגופא\u0004 \u0005[צער הגוף]\u0006 \u0003ומעלמא קאתי\u0004 \u0005[ומהחוץ בא]\u0006 \u0003לה, וקא קפיד\u0004 \u0005[ו\u0006הוא \u0005מקפיד]\u0006 על קבלת תשלומיה! \u0003דקתני\u0004 \u0005[\u0006כפי \u0005ש\u0006הוא \u0005שונה]:\u0006 \u0003ולא עוד אלא אחרים שחבלו בה\u0004 — \u0003חייבין ליתן לאביה!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003התם דגברא קפדנא\u0004 \u0005[שם שאיש קפדן]\u0006 \u0003הוא,\u0004 וראיה לדבר \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אין\u0004 ילדיו \u0003סמוכין על שלחנו\u0004 ואינו דואג למזונותיהם, איש כזה \u0003אפילו במידי דאתי להו מעלמא קפיד\u0004 \u0005[בדבר שבא להם מבחוץ מקפיד].\u0006 ואולם \u0003הכא\u0004 \u0005[כאן],\u0006 בברייתא זו, \u0003דלאו גברא קפדנא\u0004 \u0005[שלא אדם קפדן]\u0006 \u0003הוא, דהא\u0004 \u0005[שהרי]\u0006 ילדיו \u0003סמוכין על שלחנו, כי קא קפיד\u0004 \u0005[כאשר הוא מקפיד]\u0006 — הרי זה \u0003במידי דקא חסר ליה\u0004 \u0005[בדבר שהוא חסר בו],\u0006 אבל \u0003במידי דאתי להו מעלמא\u0004 \u0005[בדבר שבא להם מן החוץ]\u0006 — \u0003לא קפיד\u0004 \u0005[מקפיד].\u0006","ומסבירים עוד: שנינו בשתי הברייתות שיעשה לבניו הקטנים בכסף התשלומים המגיע להם סגולה, ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירושה של \u0003סגולה\u0004 זו? \u0003רב חסדא אמר:\u0004 שיקנה להם בכסף זה \u0003ספר תורה, רבה בר רב הונא אמר:\u0004 שיקנה להם \u0003דיקלא דאכיל מיניה תמרי\u0004 \u0005[דקל שיאכל\u0006 הילד \u0005ממנו תמרים].\u0006 ומעירים כי אותם הדברים שנדונו על ידי אמוראי בבל, נדונו גם בארץ ישראל.","\u0003וכן אמר ריש לקיש\u0004 כדברי רב: \u0003לא זכתה תורה לאב אלא שבח נעורים בלבד, ור' יוחנן אמר: אפילו פציעה.\u0004","ותוהים: \u0003פציעה\u0004 שאין בה אובדן כושר עבודה, כחבלה, \u0003סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר שיזכה בזה האב? והרי \u0003אפילו ר' אלעזר לא קמיבעיא ליה\u0004 \u0005[נשאלה לו],\u0006 לא היה לו ספק לגבי זכות האב בתשלומי בתו \u0003אלא\u0004 לגבי \u0003חבלה,\u0004"],["\u0003דאפחתה\u0004 \u0005[שהפחיתה]\u0006 \u0003מכספה,\u0004 כלומר, מערכה הכספי שיינתן לו עבורה, \u0003אבל פציעה\u0004 ש\u0003לא אפחתה\u0004 \u0005[הפחיתה]\u0006 \u0003מכספה לא קמיבעיא ליה\u0004 \u0005[נשאלה לו]!\u0006","\u0003אמר ר' יוסי בר חנינא:\u0004 כאן מדובר \u0003שפצעה בפניה, ו\u0004פציעה שכזו \u0003אפחתה\u0004 \u0005[הפחיתה]\u0006 \u0003מכספה,\u0004 ממה שיכול לקבל עבורה.","שנינו במשנה: \u0003החובל בעבד כנעני של אחרים\u0004 — \u0003חייב\u0004 בכל התשלומים. ור' יהודה סבור שאין צריך לשלם במקרה זה בושת. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה?\u0004 ומסבירים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 שממנו למדים דין בושת: \u0003\"כי ינצו אנשים יחדו איש ואחיו\"\u0004 (דברים כה, יא), ומלשון הכתוב נלמד שהוא מדבר רק \u0003במי שיש לו\u0004 יחס של \u0003אחוה\u0004 בישראל, \u0003יצא עבד שאין לו אחוה\u0004 עם ישראל, שאינו נכלל בקהל ישראל, ולכן גם אינו בכלל אלה שמגיע תשלום על בושתם. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 סבורים: הריהו נחשב בכלל אחוה בישראל לענין בושת משום ש\u0003אחיו הוא במצו‍ת,\u0004 שהרי גם העבד הכנעני צריך לקיים את רוב המצוות.","ושואלים: \u0003אלא מעתה, ל\u0004פי נימוקו זה של \u0003ר' יהודה\u0004 שאין העבד הכנעני נחשב אחיו של ישראל — \u0003זוממי עבד,\u0004 אנשים שהעידו עדות שקר שעבר עבירה שיש בה חיוב מיתה \u0003לא יהרוגו\u0004 אותם בית דין, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועשיתם לו כאשר זמם לעשות לאחיו\"\u0004 (דברים יט, יט) והעבד אינו בכלל אחיו! \u0003אמר רבא אמר רב ששת, אמר קרא\u0004 \u0005[הכתוב]\u0006 באותו ענין: \u0003\"ובערת הרע מקרבך\"\u0004 (דברים יט, יט), וכוונתו שיש לבער את עושה הרשעה \u0003מכל מקום,\u0004 לרבות מי שזמם להרוג עבד.","ושואלים מצד שני: \u0003אלא מעתה, לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 שאומרים שעבד כנעני הרי הוא בכלל אחוה בישראל, \u0003עבד יהא כשר למלכות\u0004 שנאמר בה \"מקרב אחיך תשים עליך מלך\" (דברים יז, טו), ולדעתם הלא הוא בכלל \"אחיך\"! \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 \u0003תיקשי\u0004 \u0005[יקשה]\u0006 \u0003לך\u0004 דינו של \u0003גר לדברי הכל,\u0004 בין לחכמים ובין לר' יהודה, שמדוע אומרים שאין ממנים גר למלך והרי יש לו אחוה בישראל? \u0003אלא,\u0004 בענין זה \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"מקרב אחיך\u0004 תשים עליך מלך \u0003\",\u0004 וכוונתו \u0003ממובחר שבאחיך,\u0004 ומטעם זה פסולים גרים ועבדים.","ועוד מקשים: \u0003אלא מעתה, לרבנן\u0004 \u0005[ל\u0006דברי \u0005חכמים]\u0006 \u0003יהא עבד כשר לעדות, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והנה עד שקר העד שקר ענה באחיו\"\u0004 (דברים יט, יח), ואם עבד הוא בכלל אחוה בישראל, מדוע לא יוכל להעיד?","\u0003אמר עולא: עדות לא מצית אמרת\u0004 \u0005[אין אתה יכול לומר]\u0006 שיהא כשר בה עבד, שכן \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 פסילת \u0003עדות\u0004 של עבד \u0003בקל וחומר מאשה: ומה אשה שהיא ראויה לבא בקהל\u0004 להינשא לכל בן ישראל — \u0003פסולה לעדות, עבד שאינו ראוי לבא בקהל\u0004 שהרי הוא אסור בבת ישראל — \u0003אינו דין שפסול לעדות?\u0004","ודוחים: \u0003מה לאשה\u0004 שיש בה צד של קולה \u0003שכן אינה ראויה ל\u0004מצות \u0003מילה, תאמר בעבד שהוא ראוי למילה!\u0004 ומשיבים: \u0003קטן יוכיח, שישנו ב\u0004מצות \u0003מילה\u0004 \u0003ו\u0004עדיין \u0003פסול\u0004 הוא \u0003לעדות.\u0004","ומשיבים: \u0003מה לקטן שאינו\u0004 חייב \u0003במצו‍ת, תאמר בעבד שהוא\u0004 חייב \u0003ב\u0004רוב ה\u0003מצו‍ת?\u0004 ומשיבים: \u0003אשה תוכיח, שישנה ב\u0004חיוב \u0003מצות ופסולה לעדות.\u0004","\u0003וחזר הדין,\u0004 לפי זה יוצא שהדיון הולך וחוזר: \u0003לא ראי זה כראי זה ולא ראי זה כראי זה,\u0004 שיש צדדים שונים ונימוקים שונים בין לפסול ובין להכשיר, ואולם \u0003הצד השוה שבהן\u0004 — \u0003שכן\u0004 גם אשה וגם קטן \u0003אינן\u0004 חייבים \u0003בכל המצו‍ת ופסולין להעיד, אף אני אביא\u0004 (אוסיף) בדין זה \u0003את העבד\u0004 — \u0003ש\u0004אף הוא \u0003אינו\u0004 חייב \u0003בכל המצו‍ת ופסול להעיד.\u0004","ומקשים שוב: \u0003מה להצד השוה שבהם שכן אינו איש,\u0004 שלא אשה ולא קטן קרויים \"איש\", ולכן פסולים לעדות, \u0003תאמר בעבד שהוא\u0004 נקרא \u0003\"איש\"\u0004?","\u0003 אלא\u0004 יש להביא נימוק אחר לפסולו של עבד לעדות: \u0003תיתי\u0004 \u0005[תבוא\u0006 תילמד\u0005]\u0006 ההלכה הזו \u0003מגזלן,\u0004 כשם שהוא פסול לעדות כך עבד פסול לעדות. ומשיבים: \u0003מה לגזלן שכן מעשיו\u0004 הרעים \u0003גרמו לו, תאמר בעבד שאין\u0004 (שלא) \u0003מעשיו גרמו לו?\u0004","\u0003אלא תיתי\u0004 \u0005[תבוא\u0006 תילמד\u0005]\u0006 ההלכה הזו \u0003מגזלן ומחד מהנך\u0004 \u0005[ומאחד מאלה],\u0006 מאשה או מקטן.","\u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא אמר\u0004 טעם אחר לפסולו של עבד לעדות: מה ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"לא יומתו אבות על בנים\"\u0004 (דברים כד, טז), כוונתו: \u0003לא יומתו\u0004 אנשים מישראל, וכן לא ייענשו בשאר עונשים \u0003על פי\u0004 עדותם של מי שהם \u0003אבות שאין להם חייס\u0004 \u0005[ייחוס]\u0006 של \u0003בנים,\u0004 כלומר, שאין בניהם מתייחסים אחריהם שאלו הם העבדים. \u0003דאי סלקא דעתך\u0004 \u0005[שאם יעלה על דעתך]\u0006 לומר שמשמעות הפסוק הזה \u0003כדאמרינן\u0004 \u0005[כמו שאנו אומרים,\u0006 מפרשים אותו\u0005]\u0006 כפשוטו ש\u0003לא יומתו אבות על בנים\u0004 — \u0003ב\u0004גלל \u0003עדות\u0004 של \u0003בנים, לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"לא יומתו אבות על בניהם\", מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"בנים\"? שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003לא יומתו על פי אבות שאין להם חייס\u0004 \u0005[ייחוס]\u0006 \u0003בנים.\u0004","ומקשים: \u0003אלא מעתה,\u0004 לפי אותו הסבר, מה שנאמר בהמשך כתוב זה \u0003\"ובנים לא יומתו על אבות\"\u0004 (דברים כד, טז), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תפרש: \u0003לא יומתו\u0004 אנשים \u0003על פי\u0004 עדותם של \u0003בנים שאין להם חייס\u0004 \u0005[ייחוס]\u0006 \u0003אבות? אלא\u0004 מעתה לפי זה \u0003גר הכי נמי\u0004 \u0005[כך גם כן]\u0006 נאמר שהוא \u0003פסול לעדות\u0004 שהרי אין לו ייחוס אבות, שמשעה שהתגייר אין הוא מתייחס ואינו נחשב כבן לאביו!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003הכי השתא\u0004 \u0005[כך עכשיו\u0006 כיצד אתה משווה\u0005]?!\u0006 \u0003גר, נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003אין לו חייס\u0004 \u0005[ייחוס]\u0006 \u0003למעלה\u0004 לאבותיו שלו, אבל \u0003למטה\u0004 (לבניו וצאצאיו) \u0003יש לו חייס\u0004 \u0005[ייחוס],\u0006 \u0003לאפוקי\u0004 \u0005[להוציא\u0006 למעט\u0005]\u0006 \u0003עבד\u0004 ש\u0003אין לו\u0004 כלל \u0003חייס\u0004 \u0005[ייחוס],\u0006 \u0003לא למעלה ולא למטה.\u0004","ויש הוכחה לדבר, שכן \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003גר פסול לעדות,\u0004 אם כן \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"לא יומתו אבות על בניהם\" לכדאמרינן\u0004 \u0005[לכפי שאמרנו,\u0006 פירשנו\u0005]:\u0006 \u0003לא יומתו\u0004 אבות \u0003בעדות בנים, ונכתוב רחמנא\u0004 \u0005[ושתכתוב התורה]\u0006 \u0003\"ובנים לא יומתו על אבות\", דשמעת מינה תרי\u0004 \u0005[שתלמד מכאן שתי\u0006 הלכות\u0005]:\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 — ש\u0003לא יומתו בנים בעדות אבות, ואידך\u0004 \u0005[והאחרת],\u0006 — ש\u0003לא יומתו על פי בנים שאין להם חייס\u0004 \u0005[ייחוס]\u0006 \u0003אבות,\u0004 כלומר, גר,","\u0003ו\u0004אילו דינו של \u0003עבד נפקא ליה\u0004 \u0005[יצא לו,\u0006 יילמד\u0005]\u0006 \u0003בקל וחומר מגר\u0004 ובאופן זה: \u0003ומה גר\u0004 ש\u0003למעלה\u0004 מצד אבותיו \u0003הוא\u0004 ש\u0003אין לו חייס\u0004 \u0005[ייחוס],\u0006 \u0003אבל למטה\u0004 מצד בניו \u0003יש לו חייס\u0004 \u0005[ייחוס]\u0006 — \u0003פסול לעדות, עבד שאין לו חייס\u0004 \u0005[ייחוס]\u0006 כלל \u0003לא למעלה ולא למטה\u0004 — \u0003אינו דין שיהא פסול לעדות?\u0004","\u0003אלא מדכתב רחמנא\u0004 \u0005[ממה שכתבה התורה]\u0006 לא כך אלא \u0003\"לא יומתו אבות על בנים\", משמע\u0004 מכאן ללמדנו: \u0003לא יומתו על פי אבות שאין לו חייס\u0004 \u0005[ייחוס]\u0006 \u0003בנים, שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003עבד שאין לו חייס\u0004 \u0005[ייחוס]\u0006 \u0003לא למעלה ולא למטה\u0004 — \u0003הוא\u0004 ש\u0003פסול לעדות, אבל גר כיון\u0004 ש\u0003יש לו חייס\u0004 \u0005[ייחוס]\u0006 \u0003למטה\u0004 — \u0003כשר לעדות.\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"ובנים לא יומתו על אבותיהם\", למה לי\u0004 לאיזה ענין \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003\"ובנים לא יומתו על אבות\",\u0004 ש\u0003משמע\u0004 הכתוב לפי זה: \u0003לא יומתו על פי בנים שאין להם חייס\u0004 \u0005[ייחוס]\u0006 \u0003אבות?\u0004 יש לומר: \u0003איידי\u0004 \u0005[מתוך]\u0006 ש\u0003כתב \"לא יומתו אבות על בנים\", כתב נמי\u0004 \u0005[גם כן]\u0006 באותו סגנון \u0003\"ובנים לא יומתו על אבות\".\u0004","שנינו במשנה: \u0003חרש שוטה וקטן פגיעתן רעה,\u0004 שהחובל בהם — חייב, והם שחבלו באחרים — פטורים. מסופר: \u0003אימיה\u0004 \u0005[אמו]\u0006 של \u0003רב שמואל בר אבא מ\u0004העיר \u0003הגרוניא הות נסיבא ליה\u0004 \u0005[היתה נשואה לו]\u0006 \u0003לר' אבא,\u0004 לאחר הנישואין \u0003כתבתינהו לנכסי\u0004 \u0005[כתבה את נכסיה]\u0006 \u0003לרב שמואל בר אבא ברה\u0004 \u0005[בנה]\u0006 שיזכה בהם. \u0003בתר דשכיבא\u0004 \u0005[אחרי שמתה]\u0006 האם,"],["\u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב שמואל בר אבא קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' ירמיה בר אבא\u0004 לתבוע את נכסי אמו שניתנו לו, \u0003אוקמיה בנכסי\u0004 \u0005[העמידו,\u0006 נתן לו זכות, \u0005בנכסים]\u0006 לפי השטר. \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003ר' אבא\u0004 בעלה של האם \u0003אמרה למילתא קמיה\u0004 \u0005[אמר את הדבר לפני]\u0006 \u0003רב הושעיא, אזל\u0004 \u0005[הלך]\u0006 \u0003רב הושעיא אמרה קמיה\u0004 \u0005[אמר אותה לפני]\u0006 \u0003רב יהודה. אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: האשה שמכרה בנכסי מלוג\u0004 (נכסים שלה שהבעל אוכל את פירותיהם) \u0003בחיי בעלה ומתה\u0004 — דין הוא ש\u0003הבעל מוציא\u0004 אותם \u0003מיד הלקוחות\u0004 (הקונים). ואף מתנה זו שנתנה לבנה — כמכר הוא, והכל שייך לבעל.","\u0003אמרוה\u0004 את ההלכה הזו של רב יהודה \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' ירמיה בר אבא\u0004 שפסק לא כך, שכן נתן הנכסים ביד רב שמואל, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנא מתניתא ידענא\u0004 \u0005[אני\u0006 את ה\u0005משנה אני יודע]\u0006 ועליה אני סומך, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכותב נכסיו לבנו\u0004 שיזכה בהם הבן \u0003לאחר מותו\u0004 וכל עוד האב חי הוא יהנה מפירות הנכסים — \u0003הבן אינו יכול למכור\u0004 את הנכסים הללו \u0003מפני שהן\u0004 עדיין \u0003ברשות האב,\u0004 \u0003והאב אינו יכול למכור מפני שהן כתובין\u0004 ושייכים \u0003לבן.\u0004 אם \u0003מכר האב\u0004 — הריהם \u0003מכורים\u0004 לקונה, לאכול מפירותיהם \u0003עד שימות\u0004 האב. אם \u0003מכר הבן\u0004 את הנכסים — \u0003אין לו ללוקח\u0004 בהם דבר \u0003עד שימות האב.\u0004","ומכאן נלמד: \u0003כי מיית\u0004 \u0005[כאשר ימות]\u0006 ה\u0003אב מיהא אית ליה\u0004 \u0005[בכל אופן יהיה לו]\u0006 \u0003ללוקח\u0004 נכס זה, \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003מת הבן בחיי אב,\u0004 ש\u0003לא אתו\u0004 \u0005[באו]\u0006 כלל \u0003לידי הבן.\u0004","ומסבירים ביתר פירוט את דבריו של ר' ירמיה בר אבא, שאנו מפרשים משנה זו \u0003כ\u0004דעת \u0003ר' שמעון בן לקיש,\u0004 ש\u0003אמר: לא שנא\u0004 \u0005[שונה]\u0006 אם \u0003מת הבן בחיי האב\u0004 ש\u0003לא אתו\u0004 \u0005[באו]\u0006 הנכסים כלל \u0003לידיה\u0004 \u0005[לידו]\u0006 של ה\u0003בן,\u0004 \u0003לא שנא\u0004 \u0005[שונה]\u0006 אם \u0003מת האב בחיי הבן, דאתו לידיה\u0004 \u0005[שבאו לידו]\u0006 של ה\u0003בן,\u0004 בכל אופן \u0003קנה\u0004 ה\u0003לוקח.\u0004","\u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בהלכה הנוגעת למשנה בכותב נכסיו לבנו. \u0003מכר הבן\u0004 את ירושתו \u0003בחיי האב, ומת הבן בחיי האב,\u0004 ואחר כך מת האב, \u0003ר' יוחנן אמר: לא קנה לוקח, ריש לקיש אמר: קנה לוקח.\u0004","ומסבירים את טעמיהם בפירוט: \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 ש\u0003לא קנה לוקח, אמר\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 את טעמו בהסבר דבריו: \u0003כי קתני מתניתין\u0004 \u0005[כאשר שנה\u0006 ב\u0005משנתנו]\u0006 \u0003מכר הבן לא קנה לוקח עד שימות האב, וכי מיית\u0004 \u0005[וכאשר מת]\u0006 \u0003האב אית ליה\u0004 \u0005[יש לו]\u0006 \u0003ללוקח\u0004 נכס זה, מדובר ש\u0003לא מת הבן בחיי האב, דאתו\u0004 \u0005[ש\u0006כבר \u0005באו]\u0006 הנכסים לגמרי \u0003לידי הבן\u0004 כשמת האב, ומידיו עוברים הם ליד הלוקח. \u0003אבל מת הבן בחיי האב,\u0004 ש\u0003לא אתו לידיה\u0004 \u0005[באו לידיו]\u0006 של ה\u0003בן,\u0004 \u0003כי מיית\u0004 \u0005[כאשר מת]\u0006 \u0003אב נמי לית ליה\u0004 \u0005[גם כן אין לו]\u0006 \u0003ללוקח\u0004 בהם דבר.","ואומרים: \u0003אלמא קא סבר\u0004 \u0005[מכאן רואים שהוא סבור]\u0006 ש\u0003קנין פירות\u0004 שיש לאדם בדבר — \u0003כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 \u0003ו\u0004כיון שהאב אוכל את הפירות נמצא ש\u0003כי זבין\u0004 \u0005[כאשר מכר]\u0006 הבן — \u0003לאו דידיה זבין\u0004 \u0005[לא\u0006 את \u0005שלו מכר],\u0006 שהרי אינו יכול למכור את זכות אכילת הפירות, השייכת לאב.","ואילו \u0003ר' שמעון בן לקיש\u0004 ש\u0003אומר קנה לוקח,\u0004 טעמו \u0003כי קתני מתניתין\u0004 \u0005[כאשר שנה\u0006 ב\u0005משנתנו]\u0006 \u0003מכר הבן אין ללוקח עד שימות האב,\u0004 משמע: \u0003כי מיית\u0004 \u0005[כאשר ימות]\u0006 \u0003אב מיהת אית ליה\u0004 \u0005[מכל מקום יש לו]\u0006 \u0003ללוקח,\u0004 \u0003לא שנא\u0004 \u0005[שונה]\u0006 \u0003לא מת הבן בחיי האב דאתו לידיה\u0004 \u0005[שבאו לידיו]\u0006 של ה\u0003בן\u0004 \u0003ולא שנא\u0004 \u0005[שונה]\u0006 אם \u0003מת הבן בחיי האב\u0004 ש\u0003לא אתו לידיה דבן\u0004 \u0005[באו לידיו של הבן]\u0006 בכל מקרה \u0003קנה לוקח,\u0004 ומעירים:","\u0003אלמא קסבר\u0004 \u0005[מכאן שהוא סבור]:\u0006 \u0003קנין פירות לאו\u0004 \u0005 [לא]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 \u0003וכי קא זבין\u0004 \u0005[וכאשר הוא מוכר]\u0006 — \u0003דידיה קא זבין\u0004 \u0005[את שלו הוא מוכר].\u0006 ושבים להסבר טענתו של ר' ירמיה בר אבא.","\u0003ואנן השתא\u0004 \u0005[ואנו עכשיו],\u0006 \u0003בין ר' ירמיה בר אבא ובין רב יהודה,\u0004 הלא \u0003כר' שמעון בן לקיש סבירא להו\u0004 \u0005[סבורים הם],\u0006 \u0003וקאמר\u0004 \u0005[ואומר]\u0006 \u0003ר' ירמיה בר אבא: אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר ש\u0003קנין פירות כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 אם כן, \u0003כי מיית\u0004 \u0005[כאשר ימות]\u0006 ה\u0003אב\u0004 \u0003ומיית\u0004 \u0005[ומת]\u0006 \u0003הבן בחיי האב, אמאי אית ליה\u0004 \u0005[מדוע יש לו]\u0006 \u0003ללוקח\u0004 זכות בהם\u0005?\u0006 הרי \u0003כי קא זבין האי לאו דידיה קא זבין\u0004 \u0005[כאשר זה\u0006 הבן \u0005מכר, לא את שלו\u0006 הוא \u0005מכר]!\u0006","\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 ש\u0003קנין פירות לאו\u0004 \u0005[לא]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 ואם כן מדוע לא יזכה רב שמואל בר אבא בנכסים שנתנה לו אמו בחייה?","\u0003אהדרוה לקמיה\u0004 \u0005[החזירו\u0006 את התשובה הזו \u0005לפני]\u0006 \u0003רב יהודה, אמר להו\u0004 \u0005[להם]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל:\u0004 הלכה \u0003זו\u0004 שבעל מוציא מיד לקוחות \u0003אינה דומה למשנתנו\u0004 באב שכתב נכסיו לבנו.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אמר רב יוסף: בשלמא אי תני איפכא\u0004 \u0005[נניח אם היה שונה ההיפך]:\u0006 \u0003הכותב נכסיו לאביו\u0004 לאחר מותו, ומכר האב בחיי הבן, ומת בחיי הבן, ואומרת המשנה כי הלוקח זוכה בנכסים לאחר מות הבן, \u0003איכא למפשט מינה\u0004 \u0005[יש,\u0006 אפשר, \u0005לפתור מכאן]\u0006 ש\u0003קנין פירות לאו\u0004 \u0005 [לא]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 וכפי שהוכחנו קודם.","\u0003אלא השתא\u0004 \u0005[עכשיו]\u0006 \u0003דקתני\u0004 \u0005[ש\u0006הוא \u0005שונה]\u0006 דווקא \u0003הכותב נכסיו לבנו,\u0004 טעמו של דבר שהמכר של הבן בחיי אביו תקף \u0003משום\u0004 שהבן \u0003ראוי ליורשו הוא,\u0004 שיש לו כבר זכות בנכסים, ולא משום השטר לבדו. ואילו במקרה של רב שמואל בר אבא, הרי לא הבן יורש, אלא הבעל הוא יורשה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003אטו ברא ירית אבא, אבא\u0004 \u0005[וכי הבן יורש\u0006 את \u0005האב,\u0006 ו\u0005האב]\u0006 \u0003לא ירית ברא\u0004 \u0005[יורש\u0006 את הבן]? ומצד זכות הירושה אין איפוא הבדל ביניהם. \u0003אלא\u0004 גם אם היה שונה במשנה \"הכותב נכסיו לאביו\", היינו מבינים כי טעם הדבר — \u0003לאברוחינהו לנכסי מבריה קא אתי\u0004 \u0005[להבריח את הנכסים מבנו הוא בא,\u0006 רוצה\u0005],\u0006 ומשום כך כתבם לאביו. \u0003הכא נמי לאברוחינהו לנכסי מאחוה אתי\u0004 \u0005[כאן גם כן,\u0006 באב שכותב לבנו, \u0005להבריח את הנכסים מאחיו\u0006 הוא \u0005בא],\u0006 שיש לאב בנים אחרים, והוא רוצה שרק בנו זה יירש נכסיו. ואם כן, אין ראיה משימוש המשנה במקרה זה דווקא.","\u0003אלא\u0004 יש לדחות הסבר זה שאמרנו, ולומר באופן אחר: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש מה שאמר שמואל שזכות הבעל בנכסים שמכרה אשתו בחייה \u0003אינה דומה למשנתנו\u0004 לפיה אב אינו זוכה בנכסים שמכר בנו? הטעם הוא אחר: \u0003משום\u0004 שיש כאן \u0003תקנת אושא,\u0004 שהיא תקנה מיוחדת לגבי זכות הבעל בנכסי אשתו. ש\u0003אמר ר' יוסי בר חנינא: באושא התקינו,\u0004 ש\u0003האשה שמכרה בנכסי מלוג\u0004 שהכניסה בנישואיה לבעלה והיה המכר \u0003בחיי בעלה ומתה, הבעל מוציא\u0004 את הנכסים \u0003מיד הלקוחות.\u0004","\u0003אמר רב אידי בר אבין, אף אנן נמי תנינא\u0004 \u0005[אף אנו גם כן שנינו]\u0006 רמז לתקנת אושא במקור אחר, אם היו עדים שאמרו: \u0003\"מעידים אנו באיש פלוני שגירש את אשתו ונתן\u0004 לה את \u0003כתובתה\",\u0004"],["\u0003והרי היא תחתיו ומשמשתו,\u0004 כלומר, והאשה נמצאת נשואה וחיה עם בעלה לכל דבר, \u0003ונמצאו\u0004 עדים אלה \u0003זוממין,\u0004 כלומר, שהוזמו על ידי עדים אחרים ונמצא שרצו בעדותם למנוע מאשה זו את כתובתה, שהרי העידו שכבר קיבלה כתובה, במקרה זה \u0003אין אומרים\u0004 ש\u0003ישלמו\u0004 העדים את \u0003כל\u0004 הסכום הכתוב ב\u0003כתובתה, אלא\u0004 רק \u0003טובת הנאת כתובתה,\u0004 ו\u0003איזהו\u0004 (מה היא) \u0003טובת הנאת כתובתה?\u0004 — \u0003אומדין\u0004 (משערים) \u0003כמה אדם רוצה ליתן,\u0004 מוכן לשלם תמורת הסיכוי שיזכה \u0003בכתובה של\u0004 אשה \u0003זו, ש\u0004הרי \u0003אם נתארמלה או נתגרשה\u0004 (תתאלמן או תתגרש) — יקבל את הכתובה, אף שהוא יודע ש\u0003אם מתה\u0004 (תמות) בחיי בעלה — \u0003יירשנה בעלה.\u0004","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 כי \u0003ליתא\u0004 \u0005[אין]\u0006 מקבלים \u0003לתקנת אושא, אמאי\u0004 \u0005[מדוע]\u0006 בכלל \u0003יירשנה בעלה? תזבין\u0004 \u0005[תמכור]\u0006 את \u0003כתובתה לגמרי!\u0004","\u0003אמר אביי:\u0004 מכאן אין ראיה לתקנת אושא, שכן גם לחולקים עליה \u0003אם אמרו\u0004 שיכולה אשה למכור \u0003בנכסי מלוג\u0004 שהם שלה, וכי \u0003יאמרו\u0004 דבר זה \u0003בנכסי צאן ברזל\u0004 (שהם הנכסים המשועבדים לפרעון כתובתה) שאינם של האשה, אלא הם ברשות ובאחריות הבעל לגמרי? ואם כן בכל אופן יש בכתובתה נכסים שאם מתה יורש אותם בעלה. ואין מכאן ראיה לתקנת אושא.","\u0003אמר אביי:\u0004 ענין זה של \u0003טובת הנאה הואיל ואתא לידן\u0004 \u0005[והגיע\u0006 בא \u0005לידינו],\u0006 \u0003נימא\u0004 \u0005[נאמר]\u0006 \u0003בה מילתא\u0004 \u0005[דבר\u0006 הלכה\u0005]:\u0006 \u0003טובת הנאה\u0004 של מכירת הכתובה \u0003לאשה הויא\u0004 \u0005[היא],\u0006 ואין בה חלק לבעל. \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר ש\u0003לבעל הויא\u0004 \u0005[היא],\u0006 \u0003לימרו\u0004 \u0005[שיאמרו]\u0006 \u0003לה עדים\u0004 זוממים שבאו להפסידה כתובתה: \u0003מאי אפסדינך\u0004 \u0005[מה הפסדנו אותך]\u0006 על ידי עדותנו? הרי גם \u0003אי הות מזבנת לה\u0004 \u0005[אם היית מוכרת אותה]\u0006 את \u0003טובת הנאה,\u0004 ה\u0003בעל הוה שקיל מינך\u0004 \u0005[היה נוטל\u0006 את תמורתה \u0005ממך]!\u0006 \u0003אמר רב שלמן:\u0004 אין להביא מכאן ראיה \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 \u0003רווח ביתא\u0004 \u0005[הבית]\u0006 בתוספת כסף על ידי מכירת הכתובה, וייתכן שהאשה מעדיפה חיי רווח בזמן נישואיה יותר מהחזקת נכסים אלה לאחר מכן.","\u0003אמר רבא, הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003טובת הנאה לאשה, ו\u0004אף \u0003אין הבעל אוכל פירות\u0004 מן הנכסים שקנתה בכספי טובת הנאה. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003פירא תקינו ליה רבנן\u0004 \u0005[\u0006את \u0005פירות\u0006 נכסיה של האשה \u0005תיקנו לו\u0006 הקנו לבעל \u0005חכמים]\u0006 ואולם \u0003פירא דפירא\u0004 \u0005[פירות הפירות]\u0006 הללו \u0003לא תקינו ליה רבנן\u0004 \u0005[תיקנו לו חכמים].\u0006","\u0003כי אתא\u0004 \u0005[כאשר באו]\u0006 \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע מבי רב\u0004 \u0005[מבית הרב],\u0006 מבית המדרש בו למדו, \u0003אמרי\u0004 \u0005[היו אומרים]:\u0006 \u0003תנינא\u0004 \u0005[שנינו]\u0006 במשנה את \u0003תקנת אושא:\u0004 והיכן? ממה ששנינו במשנתנו: \u0003העבד והאשה פגיעתן רעה, החובל בהן\u0004 — \u0003חייב, והם שחבלו באחרים\u0004 — \u0003פטורין,\u0004 משום שאין בידם לשלם. \u0003ו\u0004מעתה \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר ש\u0003ליתא\u0004 \u0005[אין]\u0006 הלכה שכזו שהיא \u0003תקנת אושא,\u0004 מדוע אם כן פטורה אשה שחבלה והלא היא יכולה להשיג כסף גם בחיי בעלה! כיצד? — \u0003תזבין\u0004 \u0005[תמכור]\u0006 \u0003נכסי מלוג ותתן ליה\u0004 \u0005[לו]\u0006 לניזק את התשלום! אלא משמע שהאשה אינה יכולה למכור כלל את נכסי מלוג שלה.","על הוכחה זו מקשים: \u0003ולטעמיך\u0004 \u0005[ו\u0006אף \u0005לטעמך\u0006 ולשיטתך\u0005]\u0006 שמכאן אתה רוצה להביא ראיה, \u0003נהי נמי דאיתיה\u0004 \u0005[גם כן\u0006 אם נניח \u0005שיש]\u0006 \u0003לתקנת אושא ולא מצי מזבנה\u0004 \u0005[יכולה למכור]\u0006 את נכסי מלוג \u0003לגמרי,\u0004 מכל מקום \u0003תזבין\u0004 \u0005[תמכור]\u0006 את \u0003נכסי מלוג בטובת הנאה,\u0004 כלומר, תמכור את הסיכוי שיחזרו הנכסים לרשותה (אם תתאלמן או תתגרש) \u0003ותתן ליה\u0004 \u0005[לו]\u0006 לניזק את מה שהזיקה לו! \u0003אלא\u0004 בהכרח יש לפרש את המשנה שמדובר במקרה \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003לה\u0004 נכסי מלוג, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 יש לפרש לענין טובת הנאה שאינה יכולה למכור — משום \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003לה.\u0004","אגב שהובא ענין זה שואלים: \u0003ותזבין\u0004 \u0005[ותמכור]\u0006 את \u0003כתובתה בטובת הנאה,\u0004 כלומר, מה שתקבל מבעלה אם תתגרש או תתאלמן, \u0003ותתן ליה\u0004 \u0005[לו]\u0006 לניזק, ואם כן יש לה כסף מסויים? ומשיבים: \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זאת\u0006 שיטת \u0005מי היא]?\u0006 — שיטת \u0003ר' מאיר היא, דאמר\u0004 \u0005[שאומר]:\u0006 \u0003אסור לו לאדם שישהא את אשתו\u0004 תחתיו \u0003אפילו שעה אחת בלא כתובה.\u0004 וכיון שכך — אין האשה יכולה למכור את כתובתה בטובת הנאה.","ודוחים: \u0003וטעמא מאי\u0004 \u0005[ו\u0006הרי \u0005טעם\u0006 הדבר \u0005מהו],\u0006 מדוע אסור לאשה נשואה להיות בלא כתובה? \u0003כדי שלא תהא\u0004 אשתו של אדם \u0003קלה בעיניו להוציאה\u0004 (לגרשה), שהרי יצטרך לתת לה כתובתה, ואולם אם כן \u0003הכא\u0004 \u0005[כאן]\u0006 כשמוכרת את כתובתה גם כן \u0003לא מגרש לה\u0004 \u0005[אותה],\u0006 בגלל נימוק זה שאין לה תשלומי כתובה, \u0003דאי מגרש לה\u0004 \u0005[ש\u0006הרי \u0005אם יגרש אותה],\u0006 \u0003אתו הנך דזבני גבו לה\u0004 \u0005[יבואו אלה שקנו\u0006 ממנה \u0005ויגבו אותה]\u0006 את \u0003כתובתה מיניה\u0004 \u0005[ממנו],\u0006 ואם כן מבחינתו של הבעל אין הבדל לענין קלות הגירושין אם מכרה או לא מכרה את הכתובה!","\u0003אלא,\u0004 יש לומר כך בתשובה: טעם הדבר שאשה אינה משלמת לניזק למרות שבאפשרותה למכור את כתובתה בטובת הנאה, היא משום ש\u0003טובת הנאה מילי נינהו\u0004 \u0005[מילים,\u0006 דיבורים, \u0005הם],\u0006 כלומר, אין הם רכוש מסויים, אלא רק דיבורים של הבטחת אפשרות (שמא תגבה את כתובתה) \u0003ומילי\u0004 \u0005[ומילים,\u0006 דיבורים\u0005]\u0006 \u0003לא משתעבדי\u0004 \u0005[ומילים,\u0006 דיבורים, \u0005אינם משתעבדים]\u0006 לחוב כגון זה של הניזק.","ושואלים: \u0003אלמה\u0004 \u0005[מדוע]\u0006 הם \u0003לא\u0004 משתעבדים? והרי אלו \u0003מילי דמזדבני בדינרי נינהו\u0004 \u0005[מילים,\u0006 דיבורים, \u0005שנמכרים בדינרים הם],\u0006 שהרי הבטחה זו שמבטיחה האשה לקונה שווה כסף! \u0003אלא\u0004 טעם הדבר שאינה מוכרת כתובתה בטובת הנאה, הוא \u0003משום\u0004 דבריו של \u0003שמואל,\u0004 ש\u0003אמר שמואל:\u0004 מלווה \u0003המוכר שטר חוב\u0004 שיש בידו \u0003לחבירו, וחזר ומחלו\u0004 ללווה את חובו לו — החוב \u0003מחול,\u0004 ונמצא שטר החוב חסר ערך. \u0003ו\u0004לא רק בעל החוב עצמו יכול לעשות כן אלא \u0003אפילו יורש מוחל.\u0004 וכך חוששים אנו שמא תמחול האשה לבעל על כתובתה (שהוא למעשה שטר חוב), ונמצא הקונה מפסיד. ולכן אין האשה יכולה למכור את כתובתה בטובת הנאה.","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 תעשה כך, \u0003זבוני זבין\u0004 \u0005[תמכור]\u0006 את טובת הנאת כתובתה \u0003ותתן ליה\u0004 \u0005[לו]\u0006 לניזק, \u0003ואי מחלה ליה לגבי בעל\u0004 \u0005[ואם מוחלת לו עבור בעלה]\u0006 — \u0003תמחלה\u0004 \u0005[תמחול]\u0006 ויפסיד הקונה. שהרי אין הכרח לומר שתמחל, כשם שאדם יכול למכור את שטר חובו, אף שיכול למוחלו.","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 במקרה כזה, שמכריחים אותה למכור את כתובתה, \u0003כל\u0004 דבר \u0003לגבי\u0004 \u0005[אצל\u0006 שקשור ושייך\u0005]\u0006 ל\u0003בעל,\u0004 האשה \u0003ודאי מחלה ליה\u0004 \u0005[תמחול לו]\u0006 שלא יצטרך לפרוע, \u0003ואפסדיניה לההוא זבינא\u0004 \u0005[ולהפסיד\u0006 לקונים \u0005את המיקח הזה]\u0006 \u0003בידים לא אפסדינהו\u0004 \u0005[מפסידים\u0006 אותם\u0005]\u0006 שאין מתקנים דבר שבוודאי יפסיד ממנו הקונה.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003זבינא ניהליה לההוא דחבלה ביה\u0004 \u0005[תמכור לו\u0006 את כתובתה \u0005לזה שחבלה בו]\u0006 \u0003בטובת הנאה,\u0004 תמורת הסכום שנתחייבה לו,"],["\u0003דאי מחלה\u0004 \u0005[ש\u0006גם אם \u0005תמחל]\u0006 האשה את הכתובה \u0003לגבי\u0004 \u0005[אצל]\u0006 ה\u0003בעל\u0004 — \u0003לא קא מפסיד\u0004 \u0005[הוא\u0006 הנחבל \u0005לא מפסיד],\u0006 \u0003דהשתא נמי לא מידי קא יהבה ליה\u0004 \u0005[ש\u0006הרי \u0005עכשיו\u0006 שמוכרת כתובתה \u0005גם כן שום דבר אינה נותנת לו]!\u0006 על כך יש להשיב: \u0003סוף סוף כל\u0004 דבר \u0003לגבי\u0004 \u0005[אצל]\u0006 \u0003בעל ודאי מחלה\u0004 \u0005[תמחול],\u0006 \u0003ואטרוחי בי דינא בכדי\u0004 \u0005[ולהטריח\u0006 את \u0005בית הדין בחינם]\u0006 לעסוק במכירה זו שבוודאי בסופו של דבר לא תצא אל הפועל \u0003לא מטרחינן\u0004 \u0005[אין אנו מטריחים].\u0006","וחוזרים ומקשים: אם טעם הדבר שאשה אינה יכולה למכור כתובתה בטובת הנאה הוא משום שיכולה למחול אותה לבעלה, \u0003אלא הא דתניא\u0004 \u0005[\u0006הלכה \u0005זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003וכן היא שחבלה בבעלה\u0004 — \u0003לא הפסידה\u0004 בכך את \u0003כתובתה,\u0004 שאין הבעל גובה את התשלומים מנכסים שהכניסה לו בכתובתה. ויש לשאול \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003תזבנינה ניהליה\u0004 \u0005[תמכור לו]\u0006 את \u0003כתובתה\u0004 \u0003לבעלה\u0004 עצמו \u0003בטובת הנאה בהא\u0004 \u0005[ב\u0006עבור \u0005זו]\u0006 ה\u0003חבלה,\u0004 \u0003דאי מחלה\u0004 \u0005[ש\u0006גם \u0005אם תמחל]\u0006 \u0003לגבי\u0004 \u0005[אצל]\u0006 \u0003בעל ליכא פסידא\u0004 \u0005[אין\u0006 לו \u0005הפסד],\u0006 שהרי לו עצמו היא מוחלת!","ומשיבים: \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 \u0003ודאי\u0004 שיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: אסור לאדם שישהא את אשתו אפילו שעה אחת בלא כתובה.\u0004","\u0003וטעמא מאי\u0004 \u0005[ומה הטעם]\u0006 שאסר לאשה להיות בלא כתובה — \u0003כדי שלא תהא קלה בעיניו להוציאה\u0004 (לגרשה), ואף \u0003הכא\u0004 \u0005[כאן]\u0006 אם תמכור האשה לבעלה את הזכות לכתובתה, יביא הדבר לתוצאה הפוכה, שהבעל ירצה עוד יותר \u0003מגרש לה\u0004 \u0005[\u0006ו\u0005יגרש אותה]\u0006 \u0003וגבי ליה בחבליה מינה\u0004 \u0005[ויגבה\u0006 את \u0005חבלתו ממנה\u0006 מכתובתה\u0005]!\u0006 ואומרים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאתה חושש לכך, \u0003השתא נמי\u0004 \u0005[עכשיו גם כן]\u0006 שפסקו שאינו גובה ממנה ואין היא מוכרת לו את כתובתה, מדוע לא נחשוש שבעלה \u0003מגרש לה וגבי ליה בחבליה מינה\u0004 \u0005[יגרש אותה ויגבה את חבלתו ממנה]!\u0006","ומשיבים: מדובר כאן \u0003כגון דנפיש\u0004 \u0005[שמרובה]\u0006 סכום \u0003כתובתה,\u0004 שצריך לשלם לה כשמגרשה, ש\u0003משום ההוא פורתא\u0004 \u0005[אותו\u0006 סכום \u0005מעט]\u0006 של דמי החבלה \u0003לא\u0004 ירצה הבעל \u0003מפסיד טובא\u0004 \u0005[להפסיד הרבה].\u0006","ושואלים: \u0003ואי\u0004 \u0005[ואם]\u0006 אכן מדובר במקרה \u0003דנפישא\u0004 \u0005[שמרובה]\u0006 סכום \u0003כתובתה מ\u0004סכום ה\u0003כתובה דאורייתא\u0004 \u0005[של התורה]\u0006 שהכתובה המינימלית היא של מאתים זוז, \u0003נוקמא אכתובה דאורייתא\u0004 \u0005[נעמיד\u0006 את כתובתה \u0005על\u0006 סכום \u0005הכתובה של התורה],\u0006 \u0003ואידך תזבנה ניהליה בחבליה\u0004 \u0005[ו\u0006את החלק ה\u0005אחר\u0006 של כתובתה \u0005תמכור לו\u0006 לבעלה \u0005בחבלתו]!\u0006","ומשיבים: מדובר כאן \u0003כגון\u0004 ש\u0003לא נפישא\u0004 \u0005[מרובה]\u0006 \u0003כתובתה מכתובה דאורייתא\u0004 \u0005[של התורה],\u0006 כגון \u0003דהוי חבליה ארבעה זוזי\u0004 \u0005[שהיו\u0006 דמי \u0005חבלתו ארבעה זוזים],\u0006 ש\u0003משום ארבעה זוזי\u0004 \u0005[זוזים]\u0006 \u0003לא מפסיד\u0004 \u0005[\u0006יהא מוכן \u0005להפסיד]\u0006 \u0003עשרים וחמשה\u0004 של הכתובה.","ומקשים: \u0003אלא\u0004 לדרך זו, \u0003הא דתניא\u0004 \u0005[\u0006הלכה \u0005זו ששנינו\u0006 בסוף הברייתא\u0005]:\u0006 \u0003כשם שלא תמכור\u0004 כתובתה לצורך תשלומי נזיקין \u0003והיא תחתיו, כך לא תפסיד\u0004 חלק מכתובתה \u0003והיא תחתיו, והא זימנין משכח לה דמפסדא\u0004 \u0005[והרי פעמים נמצא שמפסידה]\u0006 ומפחיתה מכתובתה, \u0003והיכי דמי\u0004 \u0005[וכיצד הוא בדיוק]?\u0006 \u0003כגון דנפישא\u0004 \u0005[שמרובה]\u0006 סכום \u0003כתובתה מ\u0004סכום \u0003כתובה דאורייתא\u0004 \u0005[של התורה]!\u0006","\u0003אמר רבא: סיפא\u0004 \u0005[\u0006ב\u0005סוף\u0006 הברייתא\u0005],\u0006 כלומר, בהלכה זו \u0003אתאן\u0004 \u0005[באנו,\u0006 עברנו\u0005]\u0006 לענין אחר — \u0003לכתובת בנין דכרין\u0004 \u0005[בנים זכרים]\u0006 מבעלה, שיש תנאי הכתוב בכתובה שאם תמות היא, ואחר כך ימות בעלה, בנים זכרים שיהיו לה ממנו הם יירשו את דמי הכתובה יתר על חלקם בירושה אם יתחלקו בה עם בני אשה אחרת של אותו אב.","\u0003והכי קתני\u0004 \u0005[וכך שנה]:\u0006 \u0003כשם שהמוכרת כתובתה לאחרים לא הפסידה כתובת בנין דכרין,\u0004 והם נוטלים דמי כתובתה מנכסי אביה כשמת, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003זוזי\u0004 \u0005[הזוזים\u0006 הכסף\u0005]\u0006 \u0003הוא\u0004 ש\u0003אנסוה\u0004 \u0005[הכריחוה]\u0006 לכך, למכור לפי שעה, ולא רצתה לבטל זכות בניה, \u0003כך מוכרת כתובתה לבעלה לא הפסידה כתובת בנין דכרין, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003זוזי\u0004 \u0005[הזוזים\u0006 הכסף\u0005]\u0006 \u0003הוא\u0004 ש\u0003אנסוה\u0004 \u0005[הכריחוה]\u0006 לכך.","ועתה שבים לעיקר הדיון, ושואלים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 ש\u0003תקנת אושא\u0004 שאשה אינה יכולה למכור נכסי מלוג שהכניסה בכתובתה במחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא\u0004 שנויה. \u0003דתני חדא\u0004 \u0005[ששנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003עבדי\u0004 נכסי \u0003מלוג\u0004 שהכניסה אשה לבעלה \u0003יוצאין\u0004 לחירות \u0003ב\u0004דין \u0003שן ועין לאשה\u0004 אם היא חבלה בהם, שהרי הם שייכים לה (ראה שמות כא, כו–כז), \u0003אבל לא לאיש\u0004 (לבעל) אם הוא חבל בהם, משום שאינו בעליהם. \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 אינם יוצאים בשן ועין \u0003לא לאיש ולא לאשה.\u0004","ומסבירים כיצד נובעת הנחה זו שנחלקו ברייתות אלה בתקנת אושא: \u0003סברוה\u0004 \u0005[סברו\u0006 הלומדים\u0005]\u0006 מתחילה, \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003קנין פירות לאו\u0004 \u0005[לא]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 ואם כן, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003בהא קא מיפלגי\u0004 \u0005[ב\u0006נושא \u0005זה הם חלוקים]:\u0006 \u0003דמאן דאמר\u0004 \u0005[שמי שאומר,\u0006 הברייתא הראשונה\u0005]\u0006 שהעבדים יוצאים בשן ועין \u0003לאשה\u0004 — \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את \u0003תקנת אושא,\u0004 ולכן הוא סבור שכל נכסי מלוג שייכים שייכות גמורה לאשה, שהרי היא גם יכולה למכור אותם, ולכן חייבת לשחרר את עבדי מלוג שהם שלה אם פגעה בהם. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר,\u0006 הברייתא השניה\u0005]\u0006 שהעבדים אינם יוצאים בשן ועין \u0003לא לאיש ולא לאשה\u0004 — \u0003אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 את \u0003תקנת אושא\u0004 ולכן אין נכסי מלוג שייכים בשלימות לא לבעל ולא לאשה.","ודוחים: \u0003לא, דכולי עלמא אית להו\u0004 \u0005[לדעת הכל יש להם,\u0006 מקבלים\u0005]\u0006 את \u0003תקנת אושא, אלא כאן\u0004 בברייתא שעבדים יוצאים לחירות בשן ועין לאשה מדובר \u0003קודם\u0004 ה\u0003תקנה\u0004 ואז היו שייכים רק לאשה, ואילו \u0003כאן\u0004 ששנינו שאינם יוצאים לחירות אף לאשה, הרי זה \u0003לאחר\u0004 ה\u0003תקנה\u0004 שמאותה תקנה הריהם של שניהם.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר נוסף: \u0003אידי ואידי\u0004 \u0005[זו וזו],\u0006 שתי הברייתות, נשנו \u0003לאחר תקנה,\u0004 \u0003ו\u0004שתיהן \u0003אית להו\u0004 \u0005[יש להן,\u0006 מקבלים\u0005]\u0006 את \u0003תקנת אושא, אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהם משתחררים \u0003לאשה ולא לאיש מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003כ\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא:\u0004"],["\u0003הקדש\u0004 (שמקדיש דבר בקדושת הגוף), \u0003חמץ\u0004 (שהגיע הפסח וחל איסור חמץ) \u0003ושחרור\u0004 של עבד — \u0003מפקיעים מידי שיעבוד.\u0004 ואף כאן, כיון שחבלה בעבד והוא משתחרר בכך — בטל ממנו השיעבוד שמשועבדים נכסי מלוג שלה לבעלה.","ואומרים: אם כן \u0003לימא\u0004 \u0005[האם לומר]\u0006 ששיטת \u0003רבא\u0004 במחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא\u0004 שנויה, שהרי בברייתא האחרת נאמר שאינו יוצא כלל בשן ועין ואם כן לדעה זו אין השחרור מפקיע ממנו את שיעבוד הבעל על נכסי המלוג! ודוחים: \u0003לא, דכולי עלמא אית להו\u0004 \u0005[הכל יש להם,\u0006 מקבלים\u0005]\u0006 את שיטת \u0003רבא, והכא אלמוה רבנן לשיעבודא\u0004 \u0005[וכאן\u0006 לדעת הברייתא האחרת, \u0005חיזקו חכמים\u0006 במיוחד \u0005את השיעבוד]\u0006 של ה\u0003בעל\u0004 יותר משאר שיעבודים, שלא יופקע על ידי שחרור.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר: \u0003דכולי עלמא לית להו להני תנאי\u0004 \u0005[לדעת הכל אין להם לתנאים הללו\u0006 בשתי הברייתות\u0005]\u0006 \u0003תקנת אושא, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004עצם השאלה האם \u0003קנין פירות כקנין הגוף דמי\u0004 \u0005[נחשב]\u0006 \u0003קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006","\u0003ובפלוגתא דהני תנאי\u0004 \u0005[ובמחלוקת של תנאים אלה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המוכר עבדו\u0004 הכנעני \u0003לאחר, ופסק עמו\u0004 עם הקונה תנאי \u0003על מנת שישמשנו\u0004 העבד עוד \u0003שלשים יום\u0004 לאחר שמכרו, ואם כן יש למוכר באותם שלושים יום קנין פירות בעבד. ונחלקו תנאים מה דינו של העבד באותם שלושים יום.","\u0003ר' מאיר אומר: ראשון,\u0004 כלומר, המוכר \u0003ישנו בדין יום או יומים\u0004 כדין כל בעליו של עבד, שאם היכה בו מכות קשות ומת תחת ידיו, רק אם מת בתוך יום או יומיים מההכאה (ולא לאחר מכן) הרי הוא חייב מיתה עליו. ונחשב המוכר כבעליו של העבד \u0003מפני שהוא תחתיו,\u0004 שבפועל הוא עדיין נמצא ברשותו. ומסבירים: \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 ש\u0003קנין פירות,\u0004 כלומר, זכות השימוש בדבר \u0003כקנין הגוף דמי\u0004 \u0005[נחשב].\u0006","ואילו \u0003ר' יהודה אומר:\u0004 האדון ה\u0003שני,\u0004 הקונה, דווקא הוא \u0003ישנו בדין יום או יומים, מפני שהוא כספו\u0004 ולא המוכר. ומסבירים: \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003קנין פירות לאו\u0004 \u0005[לא]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[נחשב].\u0006","ואילו \u0003ר' יוסי אומר: שניהם ישנן בדין יום או יומים, זה,\u0004 המוכר, \u0003מפני שהוא תחתיו, וזה,\u0004 הקונה, \u0003מפני שהוא כספו.\u0004 ומסבירים: \u0003מספקא ליה\u0004 \u0005[מסופק לו]\u0006 לגבי \u0003קנין פירות, אי\u0004 \u0005[אם]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 \u0003אי לאו\u0004 \u0005[אם לא]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 \u0003ו\u0004כלל הוא: כל דבר שהוא בכלל \u0003ספק נפשות,\u0004 נוהגים בדינו \u0003להקל,\u0004 ולכן אם היכה אחד מהם את העבד ומת לאחר יומיים — אין הורגים מספק, שמא הוא האדון.","\u0003ר' אליעזר אומר: שניהם אינן בדין יום או יומים,\u0004 והריהם כשאר כל אדם ולכן אם מת מחמת ההכאה של אחד מהם — חייב הלה מיתה אף לאחר יומיים. ומדוע? \u0003זה,\u0004 הקונה, \u0003לפי שאינו תחתיו, וזה,\u0004 המוכר, \u0003לפי שאינו כספו.\u0004","\u0003אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר?\u0004 — \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בטעמה של הלכה זו: \u0003\"כי כספו הוא\"\u0004 (שמות כא, כא), לדייק מכאן: \u0003כספו המיוחד לו,\u0004 ולא בזמן שיש זכות כלשהי לאחר בו.","ועוד אומרים: \u0003כמאן אזלא\u0004 \u0005[כ\u0006דעת \u0005מי הולכת]\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר אמימר: איש ואשה שמכרו בנכסי מלוג\u0004 של האשה — \u0003לא עשו ולא כלום? כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 — \u0003כ\u0004דעת \u0003ר' אליעזר,\u0004 הסבור שדבר שאינו קנין גמור של אדם אינו יכול למכור אותו.","ועוד שואלים: \u0003מאן תנא להא דתנו רבנן\u0004 \u0005[מי שנה את זו ששנו חכמים]:\u0006 \u0003מי שחציו עבד וחציו בן חורין, וכן עבד של שני שותפין\u0004 — \u0003אין\u0004 הם \u0003יוצאין\u0004 לחירות אם בעליהם חבלו בהם \u0003בראשי אברים שאינן חוזרין\u0004 כגון שן ועין? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי, הכי אמרי משמיה\u0004 \u0005[כך אומרים משמו]\u0006 של \u0003רבא:\u0004 שיטת \u0003ר' אליעזר היא;\u0004","\u0003מי\u0004 \u0005[האם]\u0006 \u0003לא אמר ר' אליעזר\u0004 בדין יום או יומיים: \u0003\"כספו\"\u0004 כוונתו \u0003המיוחד לו, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בדין שן ועין נאמר שהכתוב \u0003\"עבדו\"\u0004 (\"וכי יכה איש את עין עבדו... לחפשי ישלחנו תחת עינו. ואם שן עבדו... לחפשי ישלחנו תחת שינו\". שמות כ״א:כ״ו-כ״ז, פסוקים כו–כז) כוונתו: \u0003המיוחד לו.\u0004","\u0003התוקע\u0004 (המכה) \u0003לחבירו\u0004 על אוזנו — \u0003נותן לו סלע\u0004 כקנס דמי בושתו. \u0003ר' יהודה אומר משום\u0004 (בשם) \u0003ר' יוסי הגלילי:\u0004 נותן לו \u0003מנה\u0004 (מאה דינרים). אם \u0003סטרו\u0004 על לחיו — \u0003נותן לו מאתים זוז.\u0004 סטרו \u0003לאחר ידו,\u0004 כלומר, אם היכהו על הלחי, לא בחלק הפנימי של כף היד אלא בצידה החיצון, שהיא בושה גדולה — \u0003נותן לו ארבע מאות זוז.\u0004","\u0003צרם\u0004 (משך, פגם) \u0003באזנו,\u0004 או \u0003תלש בשערו,\u0004 או \u0003רקק\u0004 (ירק בו) \u0003והגיע\u0004 (ופגע) \u0003בו ד\u0004באיש שירק בו \u0003רוקו,\u0004 או \u0003העביר\u0004 (הוריד) \u0003טליתו ממנו,\u0004 או \u0003פרע\u0004 (חשף) \u0003ראש האשה\u0004 מכיסויה \u0003בשוק\u0004 (בפומבי) — \u0003נותן לו\u0004 (לה) \u0003ארבע מאות זוז.\u0004"],["\u0003זה הכלל:\u0004 איך קוצבים את תשלום הבושת — \u0003הכל לפי כבודו\u0004 של המתבייש. \u0003אמר ר' עקיבא: אפילו עניים שבישראל רואין אותם כאילו הם בני חורין\u0004 מיוחסים \u0003שירדו\u0004 (הענו) \u0003מנכסיהם\u0004 ולפי זה דנים אותם לענין בושת, ומדוע? — שהם כולם מיוחסים, לפי \u0003שהם בני אברהם יצחק ויעקב. ו\u0004מספרים:","\u0003מעשה באחד שפרע\u0004 (חשף, הסיר את כיסוי) \u0003ראש האשה בשוק, באת\u0004 (באה) האשה \u0003לפני ר' עקיבא\u0004 לתובעו דמי בושתה, \u0003וחייבו ליתן לה ארבע מאות זוז. אמר לו\u0004 האיש לר' עקיבא: \u0003רבי, תן לי זמן\u0004 עד שאפרע, \u0003ונתן לו זמן.\u0004","מה עשה אותו אדם, \u0003שמרה\u0004 (המתין לה) ומצאה כשהיא \u0003עומדת על פתח חצרה, ושבר את הכד\u0004 של שמן \u0003בפניה, ובו\u0004 (בתוך הכד) היה \u0003כ\u0004שווי \u0003איסר שמן, גילתה\u0004 בעצמה אותה אשה \u0003את ראשה והיתה מטפחת\u0004 (מרטיבה ידה) בשמן \u0003ומנחת ידה על ראשה\u0004 כדי למרוח את ראשה בשמן וליהנות ממנו.","\u0003העמיד עליה עדים\u0004 שראו שכך עשתה, \u0003ובא לפני ר' עקיבא, אמר לו:\u0004 וכי \u0003לזו אני נותן ארבע מאות זוז\u0004 על פריעת ראשה? הרי יש עדים שהיא בעצמה אינה חוששת לכבודה ופורעת את ראשה משום דבר מועט כל כך.","\u0003אמר לו\u0004 ר' עקיבא: \u0003לא אמרת כלום.\u0004 כלומר, אין ממש בטענתך, שכן אדם \u0003החובל בעצמו אף על פי שאינו רשאי\u0004 לחבול בעצמו — \u0003פטור\u0004 הוא מקנס, ואילו \u0003אחרים שחבלו בו\u0004 — \u0003חייבים, ו\u0004כן \u0003הקוצץ נטיעותיו\u0004 של עצמו \u0003אף על פי שאינו רשאי\u0004 לקצוץ (מדין \"בל תשחית\". ראה דברים כ, יט) — \u0003פטור,\u0004 ו\u0003אחרים\u0004 שעשו כן — \u0003חייבין.\u0004 וכיוצא בזה לענין הבושת.","שנינו במשנה שהתוקע לחבירו נותן לו מנה (מאה דינרים) לדעת ר' יוסי הגלילי. ובענין זה \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: האם \u0003מנה צורי\u0004 שהוא מאה דינרים ממש \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 \u0003או מנה מדינה\u0004 שערכו רק שמינית ממנה צורי, דהיינו שנים עשרה וחצי דינרים של מנה צורי \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה מן המסופר: \u0003דההוא גברא דתקע ליה לחבריה\u0004 \u0005[שאדם אחד תקע לו לחבירו],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' יהודה נשיאה\u0004 \u0005[הנשיא]\u0006 לתובעו דמי בושתו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 למזיק: \u0003הא אנא\u0004 \u0005[הרי אני],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ר' יוסי הגלילי, הב ליה\u0004 \u0005[תן לו]\u0006 \u0003מנה צורי. שמע מינה\u0004 \u0005[למד מכאן]:\u0006 ש\u0003מנה צורי תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005].\u0006 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","אגב כך שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש הביטוי: \u0003הא אנא, הא\u0004 \u0005[הרי אני, הרי]\u0006 \u0003ר' יוסי הגלילי? אילימא הכי קאמר ליה\u0004 \u0005[אם תאמר\u0006 ש\u0005כך אמר לו]:\u0006 \u0003הא אנא דחזיתך\u0004 \u0005[הרי אני שראיתיך]\u0006 עושה את הדבר, \u0003והא\u0004 \u0005[והרי]\u0006 דעת \u0003ר' יוסי הגלילי\u0004 ש\u0003אמר מנה צורי,\u0004 ולכן \u0003זיל הב ליה\u0004 \u0005[לך תן לו]\u0006 \u0003מנה צורי; למימרא\u0004 \u0005[האם לומר\u0006 מכאן\u0005]\u0006 ש\u0003עד נעשה דיין,\u0004 ואין צורך בהבאת עדים לפני הדיין, אלא הוא עצמו שראה את הדבר פוסק בו הלכה, ולכן יכול ר' יהודה נשיאה לשמש בשני התפקידים?","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003סנהדרין שראו אחד שהרג את הנפש\u0004 — \u0003מקצתן\u0004 של הדיינים \u0003נעשו עדים\u0004 על כך, \u0003ומקצתן נעשו דיינין\u0004 לדונו על כך על פי עדותם של אלה, אלו \u0003דברי ר' טרפון. ר' עקיבא אומר: כולם עדים הם, ואין עד נעשה דיין.\u0004","ונדקדק מברייתא זו: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' טרפון\u0004 שהתיר בענין זה — \u0003אלא\u0004 באופן ש\u0003מקצתן נעשו עדים ומקצתן נעשו דיינין, אבל עד\u0004 ש\u0003נעשה דיין\u0004 בלא עדות עדים אחרים כלל \u0003לא קאמר\u0004 \u0005[אמר],\u0006 וכל שכן ר' עקיבא!","ודוחים: אפשר לומר \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005],\u0006 היה זה \u0003כגון שראו\u0004 הסנהדרין את המעשה \u0003בלילה,\u0004 ש\u0003לא למעבד דינא נינהו\u0004 \u0005[לעשות דין הם]\u0006 יכולים באותה שעה, משום שאין דנים דיני נפשות אלא ביום, ואם כן אינם יכולים להיות דיינים באותה שעה, אלא רק להיות עדים לדבר.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 דחייה אחרת, כי ר' יהודה הנשיא כלל לא היה עד על עצם המעשה, ומה שאמר \"הרי אני\", \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]\u0006 לאותו אדם שתקע: \u0003הא אנא דסבירא לי\u0004 \u0005[הרי אני שסבור אני]\u0006 \u0003כ\u0004שיטת \u0003ר' יוסי הגלילי\u0004 ש\u0003אמר\u0004 שהכוונה ל\u0003מנה צורי, והא סהדי דמסהדי\u0004 \u0005[והרי עדים שמעידים]\u0006 \u0003בך\u0004 שכך עשית, לכן \u0003זיל הב ליה\u0004 \u0005[לך תן לו]\u0006 \u0003מנה צורי.\u0004","לגוף הענין שהזכרנו שואלים: \u0003וסבר\u0004 \u0005[ו\u0006האם \u0005סבור]\u0006 \u0003ר' עקיבא\u0004 ש\u0003אין עד נעשה דיין?\u0004","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 על מה שנאמר בדיני חבלות \u0003\"והכה איש את רעהו באבן או באגרף\"\u0004 (שמות כא, יח), \u0003שמעון התימני אומר: מה אגרוף מיוחד\u0004 (מתאפיין בכך) \u0003ש\u0004הוא \u0003מסור\u0004 (נתון לפני כל) \u0003לעדה ולעדים,\u0004 כלומר, מסור לעדה שהדיינים עצמם, כמו העדים, יכולים לדעת מה שיעורו וכוחו של האגרוף שחבל, \u0003אף כל\u0004 דבר שחבל צריך \u0003ש\u0004יהיה \u0003מסור לעדה ולעדים,\u0004 והרי זה בא למעט, \u0003פרט לשיצתה\u0004 (יצאה) האבן \u0003מתחת יד העדים.\u0004 כלומר, שהאבן הזו עצמה שבה היכה נעלמה לאחר שהעדים ראוה, ובית הדין לא ראוה, ואין בית הדין יכולים לאמוד אם היתה ראויה להזיק כל כך.","\u0003אמר לו ר' עקיבא\u0004 שאין לקבל סברה זו: \u0003וכי\u0004 בכל מקרה שדנים אדם שהיכה את חבירו \u0003בפני בית דין הכהו, שיודעין\u0004 בדיוק \u0003כמה הכהו ועל מה הכהו, אם על שוקו או ציפר נפשו\u0004 (צווארו)? ואם כן בית הדין בהכרח אינו יודע את פרטי הדברים מעצמו אלא על פי העדים.","\u0003ועוד, הרי שדחף את חבירו מראש הגג או מראש הבירה\u0004 (מגדל) \u0003ומת\u0004 בדחיפה זו, האם \u0003בית דין הולכין אצל בירה או בירה הולכת אצל בית דין\u0004 כדי לאמוד אם היתה ראויה להמית? אלא ודאי סומכים על תיאור העדים.\u0003 ועוד\u0004, \u0003אם נפלה\u0004 אחר כך אותה בירה, וכי \u0003חוזר ובונה\u0004 אותה כדי שיוכלו בית דין לאמוד?","\u0003אלא\u0004 כך יש ללמוד, \u0003מה אגרוף מיוחד שהוא מסור לעדים\u0004 שהם יכולים להעיד על כך ולספר את כל הפרטים, \u0003אף כל שהוא מסור לעדים\u0004 ולכן גם אם נעלמה האבן, אם העדים מעידים שהיתה זו אבן גדולה למדי, שראויה להרוג — הרי זה די עבור הדיינים ויכולים לפסוק בכך.","ומה בא הכתוב למעט, \u0003פרט לכשיצתה אבן מתחת ידו של מכה,\u0004 שאף העדים לא ראו בדיוק את האבן, והאבן הזו נעלמה מעיניהם — שאז \u0003פטור.\u0004 שכן במקרה כזה אין העדים יכולים להעיד, שהרי אינם יכולים לומר שהיתה זו אבן גדולה מספיק כדי להזיק בה עד כדי כך.","\u0003קתני מיהת\u0004 \u0005[שנינו על כל פנים]\u0006 ש\u0003אמר לו ר' עקיבא\u0004 לשמעון התימני: \u0003וכי בפני בית דין הכהו, שיודעין כמה הכהו?\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003הכהו בפניהם\u0004 היינו אומרים ש\u0003עד נעשה דיין,\u0004 שהם רואים את הדבר ויכולים לדון על פי ראייתם, והרי אין זה כשיטת ר' עקיבא בברייתא!","ודוחים: מכאן אין ראיה שכך שיטת ר' עקיבא. כי אפשר לומר ש\u0003לדבריו\u0004 של \u0003ר' שמעון התימני קאמר\u0004 \u0005[אמר],\u0006 שלפי שיטתו ענה לו, \u0003וליה לא סבירא ליה\u0004 \u0005[ו\u0006אולם \u0005הוא עצמו אינו סבור כן]\u0006 ולדעתו אם נעשה הדבר בפני בית דין — אין אותו בית הדין יכול לדון באותו נושא.","ובהמשך לדברים אלה, מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שור תם שהמית\u0004 אדם ואחר כך חזר \u0003והזיק\u0004 — \u0003דנין אותו דיני נפשות\u0004 והורגים אותו, \u0003ואין דנין אותו דיני ממונות\u0004 על מה שהזיק.","ואילו שור \u0003מועד שהמית והזיק\u0004 — \u0003דנין אותו דיני ממונות\u0004 ומשלם את הנזק, \u0003וחוזרין ודנין אותו דיני נפשות.\u0004 אבל אם \u0003קדמו ודנוהו\u0004 תחילה \u0003דיני נפשות\u0004 — \u0003אין חוזרין ודנין אותו דיני ממונות,\u0004 שכבר ראוי לסקילה.","ותוהים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003קדמו ודנוהו דיני נפשות מאי הוי\u0004 \u0005[מה היה\u0006 על ידי כך\u0005]?\u0006 \u0003ליהדר ולידייניה נמי\u0004 \u0005[שיחזרו וידונו אותו גם כן]\u0006 ב\u0003ממונות!\u0004","\u0003אמר רבא: אשכחתינהו לרבנן דבי רב\u0004 \u0005[מצאתי את החכמים של בית הרב,\u0006 בית המדרש\u0005]\u0006 \u0003דיתבי וקאמרי\u0004 \u0005[שיושבים ואומרים]\u0006 בפירוש דבר זה: \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 — שיטת \u0003ר' שמעון התימני היא,\u0004 ש\u0003אמר: מה אגרוף מיוחד שמסור לעדה ולעדים,\u0004 שיכולים לאמוד בבית דין כיצד בדיוק אירע הדבר,"],["\u0003אלמא בעינן אומדנא דבי דינא\u0004 \u0005[מכאן\u0006 ש\u0005מצריכים אנו אומדן של בית הדין\u0006 עצמו\u0005]\u0006 כדי לחייבו, \u0003והא\u0004 \u0005[וזה]\u0006 שור שהרג \u0003כיון דגמר דינא לקטלא\u0004 \u0005[שנגמר דינו למות],\u0006 \u0003לא משהינן ליה לאומדנא דבי דינא\u0004 \u0005[אין אנו משהים אותו את אומדן בית הדין]\u0006 \u0003ולא מענינן לדיניה\u0004 \u0005[ואין אנו מענים את דינו]\u0006 להשהותו זמן רב עד שייגמר, ולכן אי אפשר לדון אותו שוב.","\u0003ואמינא להו אנא\u0004 \u0005[ואמרתי להם אני]:\u0006 \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003ר' עקיבא\u0004 באותה ברייתא, שאינו מצריך אומדן של בית דין, יש לפרש כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — \u0003כגון שברח\u0004 בעל השור ולא ניתן עתה לדונו שלא בפניו, ולחייבו על הנזק שהזיק שורו.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר בברייתא זו במקרה ש\u0003ברח\u0004 בעל השור, אם כן, במקרה האחר, \u0003כי\u0004 \u0005[כאשר]\u0006 עדיין \u0003לא דנוהו דיני נפשות, היכי דיינינא ליה\u0004 \u0005[איך דנים אותו]\u0006 \u0003דיני ממונות בלא בעלים?\u0004 שהרי גם בדיני ממונות צריכים הבעלים להיות נוכחים. ומשיבים: מדובר במקרה \u0003דקביל סהדי\u0004 \u0005[שקיבל\u0006 את עדות ה\u0005עדים]\u0006 בפני בעל השור ונתחייב לשלם \u0003וברח.\u0004","ושואלים: \u0003סוף סוף מהיכא\u0004 \u0005[מהיכן]\u0006 \u0003משתלם\u0004 (נפרע) הנזק במקרה זה — \u0003מרידיא\u0004 \u0005[מחרישה].\u0006 שלוקחים את השור הזה ומשכירים אותו לחרישה, ומדמיו משלמים את המחיר, ואחר כך מעמידים אותו לדיני נפשות. \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שור \u0003תם\u0004 גם כן \u0003נדייניה\u0004 \u0005[נדון אותו]\u0006 \u0003דיני ממונות ברישא\u0004 \u0005[בתחילה]\u0006 \u0003ונשתלם מרידיא\u0004 \u0005[וישתלם\u0006 הנזק \u0005מחרישה],\u0006 \u0003והדר נדייניה\u0004 \u0005[ואחר כך נדון אותו]\u0006 \u0003דיני נפשות!\u0004 ומדוע שנינו בברייתא שאין דנים אותו כלל דיני ממונות?","בעקבות שאלה זו \u0003אמר רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב כהנא, זאת אומרת:\u0004 כסף \u0003רידייא\u0004 \u0005[חרישה]\u0006 — כ\u0003עלייה דמרה\u0004 \u0005[של הבעלים]\u0006 \u0003הוא\u0004 נחשב, כלומר, כאילו היה משלם מנכסיו ולא כגבייה מגוף השור עצמו, והואיל ושור תם אינו משלם אלא מגופו נמצא שלא ניתן לגבות נזקי שור תם מדמי החרישה.","אגב דברי הברייתא המצריכה לאמוד האם ראוי היה ההרוג בידי חבירו למות במכה שהיכהו, מביאים כי \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003יש\u0004 דין \u0003אומד לנזקין,\u0004 האם אומדים אם היה מעשה זה שעשה המזיק ראוי לגרום נזק שכזה, \u0003או אין אומד לנזקין?\u0004","וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 דווקא \u0003לקטלא\u0004 \u0005[ל\u0006ענין \u0005מיתה]\u0006 \u0003הוא דאמדינן\u0004 \u0005[שאנו אומדים]:\u0006 \u0003בהכי נפקא\u0004 \u0005[בכך יוצאת]\u0006 \u0003נשמה, בהכי\u0004 \u0005[בכך]\u0006 \u0003לא נפקא\u0004 \u0005[יוצאת]\u0006 \u0003נשמה,\u0004 ואם היה הדבר שהרג פחות מן השיעור אומרים שלא מחמתו אירע הדבר, אלא מקרה היה, וכמבואר בברייתא, \u0003אבל לנזקין\u0004 ב\u0003כל\u0004 שיעור \u0003דהו\u0004 \u0005[שהוא],\u0006 כיון שהזיק — חייב, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003לא שנא\u0004 \u0005[שונה]\u0006 וגם בנזקים עושים אומד, אם ראוי היה הדבר להזיק נזק זה, ואם לא היה ראוי — פטור.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במשנה: \u0003מה בור\u0004 שחייבה התורה על נזקיו — \u0003שיש בו כדי להמית\u0004 שהוא \u0003עשרה טפחים, אף כל\u0004 צורה אחרת של חפירה בקרקע, כגון מערה — \u0003שיש בו כדי להמית\u0004 דהיינו \u0003עשרה טפחים. היו פחותין מעשרה טפחים ונפל לתוכו שור או חמור ומת\u0004 — \u0003פטור,\u0004 אם \u0003הוזק בו\u0004 — \u0003חייב.\u0004","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003ממטה למעלה קא חשיב\u0004 \u0005[הוא מונה],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך\u0006 הוא \u0005אומר]:\u0006 \u0003מטפח ועד עשרה\u0004 — דין \u0003מיתה ליכא\u0004 \u0005[אין],\u0006 אבל \u0003נזקין איכא\u0004 \u0005[יש],\u0006 \u0003אלמא\u0004 \u0005[מכאן\u0006 יוצא\u0005]\u0006 ש\u0003לנזקין\u0004 ב\u0003כל\u0004 שיעור \u0003דהו\u0004 \u0005[שהוא]\u0006 יהא חייב, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003אין אומדין לנזקין.\u0004","ודוחים: \u0003לא,\u0004 כאן בברייתא זו \u0003ממעלה למטה קא חשיב\u0004 \u0005[מונה],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך\u0006 הוא \u0005אומר]:\u0006 כשיש \u0003עשרה\u0004 טפחים — דין \u0003מיתה איכא\u0004 \u0005[יש],\u0006 \u0003פחות מעשרה פורתא\u0004 \u0005[מעט]\u0006 — דין \u0003נזקין איתא\u0004 \u0005[יש],\u0006 דין \u0003מיתה ליכא\u0004 \u0005[אין],\u0006 \u0003ולעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 ש\u0003יש אומד לנזקין, וכל מידי ומידי כי היכי דמיתזקה ביה בעינן\u0004 \u0005[דבר ודבר\u0006 שיעור \u0005כדי שתינזק בו צריכים אנו]\u0006 ולכן אם היה המקום שטוח ביותר, אין אנו אומרים שזה שגרם לנזק.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003הכהו על עינו וסימאו\u0004 (עשה אותו עיוור), \u0003על אזנו וחירשו\u0004 — \u0003עבד יוצא בהן לחירות\u0004 על ידי מכות אלה. אבל אם היכה \u0003כנגד עינו,\u0004 שלא פגע בגופו, \u0003ואינו רואה,\u0004 או היכה \u0003כנגד אזנו\u0004 וגרם לרעש גדול, \u0003ואינו שומע\u0004 — \u0003אין עבד יוצא בהן לחירות; מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 שפטור? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דבעינן אומדנא\u0004 \u0005[שאנו צריכים אומדן]\u0006 ואנו אומדים שבכגון זה אינו יכול להזיק? \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 ש\u0003יש אומדנא לנזקין.\u0004","ודוחים: \u0003לא, משום דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 \u0003הוא דאבעית נפשיה\u0004 \u0005[שהבהיל\u0006 את \u0005עצמו],\u0006 כלומר, לא המכה עצמה גרמה לעיוורון או לחירשות, אלא הוא גרם לעצמו על ידי הפחד. \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003המבעית\u0004 \u0005[המפחיד]\u0006 \u0003את חבירו\u0004 וגרם לו בכך לאיזה שהוא נזק — \u0003פטור מדיני אדם ו\u0004אולם \u0003חייב בדיני שמים, כיצד?\u0004 אם \u0003תקע\u0004 בקול \u0003באזנו וחירשו\u0004 — \u0003פטור,\u0004 אבל אם עשה מעשה, ש\u0003אחזו ותקע באזנו וחירשו\u0004 — \u0003חייב.\u0004","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בברייתא: \u0003חמשה דברים\u0004 שמשלם החובל בחבירו \u0003אומדין אותו\u0004 את הניזק, כמה זכאי הוא לקבל, \u0003ונותנין לו מיד. ריפוי ושבת\u0004 — אומדים כמה יצטרך \u0003עד שיתרפא. אמדוהו\u0004 את התשלומים המגיעים לניזק בשיעור מסויים \u0003והיה מתנונה\u0004 (מתנוון) \u0003והולך,\u0004 כלומר, שנעשה יותר ויותר חלש והרי זה שלא כדמי האומדנא בתחילה — \u0003אין נותנין לו אלא כמו שאמדוהו\u0004 ולא יותר, ומן הצד השני אם","\u0003אמדוהו\u0004 לסכום מסויים והתבססה אומדנא זו על הערכה שיבריא בזמן רב \u0003והבריא\u0004 לפני הזמן — \u0003נותנין לו\u0004 את \u0003כל\u0004 הסכום לפי \u0003מה שאמדוהו. שמע מינה\u0004 \u0005[למד מכאן]:\u0006 ש\u0003יש אומד לנזקין!\u0004 ומשיבים: אין ראיה מברייתא זו לשאלתנו, שכן \u0003למימד גברא\u0004 \u0005[לאמוד\u0006 את \u0005האיש]\u0006 הניזוק \u0003כמה ליקצר מיהא מכה\u0004 \u0005[יהא חולה ממכה זו],\u0006 ו\u0003כמה לא מקצר\u0004 \u0005[יהא חולה]\u0006 — \u0003לא קא מבעי לן\u0004 \u0005[נשאלה לנו],\u0006 ש\u0003ודאי אמדינן\u0004 \u0005[אנו אומדים]\u0006 בכגון זה. \u0003כי קא מבעיא לן\u0004 \u0005[כאשר נשאלה לנו\u0006 השאלה\u0005]\u0006 היה זה \u0003למימד חפצא\u0004 \u0005[לאמוד\u0006 את \u0005החפץ]\u0006 \u0003אי עביד האי נזקא\u0004 \u0005[אם עושה\u0006 הוא \u0005נזק זה],\u0006 \u0003או לא,\u0004 אם כן \u0003מאי\u0004 \u0005[מה]\u0006 הדין?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בברייתא, \u0003שמעון התימני אומר: מה אגרוף מיוחד\u0004 (מתאפיין בכך) \u0003ש\u0004הוא \u0003מסור\u0004 (נתון לפני כל) \u0003לעדה ולעדים,\u0004 כלומר, מסור לעדה שהדיינים עצמם, כמו העדים, יכולים לדעת מה שיעורו וכוחו של האגרוף שחבל, \u0003אף כל\u0004 דבר שחבל צריך \u0003ש\u0004יהיה \u0003מיוחד\u0004 בכך שיהיה \u0003מסור לעדה ולעדים, שמע מינה\u0004 \u0005[למד מכאן]:\u0006 ש\u0003יש אומד לנזקין.\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ודנים עוד במה שנאמר בברייתא שהובאה מקודם, \u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא: \u0003אמדוהו\u0004 שיבריא לזמן מסויים \u0003והבריא\u0004 מוקדם ממה שאמדוהו — \u0003נותנין לו\u0004 את \u0003כל\u0004 הסכום לפי \u0003מה שאמדוהו. מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003לרבא,\u0004 ש\u0003אמר רבא: האי מאן\u0004 \u0005[מי]\u0006 שניזק ש\u0003אמדוהו\u0004 שלא יוכל לעבוד \u0003לכולי יומא\u0004 \u0005[לכל היום],\u0006 \u0003ואיתפח לפלגא דיומא וקא עביד עבידתא\u0004 \u0005[והבריא בחצי היום ו\u0006הוא \u0005עובד עבודה]\u0006 — \u0003יהבינן ליה דכולי יומא\u0004 \u0005[נותנים לו\u0006 את דמי השבת \u0005של כל היום],\u0006 ומדוע? \u0003מן שמיא\u0004 \u0005[השמים]\u0006 \u0003הוא דרחמי עליה\u0004 \u0005[שריחמו עליו]\u0006 והבריא מהר יותר, אבל אין זה משנה את חובת התשלומים של המזיק.","שנינו במשנה: אם \u0003רקק והגיע בו הרוק,\u0004 או ש\u0003העביר\u0004 את כסותו — נותן לו ארבע מאות זוז. \u0003אמר רב פפא: לא שנו אלא\u0004 שרקק והגיע הרוק \u0003בו\u0004 עצמו, \u0003אבל\u0004 אם נגע הרוק רק \u0003בבגדו\u0004 — \u0003לא.\u0004 ושואלים: מדוע ייפטר מבושת אם הרוק נגע בבגדיו, \u0003וניהוי\u0004 \u0005[ויהא\u0006 זה\u0005]\u0006 \u0003כי\u0004 \u0005[כמו]\u0006 אם \u0003בייש\u0004 את חבירו \u0003בדברים?\u0004","\u0003אמרי במערבא\u0004 \u0005[אומרים בארץ ישראל]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוסי בר אבין, זאת אומרת: ביישו\u0004 חבירו \u0003בדברים\u0004 בלבד \u0003פטור מכלום,\u0004 שאינו משלם על כך קנס אף על פי שחייב כלפי שמים.","שנינו במשנה: את הסכום לבושת קובעים \u0003הכל לפי כבודו. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 במשנה, שאמר כך, האם \u0003לקולא קאמר\u0004 \u0005[להקל אמר],\u0006 \u0003או לחומרא קאמר\u0004 \u0005[להחמיר אמר]?\u0006 ומסבירים את צדדי השאלה: \u0003לקולא קאמר\u0004 \u0005[להקל אמר]\u0006 — \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003עני\u0004 ש\u0003לא בעי למשקל כולי האי\u0004 \u0005[צריך לקבל כל כך\u0006 הרבה\u0005]\u0006 באותם סכומים הקצובים במשנה, \u0003או דלמא לחומרא קאמר\u0004 \u0005[שמא להחמיר אמר],\u0006 \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003עשיר דבעי למיתב ליה טפי\u0004 \u0005[שצריך לתת לו יותר]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 \u0003מדקאמר\u0004 \u0005[ממה שאומר]\u0006 \u0003ר' עקיבא\u0004 שם: \u0003אפילו עניים שבישראל רואין אותן כאילו הן בני חורין שירדו מנכסיהם,\u0004 לפי \u0003שהם בני אברהם יצחק ויעקב, שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003לקולא קאמר\u0004 \u0005[להקל אומר],\u0006 כלומר, שהעניים יקבלו סכום יותר נמוך, ועל זה בא ר' עקיבא ואומר שאין מקילים לעניים משום שכולם שווים מפני חשיבות ישראל. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","מסופר במשנה: \u0003ומעשה באחד שפרע ראש האשה\u0004 בשוק וביקש זמן עד שישלם ונתן לו ר' עקיבא. ושואלים: \u0003ומי יהבינן\u0004 \u0005[והאם נותנים אנו]\u0006 \u0003זמן\u0004 לפירעון חוב של חבלות? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' חנינא: אין נותנין זמן לחבלות\u0004 אלא משלם מיד!","ומשיבים: \u0003כי לא יהבינן ליה\u0004 \u0005[כאשר אין אנו נותנים לו,\u0006 לחובל\u0005]\u0006 \u0003זמן\u0004 — הרי זה דווקא \u0003לחבלה,\u0004 משום \u0003דחסריה ממונא\u0004 \u0005[שהחסיר אותו,\u0006 את הנחבל, \u0005ממון]\u0006 בעצם החבלה, \u0003אבל לבושת,\u0004 ש\u0003לא חסריה ממונא\u0004 \u0005[החסיר אותו,\u0006 את המתבייש, \u0005ממון]\u0006 — \u0003יהבינן\u0004 \u0005[אנו נותנים]\u0006 זמן לתשלום\u0005.\u0006","באותו מעשה שנינו שאותו אדם שפרע ראש האשה \u0003שמרה עומדת על פתח חצירה וכו'\u0004 ואמר לו ר' עקיבא כי החובל בעצמו אף שאינו רשאי לעשות כן — פטור. ומקשים בדבר: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר לו ר' עקיבא: צללת במים אדירים והעלית חרס בידך,\u0004 כלומר, עשית מאמץ גדול ולא הישגת דבר חשוב, שכן \u0003אדם רשאי לחבל בעצמו,\u0004 וקשה שהרי אצלנו במשנה נאמר בשם ר' עקיבא שאינו רשאי לחבול בעצמו!","\u0003אמר רבא, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 (במשנה) ששנינו שאינו רשאי לחבול בעצמו, מדובר \u0003בחבלה\u0004 ממש, ואילו \u0003כאן\u0004 (בברייתא) ששנינו שרשאי אדם לבייש את עצמו, מדובר \u0003בבושת.\u0004 ומקשים: \u0003והא מתניתין\u0004 \u0005[והרי משנתנו]\u0006 \u0003בבושת הוא\u0004 שמדובר בה,"],["\u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003החובל בעצמו אף על פי שאינו רשאי\u0004 — \u0003פטור,\u0004 משמע שאף לגבי בושת אינו רשאי! ומשיבים: \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]\u0006 ר' עקיבא לאותו אדם: \u0003לא מבעיא\u0004 \u0005[נצרכה]\u0006 לומר \u0003בושת,\u0004 ש\u0003אדם רשאי לבייש את עצמו,\u0004 מכל מקום המביישו חייב, \u0003אלא אפילו חבלה,\u0004 ש\u0003אין אדם רשאי לחבל בעצמו\u0004 והוא עושה זאת, מכל מקום \u0003אחרים שחבלו בו\u0004 — \u0003חייבין.\u0004","ועל ההנחה המוסכמת בענין זה שואלים: \u0003ו\u0004האם \u0003אין אדם רשאי לחבל בעצמו? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יכול\u0004 מי ש\u0003נשבע להרע בעצמו ולא הרע יהא פטור\u0004 מקרבן שבועה על שהפר שבועה זו? — \u0003תלמוד לומר:\u0004 שנאמר בחיוב קרבן שבועה על המיפר שבועתו \u0003\"להרע או להטיב\"\u0004 (ויקרא ה, ד), \u0003מה הטבה\u0004 שמתחייב אם נשבע לעשות דבר טוב הוא דווקא בדבר שהוא \u0003רשות,\u0004 ולא בנשבע לקיים מצוה, \u0003אף הרעה\u0004 שמתחייב על שבועתה, היא דווקא בדבר שהוא \u0003רשות,\u0004 ולא עבירה. ובכך \u0003אביא\u0004 (אוסיף) לחייב גם מי ש\u0003נשבע להרע בעצמו ולא הרע\u0004 ומכאן שאדם רשאי להרע לעצמו!","\u0003אמר שמואל:\u0004 אין מדובר כאן בהרעה לעצמו בדרך של חבלה ממש, אלא \u0003ב\u0004נשבע: \u0003\"אשב בתענית\",\u0004 ודבר זה מותר לעשותו.","ושואלים: \u0003דכוותה גבי\u0004 \u0005[כיוצא בה אצל]\u0006 \u0003הרעת אחרים\u0004 ששנינו באותה ברייתא, שאינו חייב על שבועתה, צריכים גם כן לפרש שמדובר \u0003להשיבם בתענית,\u0004 ויש לתמוה: \u0003אחרים מי מותיב להו בתעניתא\u0004 \u0005[האם\u0006 הוא \u0005יכול להושיב אותם בתענית]?\u0006","ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 באופן שגורם להם שאינם יכולים לאכול כגון \u0003דמהדק להו באנדרונא\u0004 \u0005[שמחזיק אותם,\u0006 סוגר אותם, \u0005בחדר].\u0006 ומקשים: וכיצד מפרש אתה כך את הברייתא?","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003איזהו הרעת אחרים?\u0004 — \"\u0003אכה פלוני ואפצע את מוחו\u0004\"! ולפי זה צריכים לפרש גם הרעת עצמו בחובל בעצמו, ונמצא שאדם רשאי בכך!","\u0003אלא\u0004 בהכרח יש לומר כי \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בעניין זה, \u0003דאיכא למאן דאמר\u0004 \u0005[שיש מי שאומר]:\u0006 \u0003אין אדם רשאי לחבל בעצמו, ואיכא למאן דאמר\u0004 \u0005[ויש מי שאומר]:\u0006 \u0003אדם רשאי לחבל בעצמו.\u0004","ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 ש\u0003אמר: אין אדם רשאי לחבל בעצמו? אילימא האי\u0004 \u0005[אם תאמר\u0006 ש\u0005זה]\u0006 ה\u0003תנא הוא,\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הפסוק: \u0003\"ואך את דמכם לנפשתיכם אדרש\"\u0004 (בראשית ט, ה), \u0003ר' אלעזר אומר: מיד נפשותיכם\u0004 (מעצמכם) \u0003אדרש את דמכם,\u0004 שאפילו מי שהורג את עצמו ייענש על כך?","\u0003ודלמא קטלא שאני\u0004 \u0005[ושמא מיתה שונה],\u0006 שאסור לאדם להמית את עצמו, אבל לא מדובר כאן בחבלה כלל!","\u0003אלא\u0004 שיטת \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא הוא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מקרעין\u0004 בגדים \u0003על המת, ולא\u0004 נחשב הדבר \u0003מדרכי האמורי\u0004 שנאסרו, אלא מנהג ישראל. \u0003אמר ר' אלעזר: שמעתי, שהמקרע על המת יותר מדאי\u0004 — \u0003לוקה משום \"בל תשחית\"\u0004 (ראה דברים ב, יט), \u0003וכל שכן\u0004 מי שמזיק ל\u0003גופו\u0004 מתוך צערו על המת שעובר על כך.","ודוחים: אין זו הוכחה, \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003בגדים שאני\u0004 \u0005[שונים],\u0006 \u0003דפסידא דלא הדר\u0004 \u0005[שהפסד שאינו חוזר]\u0006 \u0003הוא, כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003ר' יוחנן קרי למאני מכבדותא\u0004 \u0005[היה קורא לבגדיו כבודי],\u0006 \u0003ורב חסדא כד הוה מסגי ביני היזמי והגא\u0004 \u0005[כאשר היה הולך בין הקוצים],\u0006 \u0003מדלי להו למאניה\u0004 \u0005[היה מרים את בגדיו]\u0006 ולא היה חושש שבשרו נשרט בקוצים, \u0003אמר\u0004 \u0005[\u0006ו\u0005היה אומר]\u0006 הסבר להתנהגותו זו: \u0003זה\u0004 הבשר \u0003מעלה ארוכה\u0004 (מתרפא), \u0003וזה\u0004 הבגד \u0003אינו מעלה ארוכה\u0004 (אינו מתרפא) כשיקרע! ואם כן, אפשר שדווקא המקרע על המת יהיה חייב, ואילו החובל בעצמו אין איסור בדבר.","\u0003אלא\u0004 צריך לומר כי שיטת \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא הוא,\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' אלעזר הקפר ברבי: מה תלמוד לומר\u0004 בנזיר \u0003\"וכפר עליו מאשר חטא על הנפש\"\u0004 (במדבר ו, יא)? \u0003וכי באיזה נפש חטא זה? אלא\u0004 חטאו הוא בזה \u0003שציער עצמו מן היין\u0004 על ידי הנזירות, וחטא לנפשו בדבר זה. \u0003והלא דברים קל וחומר: ומה זה שלא ציער עצמו אלא מן היין\u0004 בלבד \u0003נקרא חוטא, המצער עצמו מכל דבר, על אחת כמה וכמה.\u0004 הרי ששיטת ר' אלעזר הקפר היא שאין אדם רשאי לחבל בעצמו כלל.","ועוד שנינו במשנה: \u0003הקוצץ נטיעותיו\u0004 של עצמו — אף על פי שאינו רשאי — פטור, אחרים שעשו כן — חייבים. \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רבה בר בר חנה קמיה\u0004 \u0005[לפני]\u0006 \u0003רב\u0004 ברייתא זו, בא אדם לחבירו וטוען: \u0003שורי הרגת\u0004 או \u0003נטיעותי קצצת\u0004 ועליך לשלם לי עליהם, אומר לו החבר: אכן כן, אבל \u0003אתה אמרת לי להורגו\u0004 או \u0003אתה אמרת לי לקוצצו\u0004 — \u0003פטור. אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003אם כן, לא שבקת חיי לברייתא\u0004 \u0005[אין אתה מניח חיים לבריות]!\u0006 \u0003כל כמיניה\u0004 \u0005[וכי הכל ביכולתו\u0006 לומר ונקבל דבריו\u0005]?!\u0006 שהרי בטענה זו יכול להיפטר כל מזיק!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר בר חנה בשאלה: \u0003איסמייה\u0004 \u0005[\u0006האם \u0005אמחוק אותה]\u0006 את הברייתא הזו מן הברייתות הראויות להיאמר? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב בתשובה: \u0003לא,\u0004 אל תעשה כן, אלא \u0003תתרגם מתניתך\u0004 \u0005[הסבר\u0006 את \u0005הברייתא שלך]\u0006 שמדובר בה \u0003בשור העומד להריגה,\u0004 וכגון שנגח והרג אדם, \u0003ובאילן העומד לקציצה,\u0004 כגון אשירה, או שציוו חכמים לכורתו, שאז יש בטענת המזיק ממש, שמסתבר שאכן כך אמר לו הבעלים.","ואומרים: \u0003אי הכי,\u0004 \u0005[אם כך]\u0006 שגם בעל השור מודה שהשור עומד היה להריגה \u0003מאי קא טעין ליה\u0004 \u0005[מה הוא טוען נגדו]\u0006 והרי לא הפסידו דבר? ומשיבים: \u0003דאמר ליה\u0004 \u0005[שאומר לו]:\u0006 \u0003אנא בעינא למיעבד הא\u0004 \u0005[אני רציתי לעשות\u0006 בעצמי את \u0005זאת]\u0006 ה\u0003מצוה\u0004 של ביעור הרע, ושל \"לא תשים דמים בביתך\", ותובע אני פיצוי כספי ממך על שמנעת ממני קיום מצוה זו.","\u0003דתניא\u0004 \u0005[\u0006וכפי \u0005ששנויה\u0006 ברייתא\u0005]:\u0006 במצוות כיסוי הדם נאמר \u0003\"ושפך וכסה\"\u0004 (\"ושפך את דמו וכסהו בעפר\". ויקרא יז, יג), לומר: \u0003מי ששפך,\u0004 כלומר, מי ששוחט, הוא \u0003יכסה\u0004 את הדם, \u0003ומעשה באחד ששחט, וקדם חבירו וכסה\u0004 את הדם, \u0003וחייבו רבן גמליאל ליתן לו\u0004 לשוחט \u0003עשרה זהובים\u0004 משום שביטל אותו מהמצוה הזו.","אגב ענין זה של קציצת אילנות שנזכר במשנה, מביאים מה ש\u0003אמר רב: דיקלא דטען קבא\u0004 \u0005[דקל שטוען,\u0006 שעדיין נותן פירות בשיעור \u0005קב]\u0006 — \u0003אסור\u0004 \u0003למקצציה\u0004 \u0005[לקצוץ אותו]\u0006 משום \"בל תשחית\" (שנאמר: \"כי תצור אל עיר... לא תשחית את עצה\". דברים כ, יט).","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב ממה ששנינו: \u0003כמה\u0004 פירות \u0003יהא ב\u0004עץ \u0003זית ולא יקצצו? רובע\u0004 (רבע) הקב! ואם כן מדוע הוא אומר שצריך שיהא דווקא קב? ומשיבים: \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003זיתים, דחשיבי\u0004 \u0005[ש\u0006הם \u0005חשובים]\u0006 ואפילו רובע קב מהם יש לו ערך.","\u0003אמר ר' חנינא: לא שכיב\u0004 \u0005[מת]\u0006 \u0003שיבחת ברי\u0004 \u0005[בני]\u0006 \u0003אלא\u0004 משום \u0003דקץ תאינתא\u0004 \u0005[שקצץ תאינה]\u0006 \u0003בלא\u0004 (טרם) \u0003זמנה.\u0004 \u0003אמר רבינא: ואם היה מעולה בדמים,\u0004 כלומר, אם מחיר העץ או רווח אחר שיש לו מתוך קציצת האילן גדול יותר מאשר פירות האילן — \u0003מותר\u0004 לקוצצו, שאין בכך משום \"בל תשחית\".","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 על הפסוק \"רק עץ אשר תדע כי לא עץ מאכל הוא אותו תשחית וכרת\" (ויקרא כ, כ) שנינו: \u0003\"רק עץ אשר תדע\"\u0004 — \u0003זה אילן מאכל, \"כי לא עץ מאכל הוא\"\u0004 — \u0003זה אילן סרק,\u0004 שאף באילן מאכל יש אופנים שמותר לקוצצו.","ושואלים: \u0003וכי מאחר שסופו לרבות כל דבר\u0004 ואף אילן פרי, ולהתיר להשתמש בו לצורך, \u0003מה תלמוד לומר \"כי לא עץ מאכל\"?\u0004 ומשיבים: הרי זה בא \u0003להקדים\u0004 קציצת אילן \u0003סרק ל\u0004אילן \u0003מאכל.\u0004"],["\u0003יכול אפילו\u0004 היה אילן הסרק \u0003מעולה בדמים,\u0004 יקר יותר מאילן מאכל, יהא כך הדין שאילן סרק קודם בקציצתו לאילן מאכל? — \u0003תלמוד לומר: \"רק\",\u0004 למעט, שאף שאילן סרק קודם לאילן פרי, הכל תלוי בהפסד שיש בדבר, ובמקרים מסויימים יהא אילן פרי קודם לאילן סרק.","ומסופר: \u0003שמואל אייתי ליה אריסיה תמרי\u0004 \u0005[הביא לו אריסו תמרים].\u0006 \u0003אכיל, טעים בהו טעמא דחמרא\u0004 \u0005[אכל, טעם בהם טעם של יין].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לאריס: \u0003מאי האי\u0004 \u0005[מה זה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ביני גופני קיימי\u0004 \u0005[בין הגפנים\u0006 התמרים \u0005עומדים]\u0006 ולכן יש בהם טעם מסויים של יין. \u0003אמר\u0004 שמואל: \u0003מכחשי בחמרא כולי האי\u0004 \u0005[מכחישים ביין כל זאת\u0006 כל כך הרבה\u0005]\u0006 שמרגישים בתמרים טעם יין? \u0003למחר\u0004 קצוץ את התמרים ו\u0003אייתי\u0004 \u0005[הבא]\u0006 \u0003לי\u0004 את \u0003מקורייהו\u0004 \u0005[קצה האילן]\u0006 לאכילה.","וכיוצא בו: \u0003רב חסדא חזא תאלי בי גופני\u0004 \u0005[ראה\u0006 באחוזתו \u0005דקלים בין הגפנים].\u0006 \u0003אמר ליה לאריסיה\u0004 \u0005[לו לאריסו]:\u0006 \u0003עקרינהו\u0004 \u0005[עקור אותם],\u0006 את הדקלים, שכן \u0003גופני קני דקלי\u0004 \u0005[הגפנים קונים את הדקלים]\u0006 ומחירם מרובה יותר, ואילו \u0003דקלי לא קני גופני\u0004 \u0005[דקלים אינם קונים גפנים].\u0006","\u0003אף על פי שהוא,\u0004 המזיק, \u0003נותן לו\u0004 לניזק את כל התשלומים המגיעים לו עבור נזקו, \u0003אין נמחל\u0004 \u0003לו\u0004 משמים \u0003עד שיבקש ממנו\u0004 מחילה, \u0003שנאמר: \"ועתה השב אשת\u0004 האיש כי נביא הוא ויתפלל בעדך\u0003\"\u0004 (בראשית כ, ז). \u0003ומנין שאם לא מחל לו\u0004 הניזק \u0003שהוא אכזרי? שנאמר: \"ויתפלל אברהם אל האלהים וירפא אלהים את אבימלך\"\u0004 (שם פסוק יז).","\u0003האומר\u0004 לחבירו \u0003\"סמא את עיני\",\u0004 או \u0003\"קטע את ידי\",\u0004 או \u0003\"שבר את רגלי\"\u0004 ועשה זאת — אף על פי כן \u0003חייב\u0004 בכל הנזקים. ואף אם הוסיף ואמר לו במפורש \u0003\"\u0004עשה כן \u0003על מנת לפטור\"\u0004 — בכל זאת \u0003חייב.\u0004","אם אמר לו \u0003\"קרע את כסותי\",\u0004 או \u0003\"שבר את כדי\"\u0004 — \u0003חייב,\u0004 אבל אם אמר לו במפורש שיעשה כן \u0003על מנת לפטור\u0004 — \u0003פטור.\u0004 לעומת זאת, אם אמר \u0003\"עשה כן,\u0004 כלומר, הזק \u0003לאיש פלוני על מנת לפטור\"\u0004 — \u0003חייב, בין\u0004 שאמר להזיקו \u0003בגופו בין בממונו.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל\u0004 סכומים \u0003אלו שאמרו\u0004 במשנה הקודמת, שחייב אדם לשלם לחבירו אם סטר לחבירו וכיוצא בזה, הם \u0003דמי בושתו,\u0004 שלזה יש קנס קצוב, \u0003אבל\u0004 בנוגע ל\u0003צערו\u0004 של אדם \u0003אפילו הביא\u0004 החובל \u0003כל אילי נביות\u0004 המשובחים \u0003שבעולם\u0004 לשם קרבן, \u0003אין נמחל לו\u0004 למזיק \u0003עד שיבקש ממנו,\u0004 מן הניזק, מחילה, \u0003שנאמר: \"השב אשת האיש כי נביא הוא ויתפלל בעדך\"\u0004 (שם פסוק ז).","ואגב שהובא הפסוק תוהים: וכי יש להבין מכאן ש\u0003אשת נביא בעי אהדורי\u0004 \u0005[צריך להחזיר],\u0006 \u0003אשת אחר לא בעי אהדורי\u0004 \u0005[צריך להחזיר]?\u0006","\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן,\u0004 כך צריך לפרש: \u0003\"השב אשת האיש\" מכל מקום,\u0004 שהרי אשתו היא. \u0003ודקא אמרת\u0004 \u0005[ומה שאמרת]\u0006 אבימלך: \u0003\"הגוי גם צדיק תהרג. הלא הוא אמר לי אחתי היא והיא גם הוא אמרה אחי הוא\"\u0004 (שם פסוקים ד–ה)! על כך יש להשיב לך כי אינך כה צדיק, וטעם הדבר שאמר ששרה אחותו היא, כי \u0003נביא הוא, וכבר לימד,\u0004 כלומר, כבר למד כיצד לנהוג מתוך התנהגותך שלך, ש\u0003אכסנאי\u0004 (אורח) \u0003שבא לעיר, על עסקי\u0004 (ענייני) \u0003אכילה ושתיה שואלין אותו, או על עסקי אשתו שואלין אותו,\u0004 האם שואלים את האורח \u0003אשתך היא? אחותך היא?\u0004 ולכן האשמה תלויה בך, שחשד שבאים לגזול ממנו את אשתו.","ומעירים: \u0003מכאן לבן נח שנהרג\u0004 אפילו על דבר שחטא בו בלי לדעת שהוא אסור, משום \u0003שהיה לו ללמוד ולא למד.\u0004","אגב הזכרת ענין אברהם ואבימלך מפרשים עוד מהפסוקים באותו ענין. נאמר שם: \u0003\"כי עצר עצר ה'\u0004 בעד כל רחם לבית אבימלך\" \u0005(שם פסוק יח)\u0006. \u0003אמר ר' אלעזר: שתי עצירות הללו\u0004 הכתובות שם (\"עצור עצר\"), \u0003למה?\u0004 \u0003אחת באיש\u0004 — שלא יצאה ממנו \u0003שכבת זרע, שתים באשה\u0004 — שלא יצאה לא \u0003שכבת זרע\u0004 \u0003ו\u0004לא \u0003לידה,\u0004 שלא יכלה ללדת.","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 \u0003שתים באיש\u0004 — \u0003שכבת זרע וקטנים\u0004 (מי רגלים), \u0003שלשה באשה\u0004 — גם \u0003שכבת זרע\u0004 \u0003ו\u0004גם \u0003קטנים\u0004 \u0003ו\u0004גם \u0003לידה.\u0004","\u0003רבינא אמר: שלש באיש\u0004 — \u0003שכבת זרע וקטנים ופי טבעת,\u0004 שגם צואה לא יכלו להוציא, שלא יכלו כלל לעשות צרכיהם, ואילו \u0003ארבעה באשה\u0004 — \u0003שכבת זרע\u0004 \u0003ולידה, וקטנים ופי טבעת.\u0004","עוד נאמר שם: \u0003\"בעד כל רחם\"\u0004 — \u0003אמרי דבי\u0004 \u0005[אמרו\u0006 החכמים \u0005של בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: אפילו תרנגולת של בית אבימלך לא הטילה ביצתה\u0004 באותה הזמן, שהרי נאמר \"כל רחם\" לא רק של הנשים.","אגב הזכרת ענין זה של אבימלך מביאים שורה של שאלות ששאל רבא את רבה בר מרי, והראשונה בהן קשורה לענין זה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: מנא הא מילתא דאמור רבנן\u0004 \u0005[מנין דבר זה שאמרו חכמים]:\u0006 \u0003כל המבקש רחמים על חבירו והוא צריך לאותו דבר, הוא נענה תחילה? אמר ליה\u0004 \u0005[לו]:\u0006 ראיה לדבר, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וה' שב את שבות איוב בהתפללו בעד רעהו\"\u0004 (איוב מב, י).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003את אמרת מהתם, ואנא אמינא מהכא\u0004 \u0005[אתה אומר משם,\u0006 מן הכתובים, \u0005ואני אומר מכאן,\u0006 מן התורה\u0005],\u0006 שנאמר: \u0003\"ויתפלל אברהם אל האלהים וירפא אלהים את אבימלך ואת אשתו ואמהותיו\"\u0004 (בראשית כ, יז), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 מיד אחר כך \u0003\"וה' פקד את שרה כאשר אמר\"\u0004 (שם כא, א), הכוונה היא \u0003כאשר אמר אברהם אל אבימלך,\u0004 שמשום שהתפלל עליו שתלדנה הנשים בביתו — הוא עצמו זכה להיענות בכך.","ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: מנא הא מילתא דאמרי אינשי\u0004 \u0005[מנין דבר זה שאומרים אנשים]\u0006 בפתגם עממי: \u0003בהדי הוצא לקי כרבא\u0004 \u0005[יחד עם הקוץ לוקה\u0006 גם \u0005הכרוב],\u0006 שפעמים עוקרים את הכרוב עם הקוץ? \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"למה תריבו אלי כלכם פשעתם בי נאם ה'\"\u0004 (ירמיה ב, כט), משמע מלשון \"כולכם\" שנאמרה התוכחה לכולם, אפילו לאלה שלא היו פושעים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003את אמרת מהתם, ואנא אמינא מהכא\u0004 \u0005[אתה אומר משם,\u0006 מן הנביאים, \u0005ואני אומר\u0006 ראיה \u0005מכאן,\u0006 מן התורה\u0005]\u0006 שאמר ה' למשה לאחר שליקטו אנשים מבני ישראל מן בשבת: \u0003\"עד אנה מאנתם לשמר מצותי ותורתי\"\u0004 (שמות טז, כח), ומשמע שאף משה בכלל זה, אף שהוא לא חטא.","ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: כתיב\u0004 \u0005[נאמר]\u0006 ביוסף: \u0003\"ומקצה אחיו לקח חמשה אנשים\u0004 ויציגם לפני פרעה\u0003\"\u0004 (בראשית מז, ב), \u0003מאן נינהו\u0004 \u0005[מי הם\u0006 אותם\u0005]\u0006 \u0003חמשה? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: אותן שהוכפלו בשמות\u0004 בברכה שבירכם משה, דן, זבולון, גד, אשר, ונפתלי (ראה דברים, לג), משום שהיו חלשים, ואותם הביא יוסף לפני פרעה.","ושואלים: הרי \u0003יהודה נמי איכפולי מיכפל\u0004 \u0005[גם כן הוכפל]\u0006 בברכה, ובוודאי שהיה גיבור!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003למילתיה\u0004 \u0005[לעניינו]\u0006 \u0003הוא דאיכפל\u0004 \u0005[שהוכפל]\u0006 לשם דבר אחר, ש\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן, מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 בברכת משה: \u0003\"יחי ראובן ואל ימת ויהי מתיו מספר\"\u0004 (דברים, לג ו) ומיד אחר כך: \u0003\"וזאת ליהודה\"\u0004 (שם פסוק ז)?","ש\u0003כל אותן ארבעים שנה שהיו ישראל במדבר היו עצמותיו של יהודה מגולגלין בארון,\u0004 ולא היה שלדו מחובר \u0003עד שבא משה\u0004 לפני מותו \u0003ובקש\u0004 עליו \u0003רחמים.\u0004 \u0003אמר לפניו: רבונו של עולם, מי גרם לראובן שיודה\u0004 על מה שחטא בבלהה ועל כך זכה לברכה שלא יצא מכלל מנין שנים עשר בני יעקב (ראה בראשית לה, כב)? — \u0003יהודה,\u0004 לכן נאמר","\u0003מיד\u0004 אחר כך שהתפלל משה \u0003\"שמע ה' קול יהודה\"\u0004 (דברים, לג, ז), \u0003על איבריה לשפא\u0004 \u0005[נכנסו איבריו למקומם]\u0006 והיה שלדו מחובר ושלם. ועדיין \u0003לא הוו קא מסקי למתיבתא דרקיעא\u0004 \u0005[העלוהו לישיבה של מעלה],\u0006 על כך התפלל משה: \u0003\"ואל עמו תביאנו\"\u0004 (דברים, לג, ז), שיהא עם \"עמו\" — שאר החכמים. הועילה תפילה זו, ועדיין \u0003לא הוה ידע מאי קאמרי רבנן\u0004 \u0005[היה יודע\u0006 שם \u0005מה אומרים חכמים],\u0006 \u0003ולמשקל ומיטרח בהדי רבנן\u0004 \u0005[ולשאת ולתת יחד עם החכמים],\u0006 על כך ביקש: \u0003\"ידיו רב לו\"\u0004 (דברים, לג, ז), שתהיה לו יכולת ללמוד איתם. ועדיין \u0003לא הוה סליק ליה שמעתתא אליבא דהלכתא\u0004 \u0005[היתה עולה לו השמועה על פי הלכה],\u0006 התפלל עליו: \u0003\"ועזר מצריו תהיה\"\u0004 (דברים, לג, ז). כלומר, שינצח בדבר הלכה.","ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: מנא הא מילתא דאמרי אינשי\u0004 \u0005[מנין דבר זה שאומרים אנשים]:\u0006 \u0003בתר עניא אזלא עניותא\u0004 \u0005[אחר העני הולכת עניות]?\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 \u0003עשירים מביאין בכורים בקלתות\u0004 (סלים) \u0003של זהב ושל כסף,\u0004 והכהנים נוטלים את הביכורים ומחזירים את הקלתות, \u0003ועניים\u0004 מביאים אותם \u0003בסלי נצרים של ערבה קלופה,\u0004 ובמקרה זה \u0003הסלים והבכורים נותנים לכהנים.\u0004 נמצא שהעשיר מקבל בחזרה את הסל של זהב שהביא, ואילו העני מאבד גם את סלו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003את אמרת מהתם, ואנא אמינא מהכא\u0004 \u0005[אתה אומר משם,\u0006 מן המשנה, \u0005ואני אומר מכאן,\u0006 מן התורה\u0005]\u0006 ראיה לדבר:"],["ממה שנאמר \u0003\"וטמא טמא יקרא\"\u0004 (ויקרא יג, מה), שלא די לו שהוא סובל מנגע הצרעת אלא גם צריך להודיע לרבים שהוא טמא.","ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: מנא הא מילתא דאמור רבנן\u0004 \u0005[מנין דבר זה שאמרו חכמים]:\u0006 \u0003השכם ואכול בקיץ מפני החמה, ובחורף מפני הצינה;\u0004 \u0003ו\u0004עוד \u0003אמרי אינשי\u0004 \u0005[אומרים אנשים]\u0006 בענין זה: \u0003שיתין רהוטי רהוט\u0004 \u0005[שישים\u0006 אנשים \u0005רצים]\u0006 \u0003ולא מטו לגברא דמצפרא כרך\u0004 \u0005[מגיעים,\u0006 משיגים, \u0005את האדם שאכל בבוקר].\u0006 אמר לו רבה בר מרי, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא ירעבו ולא יצמאו ולא יכם שרב ושמש\"\u0004 (ישעיהו מט, י), משמע שמי שאכל ושתה בבוקר שוב אין שרב ושמש הבאים אחר כך יכולים להכותו.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003את אמרת מהתם, ואנא אמינא מהכא\u0004 \u0005[אתה אומר\u0006 ראיה \u0005משם,\u0006 מן הנביאים, \u0005ואני אומר מכאן,\u0006 מן התורה\u0005],\u0006 מה שנאמר: \u0003\"ועבדתם את ה' אלהיכם\"\u0004 (שמות כג, כה) — \u0003זו קרית\u0004 (קריאת) \u0003שמע ותפלה, \"וברך את לחמך ואת מימיך\"\u0004 (שמות כג, כה) — \u0003זו פת במלח וקיתון\u0004 (כוס) \u0003של מים\u0004 ששותים לאחר מיכן בבוקר, \u0003מכאן ואילך\u0004 מתקיים המשך הפסוק \u0003\"והסירתי מחלה מקרבך\",\u0004","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003מחלה\u0004 — \u0003זו מרה, ולמה נקרא שמה מחלה? ששמונים ושלשה חלאין יש בה\u0004 במרה, \u0003\"מחלה\" בגימטריא הכי הוו\u0004 \u0005[כך הם],\u0006 שמונים ושלוש, \u0003וכולן,\u0004 כל החולאים הללו שבמרה, \u0003פת במלח\u0004 ב\u0003שחרית\u0004 (בבוקר) \u0003וקיתון של מים מבטלן.\u0004","ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: מנא הא מילתא דאמור רבנן\u0004 \u0005[מנין דבר זה שאמרו חכמים]:\u0006 \u0003חברך קרייך \"חמרא\", אוכפא לגביך מוש\u0004 \u0005[חברך קורא אותך \"חמור\", שים על גבך אוכף]\u0006 וקבל את דבריו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 בראיה מן התורה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר הגר שפחת שרי אי מזה באת ואנה תלכי ותאמר מפני שרי גברתי אנכי בורחת\"\u0004 (בראשית טז, ח), ומלשון \"גברתי\" משמע שלאחר שהמלאך קרא לה שפחה הודתה שהיא שפחה.","ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: מנא הא מילתא דאמרי אינשי\u0004 \u0005[מנין דבר זה שאומרים אנשים]:\u0006 \u0003מילתא גנאה דאית ביך קדים אמרה\u0004 \u0005[דבר מגונה שיש בך הקדם\u0006 ו\u0005אמור אותו אתה]\u0006 ולא שיישמע מפי אחרים? \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 באליעזר עבד אברהם: \u0003\"ויאמר עבד אברהם אנכי\"\u0004 (שם כד, לד), שמיד אמר שהוא עבד.","ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: מנא הא מילתא דאמרי אינשי\u0004 \u0005[מנין דבר זה שאומרים אנשים]:\u0006 \u0003שפיל ואזיל בר אווזא ועיניה מטייפי\u0004 \u0005[כפוף והולך הברווז ו\u0006באותה עת \u0005עיניו נשואות\u0006 למרחקים\u0005]\u0006 בציפייה למצוא לעצמו אוכל? \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 באביגיל אשת נבל הכרמלי: \u0003\"והטיב ה' לאדני וזכרת את אמתך\"\u0004 (שמואל א כה, לא), שאף על פי שביקשה עבור בעלה דרך אגב דאגה גם לעצמה, שאם בעתיד יצליח דוד תיהנה גם היא ממנו.","ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: מנא הא מילתא דאמרי אינשי\u0004 \u0005[מנין דבר זה שאומרים אנשים]:\u0006 \u0003שיתין תכלי מטייה לככא דקל חבריה שמע ולא אכל\u0004 \u0005[שישים צרות,\u0006 מכאובים, \u0005באות לשיניים\u0006 של אדם \u0005ש\u0006את \u0005קול חבירו\u0006 האוכל הוא \u0005שומע ו\u0006הוא עצמו \u0005אינו אוכל],\u0006 כלומר, שמתייסר על כך? \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדברי נתן הנביא על סעודת המלכתו של אדוניהו: \u0003\"\u0004ויזבח שור ומריא וצאן לרוב ויקרא לכל בני המלך... \u0003ולי אני עבדך ולצדק הכהן ולבניהו בן יהוידע ולשלמה עבדך לא קרא\"\u0004 (מלכים א א, יט. שם פסוקים כה–כו).","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003את אמרת מהתם, ואנא אמינא מהכא\u0004 \u0005[אתה אומר משם,\u0006 מן הנביאים, \u0005ואני אומר מכאן,\u0006 מן התורה\u0005],\u0006 שנאמר: \u0003\"ויבאה יצחק האהלה שרה אמו ויקח את רבקה ותהי לו לאשה ויאהבה וינחם יצחק אחרי אמו\"\u0004 (בראשית כד, סז), \u0003וכתיב בתריה\u0004 \u0005[ונאמר\u0006 מיד \u0005אחריו]:\u0006 \u0003\"ויסף אברהם ויקח אשה ושמה קטורה\"\u0004 (שם כה, א), שאחרי שראה אברהם בנישואי בנו, גם הוא רצה להינשא.","ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: מנא הא מילתא דאמרי אינשי\u0004 \u0005[מנין דבר זה שאומרים אנשים]:\u0006 \u0003חמרא למריה טיבותא לשקייה\u0004 \u0005[היין לבעליו, החזקת טובה,\u0006 של השותה היא \u0005ל\u0006זה ש\u0005משקה אותו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 כאשר ציווה ה' את משה לסמוך את ידו על יהושע: \u0003\"וסמכת את ידך עליו... למען ישמעון ויראון כל עדת בני ישראל\"\u0004 (במדבר כז, יח. וראה שם פסוק כ), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויהושע בן נון מלא רוח חכמה כי סמך משה את ידיו עליו וישמעו אליו כל בני ישראל\u0004 ויעשו כאשר צוה ה' את משה\u0003\"\u0004 (דברים לד, ט), משמע שאף על פי שרוח ה' אינה באה מכוחו של משה והוא היה רק השליח בדבר, מכל מקום מחזיקים לו טובה ומייחסים לו את הדבר.","ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: מנא הא מילתא דאמרי אינשי\u0004 \u0005[מנין דבר זה שאומרים אנשים]:\u0006 \u0003כלבא בכפניה גללי מבלע\u0004 \u0005[כלב ברעבונו\u0006 אפילו \u0005גללים\u0006 הוא \u0005בולע]?\u0006 אמר לו: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"נפש שבעה תבוס נפת ונפש רעבה כל מר מתוק\"\u0004 (משלי כז, ז).","ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: מנא הא מילתא דאמרי אינשי\u0004 \u0005[מנין דבר זה שאומרים אנשים]:\u0006 \u0003מטייל ואזיל\u0004 \u0005[והולך]\u0006 \u0003דיקלא בישא גבי קינא דשרכי\u0004 \u0005[דקל רע אצל אילנות סרק],\u0006 כלומר, איש רע הולך אצל אנשים שאינם הגונים? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דבר זה כתוב בתורה, שנוי בנביאים, ומשולש בכתובים, ותנן במתניתין\u0004 \u0005[ושנינו\u0006 אותו \u0005במשנתנו],\u0006 \u0003ותנינא\u0004 \u0005[ונשנה]\u0006 \u0003בברייתא.\u0004","\u0003כתוב בתורה —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וילך עשו אל ישמעאל\"\u0004 (בראשית כח, ט), משמע הלך לכיוצא בו. \u0003שנוי בנביאים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויתלקטו אל יפתח אנשים רקים ויהיו עמו\"\u0004 (שופטים יא, ג). שנאספו אליו אנשים הדומים לו. \u0003ומשולש בכתובים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כל עוף למינו ישכון ובני אדם לדומה לו\"\u0004 (בן סירא יג, יז). \u0003תנן במתניתין\u0004 \u0005[שנינו\u0006 אותו \u0005במשנתנו]\u0006 בענין של טהרה וטומאה של כלים — \u0003כל המחובר לטמא\u0004 — \u0003טמא, כל המחובר לטהור\u0004 — \u0003טהור. ותנינא\u0004 \u0005[ונשנה]\u0006 \u0003בברייתא\u0004 — ששנינו, \u0003ר' אליעזר אומר: לא לחנם הלך זרזיר\u0004 וישב \u0003אצל עורב אלא מפני שהוא מינו\u0004 של העורב שאף הוא עוף טמא.","ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: מנא הא מילתא דאמרי אינשי\u0004 \u0005[מנין דבר זה שאומרים אנשים]:\u0006 \u0003קרית חברך ולא ענך, רמי גודא רבה שדי ביה\u0004 \u0005[\u0006אם \u0005אתה קורא לחברך ואינו עונה לך, השלך כותל גדול\u0006 ו\u0005זרוק עליו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 שנאמר: \u0003\"יען טהרתיך ולא טהרת מטמאתך לא תטהרי עוד\u0004 עד הניחי את חמתי בך","\u0003\"\u0004(יחזקאל כד, יג). ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: מנא הא מילתא דאמרי אינשי\u0004 \u0005[מנין דבר זה שאומרים אנשים]:\u0006 \u0003בירא דשתית מיניה לא תשדי ביה קלא\u0004 \u0005[בור ששתית ממנו\u0006 מים \u0005אל תזרוק בו אבן]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא תתעב אדמי כי אחיך הוא ולא תתעב מצרי כי גר היית בארצו\"\u0004 (דברים כג, ח), משמע שכיון שגרו בארצם אסור לגרום להם רעה.","ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: מנא הא מילתא דאמרי אינשי\u0004 \u0005[מנין דבר זה שאומרים אנשים]:\u0006 \u0003אי דלית דורא\u0004 \u0005[אם תרים את המשא\u0006 איתי\u0005]\u0006 — \u0003דלינא\u0004 \u0005[ארים],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 תרים איתי — \u0003לא דלינא\u0004 \u0005[ארים]?\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במלחמת סיסרא: \u0003\"ויאמר אליה\u0004 (לדבורה) \u0003ברק\u0004 \u0003אם תלכי עמי והלכתי ואם לא תלכי עמי לא אלך\"\u0004 (שופטים ד, ח).","ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: מנא הא מילתא דאמרי אינשי\u0004 \u0005[מנין דבר זה שאומרים אנשים]:\u0006 \u0003כד הוינן זוטרי לגברי, השתא דקשישנא לדרדקי\u0004 \u0005[כשהיינו קטנים היינו\u0006 נחשבים \u0005לאנשים, עכשיו כשאנו גדולים אנו\u0006 נחשבים \u0005לתינוקות]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 יש ראיה לדבר, כי \u0003מעיקרא כתיב\u0004 \u0005[מתחילה נאמר]:\u0006 \u0003\"וה' הולך לפניהם יומם בעמוד ענן לנחתם הדרך ולילה בעמוד אש להאיר להם\"\u0004 (שמות יג, כא), שה' עצמו הוא היה הולך לשמור את ישראל, \u0003ולבסוף\u0004 לאחר שעבר זמן והיו צריכים להיות חשובים יותר \u0003כתיב\u0004 \u0005[נאמר]:\u0006"],["\u0003\"הנה אנכי שלח מלאך לפניך לשמרך בדרך\"\u0004 (שמות כג, כ), משמע מלאך ולא ה' בעצמו.","","","","","","","ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: מנא הא מילתא דאמרי אינשי\u0004 \u0005[מנין דבר זה שאומרים אנשים]:\u0006 \u0003בתר מרי ניכסי ציבי משך\u0004 \u0005[אחרי בעל נכסים משוך עצים],\u0006 כלומר, הצטרף אליו בעשייה כלשהי שתיהנה מכך שהנך מתלווה אליו. \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וגם ללוט ההלך את אברם היה צאן ובקר ואהלים\"\u0004 (בראשית יג, ה). אגב שהוזכר ענין אברהם ואבימלך במשנתנו, מביאים מה ש\u0003אמר רב חנן: המוסר דין על חבירו\u0004 לשמים — \u0003הוא נענש תחילה, שנאמר: \"ותאמר שרי אל אברם חמסי עליך\"\u0004 (שם טז, ה), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויבא אברהם לספד לשרה ולבכתה\"\u0004 (שם כג, ב), ששרה נפטרה תחילה. ואומרים: \u0003והני מילי\u0004 \u0005[ודברים אלה\u0006 שנענש על כך אמורים\u0005]\u0006 דווקא באופן \u0003דאית ליה דינא בארעא\u0004 \u0005[שיש לו\u0006 גם \u0005דין בארץ],\u0006 כלומר, שיש מי שיעשה את דינו בארץ, ואינו צריך להיזקק לדין שמים. ובענין זה \u0003אמר ר' יצחק: אוי לו לצועק יותר מן הנצעק,\u0004 מי שצועק על חבירו לשמים יכול להיענש יותר מזה שצועקים עליו. ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אחד הצועק ואחד הנצעק,\u0004 כלומר, מי שצועקים בגללו \u0003במשמע\u0004 הכתוב המדבר בצעקת יתום על מענהו \"אם ענה תענה אותו כי אם צעוק יצעק אלי שמוע אשמע צעקתו. וחרה אפי והרגתי אתכם בחרב\" (שמות כב, כב–כג), הרי ששניהם, הצועק והנצעק, בכלל הגזירה, \u0003אלא שממהרין לצועק\u0004 לעונשו \u0003יותר מן הנצעק\u0004 כפי שמצאנו בשרה.","","","","","","\u0003ו\u0004עוד לימוד מפרשה זו של אברהם ואבימלך \u0003אמר ר' יצחק: לעולם אל תהי קללת הדיוט\u0004 (אדם פשוט) \u0003קלה בעיניך. שהרי אבימלך קלל את שרה ונתקיים\u0004 הדבר \u0003בזרעה, שנאמר: \"הנה הוא לך כסות עינים\"\u0004 (בראשית כ, טז). ופירושם של דברים, \u0003אמר לה: הואיל וכסית ממני ולא גילית שהוא אישך, וגרמת אלי הצער הזה, יהי רצון שיהו לך בני כסויי עינים. ונתקיים\u0004 הדבר \u0003בזרעה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי כי זקן יצחק ותכהין עיניו מראת\"\u0004 (שם כז, א). \u0003אמר ר' אבהו: לעולם יהא אדם מן הנרדפין ולא מן הרודפין,\u0004 וראיה לדבר: \u0003שאין לך נרדף בעופות יותר מתורים ובני יונה,\u0004 שכל הטורפים רודפים אחריהם, \u0003ו\u0004הם אלו ש\u0003הכשירן הכתוב\u0004 מבין כלל העופות \u0003לגבי מזבח,\u0004 משמע שיש מעלה גדולה בזה שהוא נרדף. שנינו במשנה: \u0003האומר \"סמא את עיני\",\u0004 בין שאמר הניזק במפורש שייפטר המזיק מתשלומים על כך, בין שלא אמר — הרי המזיק חייב. אבל האומר לחבירו להזיק את ממונו על מנת לפטור — פטור. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אסי בר חמא לרבא: מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[מה שונה תחילת\u0006 המשנה \u0005ומה שונה הסוף]\u0006 שלגבי גופו הוא חייב ולגבי בגדים הוא פטור?","","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רישא\u0004 \u0005[\u0006ב\u0005תחילת\u0006 המשנה\u0005]\u0006 ששנינו בה שחייב, למרות שאמר לו \"על מנת לפטור\" — \u0003לפי שאין אדם מוחל על ראשי אברים\u0004 שבגופו, כגון: עין, יד ורגל, שנאמרו במשנתנו, ומה שאמר \"על מנת לפטור\" — לא נתכוון לכך. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וכי אדם מוחל על צערו\u0004 אפילו כשלא חתך ראשי איברים שבגופו? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אמר לחבירו: \u0003\"הכני, פצעני, על מנת לפטור\"\u0004 — \u0003פטור?! אישתיק\u0004 \u0005[שתק]\u0006 רבא ולא מצא תשובה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 לרב אסי: \u0003מידי שמיע לך בהא\u0004 \u0005[האם שמעת דבר ב\u0006ענין \u0005זה]\u0006 בהסבר ההלכה שחייב המזיק בכל אופן בפגיעה בראשי איברים שבגופו? \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב ששת:\u0004 הטעם הוא \u0003משום פגם משפחה,\u0004 שמי שקוטעים את איבריו לא רק הוא מצטער, אלא גם משפחתו, ועל כך הוא אינו יכול למחול, אבל על צער בלבד יכול אדם למחול, וייפטר הלה אם יאמר לו \"על מנת לפטור\". \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בהסבר הדבר. \u0003ר' אושעיא אמר:\u0004 הטעם הוא \u0003משום פגם משפחה. רבא אמר: משום שאין אדם מוחל על ראשי אברים שלו.\u0004 \u0003ר' יוחנן אמר: יש \"הן\" שהוא כ\"לאו\",\u0004 שיש מקרים שלמרות שאומר \"הן\" אין הדבר נחשב כהסכמה, והרי זה כאילו אמר \"לא\", \u0003ו\u0004להיפך: \u0003יש \"לאו\" שהוא כ\"הן\",\u0004 שגם כשאומר \"לאו\" כוונתו להסכים לדבר. וכן כאן כשאומר \"על מנת לפטור\" אין הכוונה שהוא מתכוון באמת לכך. ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 אמר אדם לחבירו: \u0003\"הכני, פצעני\",\u0004 ושאלו החבר: \u0003\"על מנת לפטור\"? ואמר לו \"הן\"?! הרי\u0004 זה מקרה ש\u0003יש \"הן\" שהוא כ\"לאו\",\u0004 כאומר: וגם אם נתתי לך רשות לעשות זאת, האם סבור אתה שאמחל לך על התשלום?! אם אמר לו: \u0003\"קרע את כסותי\",\u0004 ואומר לו ההוא: \u0003\"על מנת לפטור\"? ואמר לו: לאו?! הרי \"לאו\" שהוא כ\"הן\",\u0004 שכוונתו לומר שאם לא היה רוצה לפוטרו לא היה מבקש ממנו לקרוע את בגדו. כ שנינו במשנה שאם אמר אדם לחבירו \u0003\"שבר את כדי\",\u0004 או \u0003\"קרע את כסותי\"\u0004 ועשה השני כדבריו — \u0003חייב. ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005],\u0006 נאמר בדיני שומרים שבתורה: \u0003\"\u0004כי יתן איש אל רעהו כסף או כלים \u0003לשמר\"\u0004 (שמות כב, ו), וכן \"כי יתן איש אל רעהו חמור או כלים לשמור\" (שמות כב, ט), ולכל שומר יש מקרים בהם הוא מתחייב לשלם לבעלים על נזק שנגרם לפקדון, ודייקו חכמים: \u0003\"לשמור\"\u0004 — \u0003ולא\u0004 כשנתן לו \u0003לאבד, \"לשמור\"\u0004 — \u0003ולא\u0004 כשנתן לו \u0003לקרוע, \"לשמור\"\u0004 — \u0003ולא\u0004 כשנתן לו \u0003לחלק לעניים!\u0004 משמע שאין השומר חייב על דברים שאמר לו לקרוע, אפילו לא פירש \"על מנת לפטור\"! \u0003אמר רב הונא, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 משנתנו שמחייבת הריהי עוסקת במקרה \u0003דאתי לידיה\u0004 \u0005[שבא\u0006 הדבר \u0005לידו]\u0006 וכבר יש לו אחריות על הדבר, ואף אם אמר לו חבירו לקורעו — חייב. \u0003הא\u0004 \u0005[זו]\u0006 הברייתא שפוטרת עוסקת במקרה ש\u0003לא אתי לידיה\u0004 \u0005[בא\u0006 הדבר \u0005לידו].\u0006 והואיל ועשה כדברי חבירו — פטור. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה\u0004 לרב הונא: והרי \u0003\"לשמור\",\u0004 כלומר, מקרה שבו מתחייב שומר באחריות לחפץ, \u0003דאתי לידיה\u0004 \u0005[שבא לידו]\u0006 \u0003משמע,\u0004 ובזה עוסקת הברייתא, ולא ניתן לפרשה במקרה שלא בא הדבר לידו!","\u0003אלא אמר רבה: הא והא דאתא לידיה\u0004 \u0005[זו וזו\u0006 מדובר \u0005שבא לידו],\u0006 \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה]:\u0006 \u0003הא דאתא לידיה\u0004 \u0005[זו,\u0006 המשנה, עוסקת במקרה \u0005שבא לידו]\u0006 מתחילה \u0003בתורת שמירה,\u0004 ואינו נפטר אלא אם כן פוטרו במפורש. \u0003הא דאתא לידיה\u0004 \u0005[זו,\u0006 הברייתא, עוסקת במקרה \u0005שבא לידו]\u0006 \u0003בתורת קריעה.\u0004","מסופר: \u0003ההוא ארנקא\u0004 \u0005[ארנק אחד,\u0006 כיס מלא כסף\u0005]\u0006 של \u0003צדקה דאתי\u0004 \u0005[שהובא]\u0006 \u0003ל\u0004עיר \u0003פומבדיתא,\u0004 \u0003אפקדה\u0004 \u0005[הפקיד]\u0006 \u0003רב יוסף\u0004 את הארנק \u0003גבי ההוא גברא\u0004 \u0005[אצל אדם אחד],\u0006 \u0003פשע\u0004 (התרשל) \u0003בה\u0004 בשמירה, \u0003אתו גנבי\u0004 \u0005[באו גנבים]\u0006 ו\u0003גנבוה, חייביה\u0004 \u0005[חייב אותו]\u0006 \u0003רב יוסף\u0004 לשלם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי, והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"לשמור\"\u0004 — \u0003ולא לחלק לעניים,\u0004 משמע שדבר שמחלקים לעניים אין עליו דין שמירה!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עניי\u0004 העיר \u0003פומבדיתא מיקץ קיץ להו\u0004 \u0005[יש להם קיצבה קבועה\u0006 שהם מקבלים\u0005],\u0006 וכיון שיש לכל עני קיצבה קבועה, יכול הוא לתבוע אותה, ולכן \u0003\"ולשמור\" הוא,\u0004",""],["\u0003הגוזל עצים ועשאן כלים,\u0004 או גזל גיזות \u0003צמר ועשאן בגדים\u0004 — \u0003משלם\u0004 לנגזל \u0003כ\u0004פי שהיה הדבר הנגזל שווה ב\u0003שעת הגזלה\u0004 ואינו צריך להחזיר לבעלים את הכלים או את הבגדים שעשה מגזילתו, שכן על ידי השינוי שעשה בהם קנאם.","אם \u0003גזל פרה מעוברת וילדה\u0004 ברשותו, או גזל \u0003רחל\u0004 (כבשה) \u0003טעונה\u0004 צמר \u0003וגזזה\u0004 — \u0003משלם דמי פרה העומדת לילד, ודמי רחל העומדת ליגזז,\u0004 כלומר, את שוויין בשעת הגזילה,","אבל את הוולד והגיזה הוא משאיר אצלו. אם \u0003גזל פרה ונתעברה\u0004 הפרה \u0003אצלו וילדה,\u0004 או שגזל \u0003רחל ונטענה אצלו\u0004 בצמר \u0003וגזזה\u0004 — \u0003משלם\u0004 ערך הפרה או הכבשה \u0003כשעת הגזלה. זה הכלל: כל הגזלנים משלמין כשעת הגזלה.\u0004","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 מן המשנה ניתן לדייק ולומר כי דווקא \u0003עצים ועשאן כלים\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 קונה אותם הגזלן בשינוי, אבל אם \u0003שיפן\u0004 (שייף והקציע) אותם בלבד — \u0003לא,\u0004 אין זה נקרא שינוי. וכן \u0003צמר ועשאן בגדים\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 הרי זה שינוי וקונה, אבל אם רק \u0003ליבנן\u0004 (רחץ אותן היטב) — \u0003לא.\u0004","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא: \u0003גזל עצים ושיפן, אבנים וסיתתן, צמר וליבנן, פשתן ונקהו\u0004 — \u0003משלם כשעת הגזלה!\u0004","\u0003אמר אביי:\u0004 אין זו סתירה, שכן ה\u0003תנא דידן\u0004 \u0005[שלנו,\u0006 במשנתנו\u0005]\u0006 \u0003קתני\u0004 \u0005[שונה]\u0006 סוג כזה של \u0003שינוי\u0004 שנחשב כשינוי רק \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 ואיזהו? — שינוי \u0003דהדרא\u0004 \u0005[ש\u0006הוא \u0005חוזר],\u0006 שאפשר להחזיר את הדבר הגזול למצב שהיה בו קודם, ושנינו במשנתנו ששינוי כזה קונה, \u0003וכל שכן שינוי דאורייתא\u0004 \u0005[שמן התורה],\u0006 שהוא שינוי שאינו חוזר, מקנה לגזלן את החפץ, ואת המקרה המוזכר במשנה","\u0003עצים ועשאן כלים\u0004 יש לפרש שמדובר כאן \u0003בעצים משופין\u0004 שגזל, \u0003ומאי נינהו\u0004 \u0005[ומה הם]?\u0006 — \u0003נסרים\u0004 (קרשים) שחיברם ועשה מהם כלי (כגון ארון) ש\u0003שינוי דהדר לברייתא\u0004 \u0005[שחוזר לברייתו]\u0006 \u0003הוא, דאי בעי משליף להו\u0004 \u0005[שאם\u0006 הוא \u0005רוצה\u0006 הוא יכול הוא בכל עת \u0005לשלוף,\u0006 לפרק, \u0005אותם]\u0006 ולהחזירם למצבם הקודם, וכן \u0003צמר ועשאן בגדים\u0004 מדובר פה \u0003בצמר\u0004 שהיה כבר \u0003טווי,\u0004 ש\u0003שינוי דהדר לברייתא\u0004 \u0005[שחוזר לברייתו]\u0006 \u0003הוא, דאי בעי סתר ליה\u0004 \u0005[שאם\u0006 הוא \u0005רוצה\u0006 הריהו \u0005סותר,\u0006 פורם, \u0005אותו\u0006 את הבגד\u0005]\u0006 ומחזיר אותו להיות חוטים, והרי זה שינוי מדברי חכמים שקונה, \u0003וכל שכן שינוי דאורייתא\u0004 \u0005[שמן התורה]\u0006 שינוי שאינו חוזר, שוודאי נקנה גוף החפץ לגזלן.","\u0003ו\u0004אילו ה\u0003תנא ברא\u0004 \u0005[החיצון]\u0006 בברייתא, \u0003שינוי דאורייתא קתני\u0004 \u0005[שמן התורה שונה],\u0006 \u0003ושינוי דרבנן\u0004 \u0005[שמדברי סופרים]\u0006 \u0003לא קתני\u0004 \u0005[שונה],\u0006 ויש לומר שלשיטתו אינו מקנה את החפץ לגזלן.","\u0003רב אשי אמר\u0004 תירוץ אחר: ה\u0003תנא דידן נמי\u0004 \u0005[שלנו גם כן]\u0006 \u0003שינוי דאורייתא קתני\u0004 \u0005[שמן התורה שונה],\u0006 כי \u0003עצים ועשאן כלים\u0004 הנזכרים במשנתנו מדובר פה ב\u0003בוכאני\u0004 \u0005[עלי]\u0006 של מכתשת, \u0003דהיינו\u0004 \u0005[שזהו]\u0006 \u0003שיפן,\u0004 שעל ידי השיפוי (חיתוך וקיצוע) יוצר כלי, ואינו חוזר לברייתו. \u0003צמר ועשאן בגדים\u0004 כוונתו שעשאו \u0003נמטי\u0004 \u0005[לבד],\u0006 \u0003דהיינו\u0004 \u0005[שזהו]\u0006 \u0003שינוי\u0004 ש\u0003לא הדר\u0004 \u0005[חוזר].\u0006","ולגופו של הענין שהוזכר בברייתא שואלים: \u0003וליבון מי הוי\u0004 \u0005[האם הוא נחשב]\u0006 ל\u0003שינוי,\u0004 שאם גזל צמר וליבנו משלם כשעת הגזילה? \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בדיני ראשית הגז, שצריך לתת לכהן חלק מן הגיזה כמות שהוא: \u0003לא הספיק\u0004 הבעלים של הכבשים \u0003ליתנו לו\u0004 לכהן \u0003עד שצבעו\u0004 — \u0003פטור,\u0004 לפי שנשתנה מברייתו. אבל אם \u0003לבנו ולא צבעו\u0004 — \u0003חייב,\u0004 משמע שהליבון אינו נחשב לשינוי!","\u0003אמר אביי, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[זו\u0006 הברייתא\u0005]\u0006 כשיטת \u0003ר' שמעון, הא רבנן\u0004 \u0005[זו,\u0006 המשנה, כשיטת \u0005חכמים].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בדיני ראשית הגז: \u0003גזזו, טוואו וארגו\u0004 — \u0003אין מצטרף\u0004 לשיעור שחל עליו חיוב הפרשת ראשית הגז. שאין ראשית הגז אלא מצמר כברייתו בלבד, ואם עשה בחלק מן הצמר שינוי, אינו חייב בראשית הגז, ואינו מצטרף עם הצמר האחר לכדי שיעור. ואם \u0003לבנו\u0004 — \u0003ר' שמעון אומר: אין מצטרף,\u0004 משום שלדעתו שינוי הוא זה, והוא כדברי הברייתא לענין גזילה שיקנה בשינוי. \u0003וחכמים אומרים: מצטרף,\u0004 שלדעתם אין זה נחשב שינוי, וכדברי המשנה בענין ראשית הגז.","\u0003רבא אמר\u0004 תירוץ אחר: \u0003הא והא\u0004 \u0005[זו וזו]\u0006 כשיטת \u0003ר' שמעון, ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה]:\u0006 \u0003הא דנפציה נפוצי\u0004 \u0005[זה,\u0006 במשנה, מדובר באופן \u0005ש\u0006רק \u0005ניפץ אותו],\u0006 כלומר, הפריד בידיו את הצמר לפני הליבון, ואין הליבון נחשב שינוי, \u0003הא דסרקיה סרוקי\u0004 \u0005[זה,\u0006 בברייתא, מדובר \u0005שסירק אותו]\u0006 קודם, ולכן מחשיב את הליבון כשינוי של ממש.","\u0003ר' חייא בר אבין אמר\u0004 תירוץ אחר: \u0003הא דחווריה חוורי\u0004 \u0005[זה,\u0006 במשנה, מדובר באופן \u0005שהלבין אותו]\u0006 בלבד, שאינו נחשב לשינוי, \u0003הא דכבריה כברויי\u0004 \u0005[זה,\u0006 בברייתא, מדובר באופן \u0005שליבן אותו בגופרית]\u0006 שהוא שינוי שאינו חוזר.","ובכל אופן נמצא שלדעת ר' שמעון ליבון הריהו שינוי, ותוהים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003יש לומר\u0004 הרי אתה אומר ש\u0003צבע ל\u0004שיטת \u0003ר' שמעון לא הוי\u0004 \u0005[אין הוא\u0006 נחשב\u0005]\u0006 \u0003שינוי,\u0004 וכי \u0003ליבון הוי\u0004 \u0005[הוא נחשב]\u0006 \u0003שינוי?\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003גזז ראשון ראשון,\u0004 כלומר, בזה אחר זה מן הכבשים \u0003וצבעו, ראשון ראשון וטוואו, ראשון ראשון וארגו\u0004 — \u0003אין מצטרף\u0004 לשיעור צמר עליו חל חיוב הפרשת ראשית הגז, \u0003ר' שמעון בן יהודה אומר משום\u0004 (בשם) \u0003ר' שמעון:\u0004 אם \u0003צבעו\u0004 — \u0003מצטרף.\u0004 משמע שאפילו צביעה אינה נחשבת בעיניו כשינוי!","\u0003אמר אביי, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[זו]\u0006 מה ששנינו קודם שליבון אינו מצטרף היא שיטת \u0003רבנן אליבא\u0004 \u0005[חכמים על פי שיטתו]\u0006 של \u0003ר' שמעון,\u0004 \u0003הא\u0004 \u0005[\u0006ו\u0005זו]\u0006 שיטת \u0003ר' שמעון בן יהודה אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' שמעון,\u0004 שצבעו מצטרף, וכל שכן ליבנו. והם חלוקים בדבר שיטתו.","\u0003רבא אמר: לעולם\u0004 תפרש ש\u0003לא פליגי רבנן עליה\u0004 \u0005[חולקים חכמים עליו],\u0006 על \u0003ר' שמעון בן יהודה,\u0004 שכולם סבורים שליבון הריהו שינוי לדעת ר' שמעון, \u0003ושאני\u0004 \u0005[ושונה]\u0006 \u0003צבע\u0004 שאינו נחשב שינוי, \u0003הואיל ויכול להעבירו על ידי צפון\u0004 (סבון), וכיון שכך הרי זה כשינוי החוזר לברייתו. \u0003וכי קתני התם\u0004 \u0005[ומה ש\u0006הוא \u0005שונה שם]\u0006 \u0003לא הספיק ליתנו לו עד שצבעו\u0004 — \u0003פטור, ואוקימנא\u0004 \u0005[והעמדנו\u0006 דבר זה\u0005]\u0006 \u0003כדברי הכל,\u0004 הרי זה לא בצבע סתם אלא \u0003ב\u0004צבע הקרוי \u0003קלא אילן\u0004 ש\u0003לא עבר\u0004 \u0005[עובר]\u0006 על ידי סבון.","\u0003אמר אביי: ר' שמעון בן יהודה ובית שמאי ור' אליעזר בן יעקב ור' שמעון בן אלעזר ור' ישמעאל, כולהו סבירא להו\u0004 \u0005[כולם סבורים הם]:\u0006 \u0003שינוי במקומו עומד,\u0004 כלומר, אין דבר יוצא מרשות בעליו הראשונים ומדינו הראשון אף על פי שנעשה בו שינוי. וזהו פירוט השיטות: \u0003ר' שמעון בן יהודה, הא דאמרן\u0004 \u0005[זה שאמרנו]\u0006 עתה בשמו לשיטת ר' שמעון שצביעה אינה נחשבת לשינוי.","\u0003בית שמאי מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 שיטתם? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נתן לה\u0004 לזונה \u0003חטין באתננה ועשאן\u0004 (ועשתה אותן) \u0003סולת,\u0004 או נתן לה \u0003זיתים\u0004 — \u0003ועשאן שמן, ענבים\u0004 — \u0003ועשאן יין\u0004 והקדישתם, \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003אסור\u0004 להקריבם על המזבח, כמנחה וכנסכים, משום אתנן זונה, שנאמר בתורה: \"לא תביא אתנן זונה... בית ה' אלהיך\" (דברים כג, יט). \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 ש\u0003מותר. ואמר רב יוסף, תני\u0004 \u0005[שנה]\u0006 החכם \u0003גוריון\u0004"],["\u0003דמאספורק: בית שמאי אוסרין, ובית הלל מתירין,\u0004 ואין זו סתירה איפוא בין ברייתות אלא כל ברייתא כשיטת אחד מהם. ולאחר שלמדנו שכדעת בית שמאי היא הברייתא האוסרת מבררים \u0003מאי טעמיה\u0004 \u0005[מה טעמו,\u0006 טעמם\u0005]\u0006 של \u0003בית שמאי\u0004 שאוסרים? — \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004לא תביא אתנן זונה ומחיר כלב בית ה' אלהיך לכל נדר כי תועבת ה' אלהיך \u0003גם שניהם\"\u0004 (דברים כג, יט), \"גם\" הוא לשון ריבוי — \u0003לרבות שינוייהם. ובית הלל\u0004 מה טעמם? \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"הם\"\u0004 להדגיש: \u0003ולא שינוייהם.\u0004","ויש לשאול: \u0003ובית שמאי\u0004 מה הם עונים על כך? ו\u0003הא כתיב\u0004 \u0005[הרי כתוב]\u0006 \u0003\"הם\"!\u0004 ומשיבים: לשון \"הם\" \u0003ההוא מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 ללמדנו ש\u0003הם\u0004 אסורים \u0003ולא ולדותיהם. ובית הלל\u0004 מנין להם הלכה זו של וולדות? \u0003תרתי שמעת מינה\u0004 \u0005[שני\u0006 דברים \u0005אתה שומע מכאן]:\u0006 \u0003הם\u0004 — \u0003ולא שינוייהם, הם\u0004 — \u0003ולא ולדותיהם,\u0004 שהרי הכתוב עומד על כך שיהיו הם = כמות שהם.","ושואלים: \u0003ובית הלל נמי\u0004 \u0005[גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"גם\"\u0004 שהיא לשון ריבוי! ואומרים: אכן \u0003\"גם\" לבית הלל קשיא\u0004 \u0005[קשה],\u0006 שאין ברור לנו כיצד הם מפרשים אותו.","\u0003ר' אליעזר בן יעקב מאי היא\u0004 \u0005[מה הוא]\u0006 הענין שאמרנו שהוא סבור ששינוי במקומו עומד?","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: הרי שגזל סאה של חטין,\u0004 ואחר כך \u0003טחנה, לשה ואפאה ו\u0004אחרי כל זה \u0003הפריש ממנה חלה, כיצד מברך\u0004 על הפרשת חלה זו? — \u0003אין זה מברך אלא מנאץ\u0004 (מקלל), \u0003ועל זה נאמר: \"\u0004ו\u0003בצע ברך נאץ ה'\"\u0004 (תהלים י, ג), שגזלן (בוצע בצע) המברך על מצוה שעושה בגזילה שגזל — אינו אלא מנאץ את ה'. משמע שהוא סבור שלמרות שעשה בחטים כל כך הרבה שינויים, עדיין השינוי במקומו עומד ואינו נחשב כקניינו של הגזלן.","\u0003ר' שמעון בן אלעזר מאי היא\u0004 \u0005[מה הוא]\u0006 הענין שבו הוא מביע את דעתו ששינוי אינו קונה? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],:\u0006 \u0003כלל זה אמר ר' שמעון בן אלעזר: כל שבח שהשביח גזלן\u0004 את הגזילה — \u0003ידו\u0004 של הגזלן \u0003על העליונה\u0004 בטענותיו כלפי הנגזל, \u0003רצה\u0004 — \u0003נוטל שבחו, רצה\u0004 — \u0003אומר לו \"הרי שלך לפניך\".\u0004","ותוהים: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר],\u0006 מה פירוש הדברים, וכי יעלה על הדעת שיאמר הגזלן לנגזל במקרה ששבחה הגזילה \"הרי שלך לפניך\"? \u0003אמר רב ששת, הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 אם \u0003השביחה\u0004 הגזלן את הגזילה — \u0003נוטל\u0004 הגזלן את \u0003שבחו,\u0004 שהשביחה הבהמה על ידו. אם \u0003כחש\u0004 הדבר הנגזל — \u0003אומר לו\u0004 הגזלן \u0003\"הרי שלך לפניך\",\u0004 ומדוע? מפני ש\u0003שינוי במקומו עומד.\u0004 ואינו נחשב כקנין, ולכן הוא מחזיר לו את השייך לו.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאתה אומר ששינוי במקומו עומד, אם כן \u0003אפילו השביח נמי\u0004 \u0005[גם כן],\u0006 לא יהא זכאי הגזלן לקבל את מה שהשביח? \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: שם עשו זאת \u0003מפני תקנת השבים,\u0004 כדי להקל על בעלי תשובה שאם השביח יקבל את מה שהשביח, ולא יימנע הגזלן מלעשות תשובה בגלל החשש שיצטרך להחזיר גם את השבח.","\u0003ר' ישמעאל מאי היא\u0004 \u0005[מה הוא]\u0006 הענין שאמר בו ששינוי במקומו עומד? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מצות פאה\u0004 היא \u0003להפריש\u0004 פאה \u0003מן הקמה,\u0004 כלומר, מן התבואה שלא נקצרה עדיין. \u0003לא הפריש מן הקמה\u0004 — \u0003מפריש מן העומרים\u0004 (קבוצת שבלים שנקצרו), \u0003לא הפריש מן העומרים\u0004 — \u0003מפריש מן הכרי\u0004 (ערימת תבואה) \u0003עד שלא מרחו\u0004 (סידר ויישר אותו),","\u0003מרחו\u0004 וחלה עליו חובת מעשרות — \u0003מעשר\u0004 תחילה את התבואה \u0003ו\u0004אחר כך \u0003נותן לו\u0004 לעני את הפאה, שלא יפסיד העני שיצטרך הוא עצמו להפריש מעשר ממה שקיבל. ואילו \u0003משום\u0004 (בשם) \u0003ר' ישמעאל אמרו: אף\u0004 אם לא הפריש פאה בכל השלבים הללו ועשה עיסה הריהו \u0003מפריש מן העיסה ונותן לו,\u0004 משמע שאפילו שנעשה שינוי בתבואה — אין זה פוטר אותו מחובת נתינה זו. עד כאן פירטה הגמרא את דעות האומרים ששינוי במקומו עומד, וכדברי אביי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: איכפל\u0004 \u0005[וכי טרחו]\u0006 נאספו יחד \u0003כל הני תנאי לאשמועינן\u0004 \u0005[התנאים הללו\u0006 כדי \u0005להשמיע לנו]\u0006 \u0003כ\u0004דעת \u0003בית שמאי\u0004 שמן הסתם אינה הלכה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי קאמרי\u0004 \u0005[כך\u0006 הם \u0005אומרים]:\u0006 \u0003לא נחלקו בית שמאי ובית הלל בדבר זה.\u0004 כלומר, שכל התנאים הללו סבורים שענין זה ששינוי אינו משנה את המצב המקורי הוא לדעת הכל, ולא נתון במחלוקת בית הלל ובית שמאי.","\u0003אמר רבא: ממאי\u0004 \u0005[מנין]\u0006 מוכיח אתה שכל אותם תנאים סבורים ששינוי במקומו עומד? כי כל הראיות שהבאת מהתנאים האלו לגבי שינוי אינם ראיות מכריעות, כיצד? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' שמעון בן יהודה התם\u0004 \u0005[שם]\u0006 לענין ראשית הגז \u0003אלא בצבע\u0004 שאינו נחשב שינוי, \u0003הואיל ויכול להעבירו על ידי צפון.\u0004","\u0003ועד כאן לא\u0004 שמענו כי \u0003קאמרי\u0004 \u0005[אומרים]\u0006 \u0003בית שמאי התם\u0004 \u0005[שם]\u0006 שגם אתנן שנשתנה נאסר \u0003אלא\u0004 משום שהוא נמסר \u0003לגבוה\u0004 (לקרבן לה'), \u0003משום דאימאיס\u0004 \u0005[שנעשה מאוס]\u0006 בהיותו אתנן ולכן אין ראוי להקריבו גם אם נעשה בו שינוי.","\u0003ועד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' אליעזר בן יעקב התם\u0004 \u0005[שם]\u0006 במפריש חלה ומברך עליה \u0003אלא לענין ברכה, משום דהוה ליה\u0004 \u0005[שהרי זו]\u0006 \u0003מצוה הבאה בעבירה,\u0004 שגוזל דבר ומברך עליו,","אבל לא שנחשב הדבר שלו בדיני קניינים. \u0003ועד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' שמעון בן אלעזר התם\u0004 \u0005[שם]\u0006 בגזלן שרשאי להחזיר בהמה שהכחישה כמות שהיא \u0003אלא בהכחשה דהדר\u0004 \u0005[שחוזרת],\u0006 שיכולה להשתנות על ידי פיטום הבהמה, שתחזור לכמות שהיתה, ואין זה שינוי גמור.","\u0003ועד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' ישמעאל התם\u0004 \u0005[שם]\u0006 שמחוייב להפריש פאה אף מן העיסה \u0003אלא לענין פאה, משום דכתיב\u0004 \u0005[שנאמר\u0006 בה\u0005]:\u0006 \u0003\"תעזב\"\u0004 (ויקרא יט, י. וכן שם כג, כב) \u0003יתירא\u0004 \u0005[יתר]\u0006 שאנו למדים מכאן שמכל מקום צריך לתת פאה אף אם השתנתה התבואה והיתה לעיסה. \u0003וכי תימא, ליגמר מיניה\u0004 \u0005[ואם תאמר נלמד ממנו]\u0006 שגם בדברים אחרים אין שינוי קונה, על כך יש להשיב כי \u0003מתנות עניים שאני\u0004 \u0005[שונות\u0006 הן\u0005]\u0006 שיש להן דין מיוחד זה.","וראיה לדברי רבא שלא ניתן להוכיח בוודאות מדברי ר' ישמעאל לענין זה, \u0003כדבעי\u0004 \u0005[כפי ששאל]\u0006 \u0003ר' יונתן, דבעי\u0004 \u0005[ששאל]\u0006 \u0003ר' יונתן: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' ישמעאל?\u0004 האם \u0003משום דקסבר\u0004 \u0005[ש\u0006הוא \u0005סבור]\u0006 ש\u0003שינוי אינו קונה, או דלמא בעלמא קסבר\u0004 \u0005[שמא בכלל סבור\u0006 הוא\u0005]\u0006 ש\u0003שינוי קונה, והכא\u0004 \u0005[וכאן]\u0006 הדין כן \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"תעזב\" יתירא?\u0004","ואגב שהובא ענין זה שואלים: \u0003ואם תמצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 כי \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' ישמעאל משום דקסבר\u0004 \u0005[ש\u0006הוא \u0005סבור]\u0006 \u0003שינוי אינו קונה,\u0004 אם כן \u0003\"תעזב\" יתירא\u0004 \u0005[יתר]\u0006 \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003למה לי? ותו\u0004 \u0005[ועוד]:\u0006 \u0003לרבנן\u0004 \u0005[לחכמים]\u0006 החולקים על ר' ישמעאל וסבורים שאינו יכול להפריש פאה מן העיסה \u0003\"תעזב\" יתירא\u0004 \u0005[יתר]\u0006 \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003למה לי?\u0004","ומשיבים: \u0003מבעי ליה לכדתניא\u0004 \u0005[נצרך\u0006 \u0005הוא\u0006 הדבר \u0005לכמו ששנוי\u0006 בברייתא\u0005]:\u0006 \u0003המפקיר כרמו, והשכים לבקר\u0004 לפני שזכה בו אחר, \u0003ובצרו\u0004 — \u0003חייב בפרט ובעוללות ובשכחה ובפאה, ו\u0004אף ש\u0003פטור מן המעשר\u0004 כדין הפקר שפטור מן המעשר, משום שלגבי מתנות עניים (ולא במעשר) נאמרה בתורה מצוה יתירה של נתינה (\"תעזוב\") שמכל מקום צריך לתת.","ולענין שינוי בגזילה \u0003אמר רב יהודה אמר שמואל: הלכה כ\u0004שיטת \u0003ר' שמעון בן אלעזר\u0004 שאמר שאף שכחשה הבהמה שנגזלה מחזיר אותה לבעלים, ולא קנה אותה הגזלן בכך.","ותוהים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר שמואל הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: אין שמין לא לגנב ולא לגזלן אלא לנזקין\u0004 בלבד. ששור שהמית שורו של אחר, מחזיר בעל השור הנוגח את הנבילה לבעלים, ושמים כמה הפסיד על ידי מיתה. אבל גנב וגזלן שכחשה הגזילה שבידם, אינם יכולים להחזירה כמות שהיא ולהוסיף את דמי הפחת, אלא מחזירים דמים כשעת הגזילה.","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבא,\u0004 ש\u0003אמר\u0004 לעיל, כשדחה את דברי אביי: \u0003כי קאמר\u0004 \u0005[כאשר אומר]\u0006 \u0003ר' שמעון בן אלעזר התם\u0004 \u0005[שם]\u0006 הרי זה דווקא \u0003בהכחשה דהדר\u0004 \u0005[שחוזרת],\u0006 אם כן \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן \u0003כי קאמר\u0004 \u0005[כאשר הוא אומר]\u0006 ש\u0003הלכה כ\u0004שיטת \u0003ר' שמעון בן אלעזר\u0004 הסובר ש\u0003שינוי במקומו עומד,\u0004 כוונתו היא \u0003בהכחשה דהדר\u0004 \u0005[שחוזרת]\u0006 שלכן אין השינוי נחשב, \u0003וכי קאמר שמואל התם\u0004 \u0005[וכאשר אמר שמואל שם]:\u0006 \u0003אין שמין לא לגנב ולא לגזלן אלא לנזקין\u0004 הוא דיבר \u0003בהכחשה\u0004 ש\u0003לא הדר\u0004 \u0005[חוזרת].\u0006","\u0003אלא לאביי,\u0004 ש\u0003אמר: כי קאמר\u0004 \u0005[כאשר אומר]\u0006 \u0003ר' שמעון בן אלעזר\u0004 אפילו \u0003בהכחשה דלא הדר קאמר\u0004 \u0005[שאינה חוזרת\u0006 הוא \u0005אומר],\u0006 אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 כיצד סותר שמואל את עצמו?","ומשיבים: \u0003אביי מתני הכי\u0004 \u0005[שונה כך],\u0006 גורס את השמועה הזו בלשון אחרת: \u0003אמר רב יהודה אמר שמואל:\u0004"],["\u0003אמרו\u0004 ש\u0003הלכה כר' שמעון בן אלעזר, ו\u0004אולם \u0003ליה\u0004 \u0005[לו\u0006 עצמו\u0005]\u0006 \u0003לא סבירא ליה\u0004 \u0005[סבור,\u0006 נראה \u0005לו\u0006 כן\u0005].\u0006","ועוד בענין זה של שינוי \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: דבר תורה\u0004 (מדין תורה) \u0003גזילה\u0004 גם זו \u0003הנשתנית\u0004 (שהשתנתה) \u0003חוזרת בעיניה,\u0004 כפי שהיא עכשיו עם השינוי שבה, \u0003שנאמר: \"והשיב את הגזלה אשר גזל\"\u0004 (ויקרא ה, כג), כוונתו: והשיב אותה \u0003מכל מקום. ואם תאמר: משנתנו\u0004 שאינה אומרת כן, אלא נאמר בה שמחזיר דמים בלבד! — אותה קבעו חכמים \u0003משום תקנת השבים.\u0004","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: הלכה כסתם משנה, ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006 בענין ראשית הגז: \u0003לא הספיק\u0004 הבעלים \u0003ליתנו\u0004 את הצמר \u0003לו,\u0004 לכהן, \u0003עד שצבעו\u0004 — \u0003פטור,\u0004 משמע שצביעה שהיא שינוי יוצרת קנין!","\u0003אמר להו ההוא מדרבנן\u0004 \u0005[להם אחד החכמים]\u0006 \u0003ור' יעקב שמיה\u0004 \u0005[שמו]:\u0006 \u0003לדידי מפרשא לי מיניה\u0004 \u0005[לי עצמי נתפרשה\u0006 המשנה \u0005ממנו,\u0006 על ידי\u0005]\u0006 \u0003ר' יוחנן,\u0004 שמדובר במקרה \u0003כגון שגזל עצים משופין ועשאן כלים, דהוה ליה\u0004 \u0005[שהריהו]\u0006 \u0003שינוי החוזר לברייתו,\u0004 ובשינוי החוזר לברייתו מן התורה אינו קונה, והמשנה תקנת חכמים היא.","אגב מה שדברנו בתקנת השבים דנים עתה בכמה עניינים הנוגעים בזה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הגזלנין ומלוי ברבית שהחזירו\u0004 למי שלקחו ממנו את הגזילה או הריבית — \u0003אין מקבלין מהן, והמקבל מהן\u0004 — \u0003אין רוח חכמים נוחה הימנו\u0004 מפני שמרפה בכך ידיהם של הרוצים לחזור בתשובה.","\u0003אמר ר' יוחנן: בימי רבי נשנית משנה\u0004 (ברייתא) \u0003זו. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעשה באדם אחד\u0004 גזלן \u0003שבקש לעשות תשובה\u0004 על כל גזילותיו, \u0003אמרה לו אשתו: ריקה\u0004 (שוטה), \u0003אם אתה עושה תשובה\u0004 תצטרך להשיב כל דבר לבעליו, ו\u0003אפילו אבנט\u0004 שאתה לובש \u0003אינו שלך! ונמנע ולא עשה תשובה. באותה שעה אמרו\u0004 חכמים: \u0003הגזלנין ומלוי רביות שהחזירו\u0004 — \u0003אין מקבלין מהם, והמקבל מהם\u0004 — \u0003אין רוח חכמים נוחה הימנו,\u0004 שעל ידי זה מונע אותם מלעשות תשובה.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: בנים ש\u0003הניח להם אביהם מעות של רבית\u0004 (שהרוויח על ידי לקיחת רבית), \u0003אף על פי שהן,\u0004 הבנים, \u0003יודעין שהן\u0004 מעות \u0003רבית\u0004 — \u0003אין חייבין להחזיר.\u0004 ונדייק: \u0003אינהו\u0004 \u0005[הם]\u0006 \u0003הוא\u0004 ש\u0003לא\u0004 חייבים להחזיר. \u0003הא\u0004 \u0005[אבל]\u0006 \u0003אביהם\u0004 עצמו \u0003חייב להחזיר\u0004 ומקבלים ממנו.","ומשיבים: אין לדייק כן, שכן \u0003בדין\u0004 (מן הדין) \u0003הוא\u0004 ש\u0003אביהם נמי\u0004 \u0005[גם כן]\u0006 \u0003אינו חייב להחזיר, והא דקתני בדידהו\u0004 \u0005[וזה ששנה\u0006 בברייתא את ההלכה \u0005בהם]\u0006 — טעם הדבר הוא \u0003משום דקא בעי למתני סיפא\u0004 \u0005[שרצה לשנות\u0006 ב\u0005סוף\u0006 הברייתא\u0005]\u0006 את ההלכה: \u0003הניח להם אביהם פרה וטלית וכל דבר\u0004 אחר \u0003המסויים\u0004 (מוגדר ומוכר) שגזל — \u0003חייבין להחזיר\u0004 אותם \u0003מפני כבוד אביהם\u0004 שלא ייזכר תמיד שזה הדבר שגזל אדם פלוני, והלכה זו היא דווקא בבנים, משום כך \u0003תנא רישא נמי בדידהו\u0004 \u0005[שנה\u0006 ב\u0005תחילת\u0006 הברייתא \u0005גם כן בהם\u0006 בבנים\u0005].\u0006","ושואלים: \u0003ומפני כבוד אביהם חייבין להחזיר?\u0004 מדוע חייבים להחזיר? \u0003אקרי\u0004 \u0005[קרא]\u0006 \u0003כאן\u0004 כמו שנאמר: \u0003\"ונשיא בעמך לא תאר\"\u0004 (שמות כב, כז), ודייקו חכמים שהכתוב מדבר דווקא \u0003בעושה מעשה עמך,\u0004 אבל המקלל נשיא רשע אינו עובר על איסור זה. והוא הדין לכיבוד אב, שאם אינו נוהג כראוי אין צריך לחשוש לכבודו, ומדוע צריכים הבנים להחזיר משום כבוד אביהם הגזלן?","ומשיבים: \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003רב פנחס\u0004 בענין אחר, שמדובר \u0003בשעשה\u0004 האיש \u0003תשובה, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בשעשה\u0004 האב \u0003תשובה\u0004 ואין הוא עוד רשע וחייבים הבנים בכבודו. ותוהים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003עשה תשובה, מאי בעי גביה\u0004 \u0005[מה עושה\u0006 הדבר \u0005אצלו]?\u0006 הלא \u0003איבעי ליה לאהדורי\u0004 \u0005[היה צריך לו להחזיר]\u0006 את הגזילה! ומשיבים: מדובר שם \u0003שלא הספיק להחזיר עד שמת,\u0004 ובמקרה כזה צריכים הבנים להחזיר אם הוא דבר המסויים, מפני כבוד אביהם.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת ממה ששנינו בברייתא: \u0003הגזלנים ומלוי ברבית אף על פי שגבו\u0004 — \u0003מחזירין.\u0004","ותחילה מבררים את לשון הברייתא: לגבי \u0003גזלנין מאי\u0004 \u0005[מה]\u0006 \u0003\"שגבו\" איכא\u0004 \u0005[יש],\u0006 מה לשון \"שגבו\" שייכת בגזלנים? שהרי \u0003אי גזול\u0004 \u0005[אם גזלו]\u0006 — \u0003גזול\u0004 \u0005[גזלו],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא גזול\u0004 \u0005[גזלו]\u0006 — \u0003לא גזול\u0004 \u0005[גזלו]\u0006 ואין כאן גבייה כלל! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן את הלשון כך: \u0003הגזלנין, ומאי ניהו\u0004 \u0005[ומה הם]\u0006 הגזלנים — \u0003מלוי רביות, אף על פי שגבו\u0004 את הריבית — \u0003מחזירין,\u0004 והרי זה שלא כדברינו שאין מקבלים מגזלנים וממלוי בריבית! \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה על כך: אמנם הם \u0003מחזירין ו\u0004אולם \u0003אין מקבלין מהם.\u0004","ושואלים: \u0003אלא למה מחזירין\u0004 אם אין מקבלים מהם? ומשיבים: כדי \u0003לצאת ידי שמים.\u0004 שכדי שתהא תשובתם שלימה צריכים הם לפחות להציע ללווים ששילמו הריבית את האפשרות לקבל את השייך להם.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת ממה ששנינו בברייתא: \u0003הרועים\u0004 שרועים את בהמותיהם בשדות אחרים, וגוזלים בכך את בעליהם, \u0003והגבאין\u0004 שנשכרים לגבות מיסים ולוקחים יותר מן הראוי, \u0003והמוכסין\u0004 שמקבלים את זכות המכס וגובים שלא כדין — \u0003תשובתן קשה,\u0004 משום שגוזלי הרבים הם וקשה להם להחזיר לכל מי שלקחו ממנו, \u0003ומחזירין למכירין,\u0004 לאותם אנשים שהם מכירים ויודעים שלקחו מהם. ומשמע שבכל זאת מחזירים!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: אמנם הם \u0003מחזירין ו\u0004אולם \u0003אין מקבלין מהם.\u0004 ושואלים: \u0003ואלא למה מחזירין?\u0004 ומשיבים: כדי \u0003לצאת ידי שמים.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שבעצם אין עליהם חובת החזרה, \u0003אמאי\u0004 \u0005[מדוע\u0006 אתה אומר\u0005]\u0006 ש\u0003תשובתן קשה?\u0004 הרי אין הדבר יותר קשה להם מלאחרים, שהרי גם הם אינם צריכים להחזיר בפועל!","\u0003ועוד, אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של הברייתא\u0005]:\u0006 \u0003ו\u0004אותם כספים \u0003שאין מכירין\u0004 את האנשים שמהם נלקחו — \u0003יעשה בהן צרכי ציבור, ואמר רב חסדא:\u0004 הכוונה לדברים כגון \u0003בורות, שיחין ומערות,\u0004 שהציבור כולו נהנה מהם ועל ידי כך נמצא שמחזירים לציבור מה שגזלו ממנו. ואם כן הרי שמקבלים מהם! \u0003אלא\u0004 צריכים לתרץ באופן אחר, \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן\u0004 שאמרו שמחזירים בפועל מדובר \u0003קודם תקנה, כאן\u0004 שאמרו שאין צריכים להחזיר מדובר \u0003לאחר תקנה.\u0004","ומעירים: \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 ש\u0003אמר רב נחמן\u0004 והסביר שמה שאמרו שאין מחזירים הוא דווקא \u0003בשאין גזילה קיימת\u0004 בעינה, \u0003אפילו תימא אידי ואידי\u0004 \u0005[תאמר\u0006 ש\u0005זה וזה]\u0006 מדברים בזמן ש\u0003לאחר תקנה\u0004 ניתן לפרש את הדברים, \u0003ולא קשיא\u0004 \u0005[קשה];\u0006"],["\u0003כאן\u0004 שאמרו שחייב להחזירה מדובר \u0003בגזילה קיימת, כאן\u0004 שאמרו שאין מקבלים מידו, אפילו כשבא לצאת ידי שמים מדובר \u0003בשאין גזילה קיימת.\u0004 ומקשים על כך: \u0003והא\u0004 \u0005[והרי]\u0006 מעשה זה ב\u0003אבנט,\u0004 שאמרה לו אשתו של אותו גזלן שגם האבנט אינו שלו שבעקבותיו תיקנו חכמים שאינו צריך להחזיר מקרה ש\u0003גזילה קיימת היא\u0004 ובמקרה שכזה הרי היה צריך להחזיר מן הדין! ומשיבים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"אבנט\"\u0004 שאמרה לו אשתו שיצטרך להחזיר, ותיקנו חכמים שאינו צריך? — \u0003דמי אבנט,\u0004 שהאבנט עצמו כבר לא היה בידו.","ושואלים: \u0003וכל היכא\u0004 \u0005[היכן]\u0006 שה\u0003גזילה קיימת, לא עבוד רבנן תקנתא\u0004 \u0005[עשו חכמים תקנה]\u0006 לבעלי תשובה? \u0003והרי מריש\u0004 (קורה) ש\u0003גזילה קיימת היא, ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 שתיקנו חכמים \u0003על המריש הגזול שבנאו בבירה\u0004 (בנין, מגדל) \u0003שיטול\u0004 הנגזל את \u0003דמיו,\u0004 ולא את המריש עצמו \u0003מפני תקנת השבים\u0004 שלא יצטרך להרוס את הבנין, משמע שגם פה עשו תקנה! ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 ש\u0003כיון דאיכא פסידא\u0004 \u0005[שיש הפסד]\u0006 של כל ה\u0003בירה\u0004 כולה, שצריכים להרוס אותה, \u0003שויוה רבנן כדליתא\u0004 \u0005[עשו אותה חכמים כאילו אינה\u0006 קיימת\u0005].\u0006","ועוד בביאור המשנה, שנינו שמי ש\u0003גזל פרה מעוברת וילדה,\u0004 משלם לנגזל דמי פרה העומדת ללדת. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הגוזל רחל\u0004 (כבשה) \u0003וגזזה,\u0004 וכן הגוזל \u0003פרה וילדה\u0004 — \u0003משלם אותה ואת גיזותיה ואת ולדותיה,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: גזילה חוזרת בעיניה\u0004 כמות שהיא עכשיו. \u0003ר' שמעון אומר: רואין אותה,\u0004 את הגזילה, \u0003כאילו היא שומא\u0004 (הוערכה) \u0003אצלו בכסף,\u0004 כלומר, העריכו את שוויה בשעת הגזילה, וכך הוא משלם.","ומבררים את הדעות השונות בברייתא זו, \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]:\u0006 \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' מאיר\u0004 שאמר שמשלם אותה ואת גיזותיה ואת ולדותיה? וצדדי השאלה: האם \u0003משום דקסבר\u0004 \u0005[שהוא סבור]\u0006 ש\u0003שינוי במקומו עומד,\u0004 שלמרות שהדבר השתנה הרי זה עדיין ברשות בעליו הראשונים, וכאילו השביחה הבהמה ברשותם. \u0003או דילמא בעלמא\u0004 \u0005[שמא בכלל]\u0006 סבור הוא ש\u0003שינוי קונה,\u0004 ומעיקר הדין הגיזות והוולדות היו צריכים להיות של הגזלן שקנאם בשינוי, \u0003והכא קנסא\u0004 \u0005[קנס]\u0006 \u0003הוא דקא קניס\u0004 \u0005[שקונס],\u0006 שיחזיר הגזלן אף דברים שמן הדין שלו הם?","ומסבירים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה],\u0006 איזה הבדל להלכה יש אם נאמר כטעם זה או כטעם זה? — \u0003להיכא דכחשא מכחש\u0004 \u0005[למקום,\u0006 במקרה, \u0005שכחשה]\u0006 שהוזלה משעת הגזילה, שאם טעמו של ר' מאיר משום שינוי במקומו עומד — מחזיר אותה כמות שהיא, אף שמשיב עתה פחות ממה שגזל, ואם הטעם הוא משום קנס, ומן הדין נקנתה לו הבהמה בשינוי, יצטרך להחזיר כפי שהיתה שווה בזמן הגזילה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במשנה הבאה: \u0003גזל בהמה והזקינה\u0004 אצלו ופחת ערכה, או גזל \u0003עבדים והזקינו\u0004 — \u0003משלם כשעת הגזילה, ר' מאיר אומר: בעבדים\u0004 — \u0003אומר לו \"הרי שלך לפניך\". ו\u0004משמע לדעת ר' מאיר ש\u0003אילו\u0004 בדין \u0003בהמה\u0004 גזולה שהזקינה אינו חולק וסובר שמשלם \u0003כשעת הגזילה\u0004.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 כי \u0003סבר\u0004 \u0005[סבור]\u0006 \u0003ר' מאיר\u0004 ש\u0003שינוי במקומו עומד,\u0004 אם כן \u0003אפילו בהמה נמי\u0004 \u0005[גם כן]\u0006 יחזיר אותה כמות שהיא כעת! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' מאיר\u0004 ש\u0003שינוי קונה, והכא\u0004 \u0005[וכאן]\u0006 כשגזל בהמה וגזזה וילדה \u0003קנסא\u0004 \u0005[קנס]\u0006 \u0003הוא דקא קניס\u0004 \u0005[שקונס]\u0006 שלא ירוויח הגזלן ממה שהשביח.","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיה: מכאן אין להוכיח, שכן אפשר לומר כי \u0003ר' מאיר לדבריהם,\u0004 לשיטתם, \u0003דרבנן קאמר להו\u0004 \u0005[של חכמים אמר להם],\u0006 וכך יש להבין: \u0003לדידי\u0004 \u0005[לי עצמי,\u0006 לשיטתי\u0005]\u0006 \u0003שינוי אין קונה, ואפילו בהמה נמי\u0004 \u0005[גם כן]\u0006 שגזלה והזקינה, צריך להחזיר כמות שהיא עכשיו. \u0003אלא לדידכו דאמריתו\u0004 \u0005[לכם עצמכם,\u0006 לשיטתכם, \u0005שאתם אומרים]\u0006 ש\u0003שינוי קונה, אודו\u0004 \u0005[הודו]\u0006 \u0003לי מיהת בעבדא\u0004 \u0005[על כל פנים בעבד]\u0006 שמחזירו כפי שהוא, \u0003דכמקרקעי דמי\u0004 \u0005[שכקרקע\u0006 הוא \u0005נחשב],\u0006 \u0003וקרקע אינה נגזלת! ואמרי ליה רבנן\u0004 \u0005[ואמרו לו חכמים]\u0006 בתשובה: \u0003לא, עבדא כמטלטלי דמי\u0004 \u0005[העבד נחשב כמיטלטלים]\u0006 לענין גזילה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במשנה: אם נתן צמר לאומן \u0003לצבוע לו\u0004 את הצמר בצבע \u0003אדום וצבעו שחור,\u0004 או לצובעו \u0003שחור וצבעו אדום, ר' מאיר אומר: נותן לו\u0004 האומן שעשה שלא כדעת בעל הבית \u0003דמי צמרו.\u0004 ונדייק: \u0003דמי צמרו\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אבל \u0003דמי צמרו ושבחו,\u0004 השבח, תוספת הערך שבאה על ידי הצביעה — \u0003לא, ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 כי \u0003סבר\u0004 \u0005[סבור]\u0006 \u0003ר' מאיר\u0004 ש\u0003שינוי אין קונה,\u0004 אם כן \u0003דמי צמרו ושבחו,\u0004 כלומר, את צמרו שהושבח \u0003בעי למיתב ליה\u0004 \u0005[צריך להשיב לו]!\u0006","\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' מאיר שינוי קונה, והכא\u0004 \u0005[וכאן]\u0006 בבהמה שנגזזה וילדה \u0003קנסא\u0004 \u0005[קנס]\u0006 \u0003הוא דקא קניס\u0004 \u0005[שקונס]\u0006 את הגזלן שלא יהנה מהגיזות והוולדות. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך היא דעת ר' מאיר.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003לא איבעי לן\u0004 \u0005[נסתפק לנו],\u0006 ומדוע? — \u0003מדאפיך\u0004 \u0005[מ\u0006מה \u0005שהפך]\u0006 \u0003רב ותני\u0004 \u0005[ושנה]\u0006 את המשנה בלשון זו: \u0003גזל פרה והזקינה, עבדים והזקינו\u0004 — \u0003משלם כשעת הגזילה,\u0004 אלו \u0003דברי ר' מאיר, וחכמים אומרים: בעבדים\u0004 — \u0003אומר לו \"הרי שלך לפניך\",\u0004 ואם כן \u0003ודאי ל\u0004דעת \u0003ר' מאיר שינוי קונה\u0004 ולכן משלם כשעת הגזילה, \u0003והכא\u0004 \u0005[וכאן]\u0006 בפרה שילדה ורחל שנגזזה \u0003קנסא\u0004 \u0005[קנס]\u0006 \u0003הוא דקא קניס ליה\u0004 \u0005[שהוא קונסו\u0006 לגזלן\u0005].\u0006","\u0003כי קא איבעי לן\u0004 \u0005[כאשר נשאלה לנו\u0006 השאלה\u0005],\u0006 \u0003הכי איבעי לן\u0004 \u0005[כך נשאלה לנו]:\u0006 \u0003כי קא קניס\u0004 \u0005[כאשר\u0006 ר' מאיר \u0005קונס]\u0006 האם זה דווקא במקום שרכוש חבירו הגיע לידיו \u0003במזיד, אבל\u0004 אם לקח דבר מבעליו \u0003בשוגג, לא קניס\u0004 \u0005[קונס],\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003אפילו בשוגג נמי קניס\u0004 \u0005[גם כן קונס]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בברייתא: לצורך \u0003חמשה\u0004 דברים \u0003גובין\u0004 רק \u0003מן\u0004 הנכסים \u0003המחוררין\u0004 (בני חורין), כלומר, שהם ברשות בעליהם, ולא מנכסים משועבדים שמכרו הבעלים כבר לאחר.","\u0003ואלו הן: פירות,\u0004 מי שצריך לקבל פירות של נכסים שנלקחו ממנו, \u0003ושבח פירות,\u0004 כלומר, השבח שהושבחו הנכסים על ידי עבודתו, \u0003והמקבל עליו\u0004 (מתחייב) בזמן הקידושין \u0003לזון\u0004 את \u0003בן אשתו ובת אשתו\u0004 מנישואיה הראשונים, \u0003וגט\u0004 (שטר) \u0003חוב שאין בו אחריות,\u0004 שלא נכתב בו במפורש שכל נכסי הלווה יהיו אחראים וערבים לפרעון חוב זה, \u0003ו\u0004כן \u0003כתובת אשה שאין בה אחריות.\u0004","ונברר: \u0003מאן\u0004 \u0005[מי]\u0006 \u0003שמעת ליה דאמר\u0004 \u0005[אותו שאומר]\u0006 ש\u0003אחריות לאו טעות סופר הוא?\u0004 שאם לא נכתב תנאי של אחריות בשטר אין זו טעות סופר ששכח ולא כתב אחריות, והרי זה כאילו נכתבה במפורש, אלא שטר שאין כתובה בו אחריות באמת אינו יכול לגבות מנכסים משועבדים — \u0003ר' מאיר\u0004 הוא הסבור כן, \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003פירות ושבח פירות.\u0004","ונברר: \u0003שבח פירות היכי דמי\u0004 \u0005[כיצד הוא בדיוק]?\u0006 — \u0003כגון שגזל\u0004 אדם \u0003שדה מחבירו ומכרה\u0004 אחר כך \u0003לאחר, והשביחה\u0004 הקונה, \u0003והרי היא יוצאה מתחת ידו\u0004 של הקונה, על ידי הנגזל, כאשר הוא מוכיח בבית הדין ששדה זה היה שלו, \u0003כשהוא,\u0004 הקונה, \u0003גובה\u0004 מן הגזלן שמכר לו את השדה שעתה נלקחה ממנו, ורוצה לקבל ממנו בחזרה את מה ששילם לחינם,"],["\u0003גובה את הקרן,\u0004 כלומר, מה ששילם עבור השדה אף \u0003מנכסים משועבדים\u0004 של הגזלן, \u0003ואת השבח,\u0004 מה שעשה והשביח את השדה, הריהו משלם \u0003מנכסים בני חורין.\u0004 ומדוע עושה זאת? — \u0003דאתא\u0004 \u0005[ש\u0006הרי \u0005בא]\u0006 \u0003בעל ארעא\u0004 \u0005[קרקע]\u0006 הראשון \u0003ושקיל ארעיה ושבחיה\u0004 \u0005[ולוקח\u0006 גם את \u0005הקרקע שלו ו\u0006גם את \u0005השבח שלה].\u0006","ונברר: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003ב\u0004קונה שהוא \u0003עם הארץ,\u0004 ש\u0003לא ידע\u0004 \u0005[יודע]\u0006 ש\u0003קרקע נגזלת או אינה נגזלת,\u0004 ואם כן בשוגג עשה כאשר קנה מן הגזלן, שסבור היה שקרקע זו אכן שייכת לגזלן שמכר לו אותה. \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003קאתי\u0004 \u0005[בא]\u0006 \u0003בעל קרקע ושקיל לארעא\u0004 \u0005[ולוקח את הקרקע]\u0006 \u0003ושבחה, ושמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 ש\u0003בשוגג נמי קניס\u0004 \u0005[גם כן קונס]\u0006 ר' מאיר ומחייב להשיב גם את השבח לבעלים. \u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיה: \u0003לא,\u0004 מדובר פה \u0003בלוקח\u0004 (קונה) \u0003תלמיד חכם וידע\u0004 \u0005[ויודע],\u0006 שלגזלן אין זכות קנין כלל בקרקע זו ולכן נקנס הוא להשיב גם את השבח לבעלים.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במשנה: נתן צמר לאומן \u0003לצבוע לו\u0004 את הצמר בצבע \u0003אדום וצבעו שחור,\u0004 או לצובעו \u0003שחור וצבעו אדום\u0004 — \u0003ר' מאיר אומר: נותן לו\u0004 האומן לבעל הצמר את \u0003דמי צמרו.\u0004 ונדייק: \u0003דמי צמרו\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 נותן לו, ואילו \u0003דמי צמרו ושבחו,\u0004 התוספת שהשביח בצביעה — \u0003לא.\u0004","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003בשוגג נמי קניס\u0004 \u0005[גם כן קונס]\u0006 ר' מאיר, אם כן \u0003דמי צמרו ושבחו בעי למיתבא ליה\u0004 \u0005[צריך לתת לו]!\u0006 \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 ש\u0003ב\u0004מקום שעה זאת ב\u0003מזיד קניס\u0004 \u0005[קונס]\u0006 ר' מאיר, ובמקום שעשה זאת \u0003בשוגג לא קניס\u0004 \u0005[קונס],\u0006 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן היא שיטת ר' מאיר.","ועוד באותה ברייתא שנינו, ש\u0003ר' יהודה אומר: גזילה חוזרת בעיניה. ר' שמעון אומר: רואין אותה כאילו היא שומא אצלו בכסף.\u0004 ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 הלכה למעשה? שלכאורה נראה ששניהם מסכימים כי הגזלן אינו צריך לתת לנגזל את השבח ונשאר הוא אצלו.","\u0003אמר רב זביד: בשבח שעל גבי גזילה קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 כלומר, כאשר גופה של הגזילה השביח כגון שנתעברה אצלו, וכיון שהחזיר הגזלן את הבהמה לבעלים הרי החזיר עימה גם את השבח שעליה, ונמצא שלא קיבל הגזלן דבר ממה שהשביחה. ובזאת נחלקו: \u0003ר' יהודה סבר\u0004 \u0005[סבור]\u0006 כי שבח זה של ה\u0003נגזל הוי\u0004 \u0005[הוא],\u0006 שהרווח הזה של הנגזל הוא, שהרי הוא אומר שגזילה חוזרת בעיניה כמות שהיא כעת, גם כאשר השביחה בידי הגזלן. \u0003ור' שמעון סבר\u0004 \u0005[סבור]\u0006 שהרווח הזה של ה\u0003גזלן הוי\u0004 \u0005[הוא].\u0006","\u0003רב פפא אמר\u0004 הבדל אחר בין ר' יהודה ור' שמעון: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 גם \u0003שבח שעל גבי גזילה\u0004 של ה\u0003גזלן הוי\u0004 \u0005[הוא],\u0006 \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003ל\u0004ענין \u0003מחצה, לשליש ולרביע קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 כלומר, לגבי זכות הבעלים לחלק מן הרווח הזה. וכך יש להבין, \u0003ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003שבח שעל גבי גזילה כוליה\u0004 \u0005[כולו]\u0006 של ה\u0003גזלן הוי\u0004 \u0005[הוא],\u0006 \u0003ור' שמעון סבר\u0004 \u0005[סבור]:\u0006 \u0003למחצה, לשליש ולרביע הוא דשקיל\u0004 \u0005[שנוטל]\u0006 ה\u0003גזלן,\u0004 שהוא נחשב כמי שלקח את הבהמה לטפל בה ולהשביחה, ולכן אינו מקבל את כל הרווחים אלא רק את חלקם, כנהוג באותו מקום בתשלומי מלאכה זו. ומנסים להביא ראיה לשיטת רב זביד.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003גזל פרה ונתעברה אצלו וילדה, רחל ונטענה אצלו\u0004 בצמר \u0003וגזזה\u0004 — \u0003משלם כשעת הגזילה.\u0004 ונדייק מכאן: אם \u0003ילדה\u0004 הפרה — \u0003אין\u0004 \u0005[כן]\u0006 משלם כשעת הגזילה, אם \u0003לא ילדה\u0004 ועדיין היא מעוברת — \u0003הדרא בעינא\u0004 \u0005[\u0006היא \u0005חוזרת בעינה]\u0006 כמות שהיא.","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב זביד\u0004 ש\u0003אמר\u0004 ש\u0003שבח שעל גבי גזילה\u0004 שעדיין לא לקחו הגזלן של ה\u0003נגזל הוי\u0004 \u0005[הוא]\u0006 \u0003ל\u0004דעת \u0003ר' יהודה, הא מני\u0004 \u0005[\u0006משנתנו \u0005זו\u0006 של \u0005מי היא]?\u0006 כדעת \u0003ר' יהודה היא, אלא לרב פפא\u0004 ש\u0003אמר\u0004 שהשבח של ה\u0003גזלן הוי\u0004 \u0005[הוא],\u0006 \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]\u0006 הרי היא \u0003לא\u0004 כדעת \u0003ר' יהודה ולא\u0004 כדעת \u0003ר' שמעון!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 לך \u0003רב פפא: הוא הדין אפילו לא ילדה נמי\u0004 \u0005[גם כן]\u0006 \u0003כשעת הגזילה הוא\u0004 ש\u0003משלם,\u0004 והוא מקבל בחזרה את השבח. \u0003והא דקתני\u0004 \u0005[וזה ששנה]\u0006 \u0003\"ילדה\"\u0004 — אי אפשר לדייק מכאן לענייננו כי \u0003איידי דנסיב רישא\u0004 \u0005[מתוך שנקט\u0006 ב\u0005התחלה]\u0006 לשון \u0003\"ילדה\", נסיב סיפא נמי\u0004 \u0005[\u0006תפס ב\u0005סוף גם כן]\u0006 לשון \u0003\"ילדה\".\u0004 אבל אין לדייק מכאן, שאם לא ילדה חוזרת כשהיא מעוברת בלא תשלום.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב פפא, ר' שמעון אומר: רואין אותה כאילו היא שומא אצלו בכסף למחצה, לשליש ולרביע.\u0004","\u0003אמר רב אשי: כי הוינן בי\u0004 \u0005[כאשר היינו\u0006 לומדים ב\u0005בית]\u0006 \u0003רב כהנא, איבעיא לן\u0004 \u0005[נשאלה לנו]\u0006 שאלה זו: \u0003ל\u0004דעת \u0003ר' שמעון\u0004 ש\u0003אמר למחצה, לשליש ולרביע הוא דשקיל\u0004 \u0005[שלוקח]\u0006 \u0003גזלן, כי מסלקינן ליה\u0004 \u0005[כאשר אנו מסלקים אותו\u0006 את הגזלן\u0005]\u0006 ואומרים לו שיקבל חלק בשבח, האם \u0003בדמי מסלקינן ליה\u0004 \u0005[בדמים מסלקים אנו אותו]\u0006 שמשלמים לו את חלקו בכסף, \u0003או דילמא מבשרא שקול\u0004 \u0005[שמא מן הבשר\u0006 עצמו הוא \u0005לוקח]?\u0006","\u0003ופשטנא\u0004 \u0005[ופתרנו]\u0006 את הבעיה הזו \u0003מהא\u0004 \u0005[מזו]\u0006 ש\u0003אמר רב נחמן אמר שמואל: שלשה שמין\u0004 (מעריכים) \u0003להן\u0004 את \u0003השבח\u0004 שהשביחו \u0003ומעלין אותן בדמים,\u0004 שמשלמים את השבח בכסף, ואין משלמים בחלק מן הנכס, \u0003ואלו הן:\u0004 בן \u0003בכור ל\u0004בן \u0003פשוט\u0004 (אח שאינו בכור), שאם עבדו שניהם בנחלה משותפת שירשו מאביהם, ואחר כך חילקו ביניהם, צריך הבכור (המקבל פי שנים) להחזיר לפשוט את חלקו ברווח שהשביח חלק הנכס שירש הבכור יתר על אחיו, ודבר זה נעשה בדמים, ולא בחלק מן הקרקע.","\u0003ו\u0004כן \u0003בעל חוב ללוקח,\u0004 בעל חוב הגובה בחובו מקרקע משועבדת לו, שמכר הלווה לאדם אחר, הריהו מפצה את הקונה על מה שהשביח את הקרקע בכסף ולא מגוף הקרקע. \u0003ובעל חוב ליתומים\u0004 כשגובה מנכסי אביהם עבור חוב של אביהם, ומוטל עליו לשלם להם במה שהשביחו את הקרקע לאחר מות אביהם — אף דבר זה נעשה בכסף, ולא מן הקרקע עצמה.","אגב שהובאו דברי שמואל דנים בהם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי, מי\u0004 \u0005[האם]\u0006 \u0003אמר שמואל:\u0004 ש\u0003בעל חוב ללוקח יהיב ליה\u0004 \u0005[נותן לו]\u0006 \u0003שבח\u0004 כלשהו? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: בעל חוב\u0004 הוא \u0003גובה את השבח\u0004 כולו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן\u0004 שאינו גובה את השבח, הרי זה \u0003בשבח המגיע לכתפים,\u0004 כלומר, שהשביח הלוקח עד שנשלם גידולו, שהוא כבר בשל ואפשר לבוא ולקחת אותו על הכתפיים, \u0003וכאן\u0004 שגובה, הרי זה \u0003בשבח שאין מגיע לכתפים,\u0004 שעדיין לא נשלם גידולו והוא עובר לגמרי לרשות בעל החוב.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא: \u0003והא\u0004 \u0005[והרי]\u0006 היו \u0003מעשים בכל יום, וקא מגבי\u0004 \u0005[והיה מגבה]\u0006 \u0003שמואל\u0004 מן הלוקח \u0003אפילו שבח המגיע לכתפים! אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006"],["\u0003הא דמסיק ביה כשיעור ארעא ושבחא\u0004 \u0005[זה ש\u0006הוא היה \u0005נושה בו כשיעור הקרקע והשבח\u0006 יחד\u0005]\u0006 גובה את השבח, \u0003הא דלא מסיק ביה\u0004 \u0005[זה שאינו נושה בו]\u0006 \u0003אלא כשיעור ארעא\u0004 \u0005[הקרקע\u0006 עצמה\u0005]\u0006 ואז מחזיר לו את השבח.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]:\u0006 \u0003אי אית ליה זוזי\u0004 \u0005[אם יש לו כסף]\u0006 \u0003ללוקח, לא מצי מסלק ליה\u0004 \u0005[אינו יכול לסלק אותו]\u0006 את \u0003בעל\u0004 ה\u0003חוב\u0004 בכסף, אלא לבעל החוב יש זכות על הקרקע עצמה, לפי שיטה זו \u0003שפיר\u0004 \u0005[יפה].\u0006 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003אי אית ליה זוזי\u0004 \u0005[אם יש לו כסף]\u0006 \u0003ללוקח מצי מסלק ליה\u0004 \u0005[יכול\u0006 הוא \u0005לסלק אותו]\u0006 את \u0003בעל\u0004 ה\u0003חוב\u0004 ולשלם לו כסף, \u0003לימא ליה\u0004 \u0005[שיאמר לו\u0006 כך\u0005]:\u0006 \u0003אי הוו\u0004 \u0005[אם היו]\u0006 \u0003לי זוזי\u0004 \u0005[זוזים,\u0006 כסף\u0005]\u0006 \u0003הוה מסלקינא לך מכוליה ארעא\u0004 \u0005[הייתי מסלק אותך מכל הקרקע\u0006 הזאת\u0005],\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 שאין לי כסף לשלם לך את כל חובך \u0003הב\u0004 (תן) \u0003לי\u0004 לפחות \u0003גריוא דארעא\u0004 \u0005[חלקת אדמה]\u0006 כ\u0003שיעור שבחאי\u0004 \u0005[השבח שלי]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — \u0003כגון דשויה ניהליה\u0004 \u0005[שעשה לו\u0006 הלווה\u0005]\u0006 את השדה הזו \u0003אפותיקי,\u0004 כלומר, ש\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא יהא לך פרעון אלא מזה,\u0004 ובמקרה כזה יש שיעבוד ברור על גוף השדה הזה, ולא על דבר אחר.","ובענין זה של שבח שהשביחה גזילה \u0003אמר רבא:\u0004 מי ש\u0003גזל\u0004 דבר \u0003והשביח\u0004 את הגזילה \u0003ומכר\u0004 לאחר, \u0003ו\u0004כן \u0003גזל והשביח\u0004 ומת \u0003והוריש\u0004 — \u0003מה שהשביח מכר, מה שהשביח הוריש,\u0004 והנגזל (אם נוטל את הגזילה בחזרה) צריך לשלם לקונה וליורש עבור השבח.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא\u0004 בעקבות הלכה זו: אם \u0003השביח לוקח, מהו\u0004 הדין, האם הוא צריך להחזיר את השבח או לא? \u0003בתר דבעיא הדר פשטה\u0004 \u0005[אחרי ששאל\u0006 את השאלה \u0005חזר\u0006 ו\u0005פתר אותה]:\u0006 \u0003מה מכר ראשון לשני\u0004 בכל מכירה? — \u0003כל זכות שתבא לידו,\u0004 וכיון שיש לגזלן זכות בשבח שהשביח בגזילה — מכר גם את הזכות הזו לקונה.","ועוד בענין זה, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 אם \u0003השביח גוי\u0004 חפץ שגזל, \u0003מהו,\u0004 האם הוא זוכה בשבח? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: תקנתא\u0004 \u0005[תקנה]\u0006 \u0003לגוי ניקו ונעבוד\u0004 \u0005[נעמוד ונעשה],\u0006 שלא עשו חכמים תקנות למען הגויים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 שאלה זו אלא \u0003כגון דזבניה\u0004 \u0005[שמכר אותה]\u0006 הגוי \u0003לישראל.\u0004 ואומרים: \u0003סוף סוף הבא מחמת גוי,\u0004 כלומר, שכוחו (רשותו, זכותו) בחפץ זה בא מחמת הגוי, \u0003הרי הוא כגוי\u0004 עצמו וכפי שאמרנו שהראשון מוכר לשני את כל הזכויות שיש לו בחפץ.","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003כגון\u0004 ש\u0003גזל ישראל וזבנה ניהליה\u0004 \u0005[ומכרה,\u0006 את הגזילה, \u0005לו,\u0006 לגוי\u0005]\u0006 \u0003והשביחה\u0004 ה\u0003גוי, והדר\u0004 \u0005[וחזר]\u0006 ה\u0003גוי וזבנה\u0004 \u0005[ומכרה]\u0006 \u0003לישראל,\u0004 והשאלה היא: \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין אז? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003כיון דמעיקרא\u0004 \u0005[שמתחילה]\u0006 גזלה \u0003ישראל והדר\u0004 \u0005[ו\u0006אחר כך \u0005שוב]\u0006 הגיעה ליד \u0003ישראל\u0004 — \u0003עבדי רבנן תקנתא\u0004 \u0005[עשו חכמים תקנה],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003גוי באמצע\u0004 — \u0003לא עבדו ליה רבנן תקנתא\u0004 \u0005[עשו לו חכמים תקנה]?\u0006 שאלה זו לא נפתרה ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנתנו כי הגוזל עצים ועשה מהם כלים — נקנו לו העצים בשינוי. ומעתה דנים במקרים שונים האם נחשבים הם כשינוי. \u0003אמר רב פפא: האי מאן\u0004 \u0005[מי]\u0006 ש\u0003גזל דיקלא מחבריה וקטליה\u0004 \u0005[דקל מחבירו וקצץ אותו],\u0006 \u0003אף על גב דשדיא מארעא לארעא דידיה\u0004 \u0005[אף על פי שזרק\u0006 את הדקל \u0005מן הקרקע\u0006 של הנגזל \u0005אל הקרקע שלו\u0006 עצמו\u0005]\u0006 — \u0003לא קני\u0004 \u0005[קנה].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003מעיקרא דיקלא מיקרי והשתא נמי דיקלא מיקרי\u0004 \u0005[מתחילה דקל\u0006 הוא \u0005נקרא וגם עכשיו\u0006 שנקצץ \u0005דקל\u0006 הוא \u0005נקרא],\u0006 שאין כאן שינוי שעל ידיו יקנה. ויותר מכך, אף אם גזל \u0003דיקלא\u0004 \u0005[דקל]\u0006 \u0003ועביד גובי\u0004 \u0005[ועשה\u0006 ממנו \u0005חתיכות]\u0006 — \u0003לא קני\u0004 \u0005[קנה],\u0006 כי \u0003השתא מיהת גובי דדיקלא מיקרי\u0004 \u0005[עכשיו על כל פנים חתיכות דקל\u0006 הן \u0005נקראות].\u0006","אבל אם גזל \u0003גובי\u0004 \u0005[חתיכות]\u0006 \u0003ועבדינהו כשורי\u0004 \u0005[ועשה מהן קורות]\u0006 — \u0003קני\u0004 \u0005[קנה],\u0006 משום שיש דבכך שינוי. וכיוצא בזה \u0003כשורי רברבי ועבדינהו כשורי זוטרי\u0004 \u0005[\u0006גזל \u0005קורות גדולות ועשה אותן קורות קטנות]\u0006 — \u0003לא קני\u0004 \u0005[קנה],\u0006 שעדיין קורות הן נקראות. \u0003עבדינהו קצוצייתא\u0004 \u0005[עשה מהן קרשים]\u0006 — \u0003קני\u0004 \u0005[קנה].\u0006","\u0003אמר רבא: האי מאן\u0004 \u0005[מי]\u0006 ש\u0003גזל לוליבא\u0004 \u0005[לולב]\u0006 \u0003ועבדינהו הוצי\u0004 \u0005[ועשה ממנו עלים],\u0006 שפירק את כל העלים מן השידרה — \u0003קני\u0004 \u0005[קנה]\u0006 את זה, \u0003דמעיקרא לוליבא מיקרי\u0004 \u0005[שמתחילה לולב\u0006 הוא \u0005נקרא]\u0006 \u0003והשתא הוצי\u0004 \u0005[ועכשיו\u0006 הוא נקרא \u0005עלים].\u0006 וכן \u0003הוצי ועבדינהו חופיא\u0004 \u0005[\u0006אם גזל \u0005עלים\u0006 של לולב \u0005ועשה מהם רצועות של מטאטא]\u0006 — \u0003קני\u0004 \u0005[קנה],\u0006 ומדוע? \u0003מעיקרא הוצי והשתא חופיא\u0004 \u0005[מתחילה\u0006 קראו לזה \u0005עלים ועכשיו\u0006 קוראים לזה \u0005רצועות מטאטא].\u0006 אם גזל \u0003חופיא\u0004 \u0005[מטאטא]\u0006 \u0003ועבדיה שרשורא\u0004 \u0005[ועשה ממנו\u0006 כעין \u0005שרשרת,\u0006 חבל\u0005]\u0006 — \u0003לא קני\u0004 \u0005[קנה],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003דהדר סתר ליה והוי חופיא\u0004 \u0005[שהוא חוזר וסותר אותו והוא\u0006 שוב \u0005מטאטא].\u0006","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 אם \u0003נחלקה התיומת\u0004 (העלה האמצעי של הלולב), \u0003מהו\u0004 דינו לענין שינוי שעושה קנין? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ש\u0003אמר ר' מתון אמר ר' יהושע בן לוי:\u0004 אם \u0003ניטלה התיומת\u0004 — \u0003פסול\u0004 הלולב למצוותו."],["\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003הוא הדין לנחלקה\u0004 התיומת. שעל ידי כך נפסל הלולב, והעושה כן קונה אותו בשינוי? ודוחים: \u0003לא, ניטלה שאני\u0004 \u0005[שונה],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003חסר לה\u0004 משהו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך נפתרה השאלה, שאומרים, \u0003תא שמע\u0004 \u0005[בוא,\u0006 ו\u0005שמע]\u0006 ש\u0003אמר ר' מתון אמר ר' יהושע בן לוי: נחלקה התיומת\u0004 — \u0003נעשה כמי שנטלה\u0004 לגמרי \u0003ופסול,\u0004 אם כן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שחלוקת התיומת היא פסול ושינוי גמור, וקונה.","\u0003אמר רב פפא: האי מאן\u0004 \u0005[מי]\u0006 ש\u0003גזל עפרא מחבריה ועבדיה לבינתא\u0004 \u0005[עפר מחבירו ועשה אותו לבינה]\u0006 — \u0003לא קני\u0004 \u0005[קנה]\u0006 בשינוי, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003דהדר משוי ליה עפרא\u0004 \u0005[ש\u0006יכול \u0005לחזור ולעשות אותו עפר].\u0006 אבל אם גנב ממנו \u0003לבינתא ועבדיה עפרא\u0004 \u0005[לבינה ועשה אותה עפר]\u0006 — \u0003קני\u0004 \u0005[קנה]\u0006 בשינוי, שכן \u0003מאי אמרת? דלמא הדר ועביד ליה לבינתא\u0004 \u0005[מה אתה אומר, שמא\u0006 הוא \u0005חוזר ועושה אותה לבינה]?\u0006 \u0003האי לבינתא אחריתי הוא\u0004 \u0005[זו\u0006 שיעשה \u0005לבינה אחרת היא],\u0006 \u0003ופנים חדשות באו לכאן.\u0004 שאף שהיא נראית כלבינה הראשונה, מכל מקום לבינה אחרת חדשה היא.","\u0003ו\u0004עוד \u0003אמר רב פפא: האי מאן\u0004 \u0005[מי]\u0006 ש\u0003גזל נסכא מחבריה ועביד זוזי\u0004 \u0005[מטיל\u0006 כסף \u0005מחבירו ועשה\u0006 ממנו \u0005מטבעות]\u0006 — \u0003לא קני\u0004 \u0005[קנה]\u0006 בשינוי, \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 — \u0003הדר עביד להו נסכא\u0004 \u0005[\u0006יכול הוא \u0005לחזור\u0006 ו\u0005לעשות מהם מטיל\u0006 כסף\u0005].\u0006 אבל אם היו \u0003זוזי ועבדינהו נסכא\u0004 \u0005[\u0006\u0005מטבעות ועשה אותם\u0006 \u0005מטיל\u0006 כסף\u0005]\u0006 — \u0003קני\u0004 \u0005[קנה],\u0006 שכן \u0003מאי אמרת\u0004 \u0005[מה אתה אומר]?\u0006 — \u0003הדר עביד להו זוזי\u0004 \u0005[\u0006שהוא \u0005חוזר ועושה אותם מטבעות]?\u0006 מטבעות אלה הם חדשים ו\u0003פנים חדשות באו לכאן.\u0004","אם היו המטבעות שגזל \u0003שחימי ועבדינהו חדתי\u0004 \u0005[שחורים,\u0006 משומשים וישנים, \u0005ועשה אותם חדשים]\u0006 על ידי זה שניקה וצחצח אותם — \u0003לא קני\u0004 \u0005[קנה],\u0006 אבל אם היו \u0003חדתי ועבדינהו שחימי\u0004 \u0005[חדשים ועשה אותם שחורים]\u0006 — \u0003קני\u0004 \u0005[קנה],\u0006 \u0003מאי אמרת\u0004 \u0005[מה אתה אומר]?\u0006 — \u0003הדר עביד להו חדתי\u0004 \u0005[\u0006שהוא \u0005חוזר ועושה אותם חדשים],\u0006 שמצחצח אותם? \u0003מידע ידיע שיחמייהו\u0004 \u0005[ידועה השחרות שלהם]\u0006 ולכן השינוי שעשה בהם היה שינוי שאינו חוזר.","שנינו במשנה, \u0003זה הכלל: כל הגזלנין משלמין כשעת הגזלה.\u0004 ושואלים: \u0003\"זה הכלל\" לאתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף, את \u0005מה]?\u0006 ומשיבים: \u0003לאתויי הא\u0004 \u0005[להביא\u0006 את \u0005זו]\u0006 ש\u0003אמר ר' אלעא:\u0004 אם אדם \u0003גנב טלה ונעשה\u0004 במשך הזמן שהיה אצלו \u0003איל,\u0004 גנב \u0003עגל ונעשה שור\u0004 — \u0003נעשה שינוי בידו, וקנאו\u0004 על ידי כך, ולכן אם \u0003טבח ומכר\u0004 לאחר השינוי שנעשה אז — \u0003שלו,\u0004 של הגזלן, \u0003הוא טובח, שלו הוא מוכר\u0004 ואינו משלם קנס ארבעה וחמישה.","מסופר: \u0003ההוא גברא\u0004 \u0005[אדם אחד]\u0006 ש\u0003גזל פדנא דתורי מחבריה\u0004 \u0005[צמד שוורים מחבירו],\u0006 \u0003אזל כרב בהו כרבא, זרע בהו זרעא\u0004 \u0005[הלך חרש בהם חרישה\u0006 ו\u0005זרע בהם זרע],\u0006 \u0003לסוף אהדרינהו למריה\u0004 \u0005[ובסוף החזירם לבעליהם].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הנגזל \u0005לפני]\u0006 \u0003רב נחמן\u0004 לתבוע אותו, \u0003אמר להו\u0004 \u0005[להם]\u0006 רב נחמן: \u0003זילו שומו שבחא דאשבח\u0004 \u0005[לכו\u0006 ו\u0005העריכו\u0006 את \u0005השבח שהשביח]\u0006 את הקרקע במשך הזמן שהשתמש בשוורים שגזל, ואותו יצטרך הגזלן לשלם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: תורי אשבח, ארעא\u0004 \u0005[\u0006וכי \u0005השוורים\u0006 לבדם \u0005השביחו\u0006 וה\u0005אדמה]\u0006 עצמה \u0003לא אשבח\u0004 \u0005[השביחה]?\u0006 \u0003אמר\u0004 רב נחמן: \u0003מי קאמינא נשיימו כוליה\u0004 \u0005[האם אמרתי שישומו\u0006 ויתנו לו \u0005את כל\u0006 השבח\u0005]?\u0006 הלא \u0003פלגא קאמינא\u0004 \u0005[חצי אמרתי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003סוף סוף\u0004 הרי \u0003גזילה הוא, וקא הדרה בעינא\u0004 \u0005[והיא חוזרת בעינה],\u0006 כלומר, כפי שקיבל אותה, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הגזלנין משלמין כשעת הגזלה!\u0004 ומדוע צריך להוסיף ולשלם מחצית השבח לנגזל?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: האם \u0003לא אמינא\u0004 \u0005[אמרתי]\u0006 \u0003לך כי יתיבנא בדינא\u0004 \u0005[\u0006ש\u0005כאשר אני יושב בדין]\u0006 \u0003לא תימא\u0004 \u0005[תאמר]\u0006 \u0003לי מידי\u0004 \u0005[דבר]\u0006 לשאול ולהעיר על הפסקים שלי, ש\u0003אמר הונא חברין עלאי\u0004 \u0005[חברנו עלי]:\u0006 \u0003אנא ושבור מלכא אחי בדינא\u0004 \u0005[אני ושבור המלך,\u0006 החכם שמואל, \u0005אחים בדין],\u0006 כלומר, שבענייני דינים חשוב אני כשמואל עצמו. ואף כאן היה לי טעם בדבר, והוא: \u0003האי אינש גזלנא עתיקא\u0004 \u0005[אדם זה גזלן עתיק,\u0006 ותיק\u0005]\u0006 \u0003הוא,\u0004 שהיה רגיל בגזילה \u0003ובעינא דאיקנסיה\u0004 \u0005[ורציתי לקנוס אותו],\u0006 ולכן אמרתי שישלם גם את השבח, אבל לא מפני שכך הדין.","\u0003גזל בהמה ו\u0004בהיותה אצלו \u0003הזקינה\u0004 והרי עתה בהמה זו שווה פחות, וכן גזל \u0003עבדים ו\u0004בהיותם אצלו \u0003הזקינו\u0004 — הרי זה שינוי וקנאם הגזלן, ולכן \u0003משלם\u0004 כפי שהיו שווים ב\u0003שעת הגזלה, ר' מאיר אומר: בעבדים\u0004 — \u0003אומר לו\u0004 הגזלן לנגזל \u0003\"הרי שלך לפניך\".\u0004","\u0003גזל מטבע ונסדק\u0004 ואבד בכך ערכו, או שגזל \u0003פירות והרקיבו,\u0004 או \u0003יין והחמיץ\u0004 — בכל אלה הריהו \u0003משלם כשעת הגזלה.\u0004","אבל אם גזל \u0003מטבע ונפסל\u0004 על ידי המלכות, או שגזל \u0003תרומה ונטמאת\u0004 במשך הזמן, או \u0003חמץ ועבר עליו הפסח\u0004 ונאסר בהנאה, \u0003בהמה ונתעבדה בה עבירה\u0004 שפוסלת אותה מקרבן, \u0003או שנפסלה מ\u0004לעלות \u0003על גבי המזבח\u0004 בגלל סיבה אחרת, \u0003או שהיתה יוצאה\u0004 (שנגזר דינה) \u0003ליסקל\u0004 משום שנגחה והרגה אדם בתוך הזמן שלאחר הגזילה — \u0003אומר לו \"הרי שלך לפניך\",\u0004 שכיון שאין זה שינוי הניכר לעין, אף על פי שבכל אלה המקרים פחת או בטל הערך של הדבר שגזל — מחזיר אותו בעינו.","על הנאמר במשנה שאם גזל בהמה והזקינה משלם כשעת הגזילה, משום שקנה אותה בכך, \u0003אמר רב פפא: לא הזקינה\u0004 — \u0003הזקינה ממש, אלא אפילו כחשה\u0004 (רזתה, נחלשה) ולא נשתנתה כל כך הרי זה נחשב שינוי וקנאה בכך. ומקשים: \u0003והא אנן\u0004 \u0005[והרי אנו]\u0006 \u0003\"הזקינה\" תנן\u0004 \u0005[שנינו]!\u0006 ומשיבים: הכוונה היתה \u0003כחשה כגון הזקינה,\u0004 ברזון כזה ש\u0003לא הדר בריא\u0004 \u0005[חוזר\u0006 ו\u0005משמין].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר קשישא\u0004 \u0005[הזקן]\u0006 \u0003בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חסדא לרב אשי, הכי קאמרי משמיה\u0004 \u0005[כך אומרים משמו]\u0006 של \u0003ר' יוחנן: אפילו גנב טלה ונעשה איל,\u0004 או \u0003עגל ונעשה שור\u0004 — \u0003נעשה שינוי בידו\u0004 על ידי שינוי השם \u0003וקנאו,\u0004 ולכן אם \u0003טבח ומכר\u0004 אותו — \u0003שלו הוא טובח, שלו הוא מוכר\u0004 ופטור מארבעה וחמישה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: וכי \u0003לאו אמינא\u0004 \u0005[לא אמרתי]\u0006 \u0003לך:\u0004 \u0003לא תחליף גברי\u0004 \u0005[אנשים]\u0006 שאתה מוסר דבר תורה משמם? \u0003ההוא משמיה\u0004 \u0005[אותה\u0006 שמועה \u0005משמו]\u0006 של \u0003ר' אלעא איתמר\u0004 \u0005[נאמרה],\u0006 ולא משמו של ר' יוחנן.","שנינו במשנה ש\u0003ר' מאיר אומר: בעבדים\u0004 — \u0003אומר לו \"הרי שלך לפניך\". אמר רב חנינא בר אבדימי אמר רב: הלכה כ\u0004שיטת \u0003ר' מאיר.\u0004 ותוהים: \u0003ו\u0004כי \u0003רב שביק רבנן ועביד\u0004 \u0005[מניח\u0006 את דברי \u0005חכמים\u0006 שהם רבים \u0005ועושה]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר? אמרי\u0004 \u0005[אומרים]:\u0006 \u0003משום\u0004 ש\u0003ברייתא איפכא תניא\u0004 \u0005[שנויה להיפך]\u0006 בהיפוך השיטות, ושיטה זו שבעבדים אומר לו \"הרי שלך לפניך\" היא שיטת חכמים ולא שיטת ר' מאיר. ותוהים: \u0003ו\u0004כי \u0003רב שביק מתניתין ועביד כברייתא\u0004 \u0005[מניח\u0006 את \u0005משנתנו ועושה כמו הברייתא]\u0006 וסומך עליה? ומשיבים: \u0003רב, מתניתין נמי איפכא תני\u0004 \u0005[\u0006את \u0005משנתנו גם כן להיפך שונה],\u0006 כלומר, מה שאנו מייחסים במשנה לר' מאיר הופך רב ושונה אותו בשם חכמים.","ושואלים: \u0003ומאי טעמיה\u0004 \u0005[ומה טעמו]\u0006 של \u0003רב דאפיך מתניתין מקמי\u0004 \u0005[שהפך\u0006 את שיטת \u0005משנתנו מפני]\u0006 ה\u0003ברייתא? אדרבה, ניפוך\u0004 \u0005[להיפך, שיהפוך]\u0006 את ה\u0003ברייתא מקמי מתניתין\u0004 \u0005[מפני משנתנו]!\u0006 \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003רב נמי מתניתין איפכא אתניה\u0004 \u0005[גם כן\u0006 את \u0005משנתנו\u0006 בצורה זו \u0005ההפוכה שנה],\u0006 ולא הוא הפך את השיטות במשנה, אלא כך עמדה לפניו המשנה, כלשון הברייתא.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר: אמנם רב הוא שהפך את השיטות במשנתנו, וכלל הוא זה: \u0003כי לא אפיך חדא מקמי חדא, חדא מקמי תרתי אפיך\u0004 \u0005[כאשר אינו הופך\u0006 משנה מפני ברייתא, הרי זה משנה \u0005אחת מפני\u0006 ברייתא \u0005אחת,\u0006 אבל משנה \u0005אחת מפני שתי\u0006 ברייתות הריהו \u0005הופך].\u0006","ואף כאן, יש ברייתא נוספת ששיטתה הפוכה משיטת משנתנו, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא אחרת\u0005]:\u0006 \u0003המחליף פרה בחמור ו\u0004בינתים \u0003ילדה\u0004 הפרה, \u0003וכן המוכר שפחתו וילדה\u0004 ומתדיינים המוכר והקונה מתי ילדה, \u0003זה אומר \"\u0004בזמן שהיתה \u0003ברשותי ילדה\"\u0004 ולכן הוולד שייך לי, \u0003והלה,\u0004 האחר, \u0003שותק\u0004 — \u0003זכה בה\u0004 זה שאומר בוודאות שברשותו ילדה. אם \u0003זה אומר \"איני יודע\" וזה אומר \"איני יודע\"\u0004 — \u0003יחלוקו.\u0004","אם \u0003זה אומר \"ברשותי\" וזה אומר \"ברשותי\"\u0004 — \u0003ישבע המוכר שברשותו ילדה\u0004 ויישאר הוולד אצלו, ומדוע? \u0003לפי שכל הנשבעין שבתורה נשבעין ולא משלמין,\u0004 אלו \u0003דברי ר' מאיר.\u0004 וכאן מכיון שהיתה למוכר חזקה ראשונה על הבהמה או על השפחה, דיו שישבע מפני שהוא נחשב דלנתבע, והוא צריך להישבע כדי להיפטר.","\u0003וחכמים אומרים: אין נשבעין לא על העבדים ולא על הקרקעות.\u0004 ואם כן רואים שלדעת חכמים דין העבדים כקרקעות, ואילו שיטת ר' מאיר אינה כן, ולכן גם במשנתנו השיטה שבעבדים אומר לו \"הרי שלך לפניך\" שיטת חכמים היא החלוקים על ר' מאיר.","ושואלים: אם אתה אומר שרב שנה את דברי חכמים בשם ר' מאיר, אם כן, \u0003האי\u0004 \u0005[זה]\u0006 הביטוי \u0003\"הלכה כר' מאיר\"\u0004 אינו נכון, אלא \u0003\"הלכה כרבנן\"\u0004 \u0005[כחכמים]\u0006 \u0003מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]?!\u0006 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003למאי דאפכיתו ותניתו\u0004 \u0005[\u0006לפי \u0005מה שאתם הופכים ושונים]\u0006 שר' מאיר אומר שאומר לו \"הרי שלך לפניך\", לפי זה צריכים אתם לפסוק \u0003הלכה כר' מאיר,\u0004 אף על פי שלשיטתי היא דעת חכמים ולא דעת ר' מאיר."],["ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב\u0004 כי \u0003עבדא כמקרקעי דמי\u0004 \u0005[עבד נחשב כקרקעות]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב דניאל בר רב קטינא אמר רב: התוקף\u0004 (תופס) \u0003בעבדו של חבירו ועשה בו,\u0004 בעבד, \u0003מלאכה\u0004 — \u0003פטור\u0004 מלשלם לחבירו את שכר עבודתו של עבדו. \u0003ואי סלקא דעתך עבדא כמקרקעי דמי\u0004 \u0005[ואם עולה על דעתך\u0006 לומר בשיטת רב ש\u0005עבד נחשב כקרקעות],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003פטור\u0004 מלשלם? הלא העבד, בדומה לקרקע, \u0003ברשותא דמריה קאי\u0004 \u0005[ברשות בעליו\u0006 הוא \u0005עומד]\u0006 תמיד, בכל מקום שהוא נמצא, ונמצא שעשה מלאכה בדבר שאינו שלו וצריך לשלם!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 שהכריח התוקף את העבד לעבוד למענו \u0003שלא בשעת מלאכה\u0004 רגילה, ולא ביטל אותו ממלאכתו. וכיון שלא חיסר מאומה מן הבעלים, אינו צריך לשלם עבור מה שנהנה. \u0003כי הא\u0004 \u0005[כמו\u0006 ענין \u0005זה]\u0006 ש\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא למרי בר מר, בעי מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003מרב הונא\u0004 שאלה זו: \u0003הדר בחצר חבירו שלא מדעתו\u0004 (מידיעתו ורצונו) של חבירו, שלא נתן לו את החצר מרצונו, האם \u0003צריך להעלות לו שכר\u0004 על כך \u0003או אין צריך להעלות לו שכר? ושלחו ליה\u0004 \u0005[לו]\u0006 בתשובה: \u0003אינו צריך להעלות לו שכר.\u0004 והסבר הדבר משום שלא הפסידו.","את ההשוואה הזו דוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]\u0006 שני עניינים אלו זה לזה? \u0003בשלמא התם\u0004 \u0005[נניח שם]\u0006 בענין הדר בחצר חבירו, \u0003בין למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 בהסבר הפטור שהוא משום \u0003ביתא מיתבא יתיב\u0004 \u0005[\u0006ש\u0005הבית הנושב\u0006 בבני אדם הוא \u0005מיושב]\u0006 ולכן \u0003ניחא ליה\u0004 \u0005[נוח לו]\u0006 לבעלים שיש מישהו שיושב בבית, \u0003בין למאן דאמר\u0004 \u0005[למי שאומר]\u0006 שטעם הדבר משום \u0003\"ושאיה יכת שער\"\u0004 (ישעיה כד, יג), שבית שומם נחרב, ולכן הדר בחצירו שומר לו על ביתו, גם כן \u0003ניחא ליה\u0004 \u0005[נוח לו]\u0006 לבעלים הדבר, ולכן פטור הדייר מלשלם לו שכר,","\u0003אלא הכא מי ניחא ליה דנכחוש עבדיה\u0004 \u0005[כאן האם נוח לו שיכחיש,\u0006 יפסיד, זה שהשתמש בעבד את \u0005עבדו]\u0006 על ידי מלאכה? \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003הכי נמי ניחא ליה\u0004 \u0005[כאן גם כן נוח לו]\u0006 הדבר כדי ש\u0003לא ליסתרי עבדיה\u0004 \u0005[יתרגל עבדו להתבטל].\u0006","ובענין זה מסופר: \u0003בי\u0004 \u0005[\u0006אנשי \u0005ביתו]\u0006 של \u0003רב יוסף בר חמא\u0004 על פי הוראתו \u0003הוו תקיף\u0004 \u0005[היו תופסים]\u0006 \u0003עבדי דאינשי\u0004 \u0005[אנשים]\u0006 \u0003דמסיק בהו זוזי ועבדי בהו\u0004 \u0005[ש\u0006הוא \u0005היה נושה בהם כסף, ועושים בהם]\u0006 \u0003מלאכה\u0004 בעל כרחם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 לרב יוסף בר חמא \u0003רבה בריה\u0004 \u0005[בנו]:\u0006 \u0003מאי טעמא עביד מר הכי\u0004 \u0005[מה טעם עושה אדוני כך]\u0006 ומשתמש בעבדים אלה? \u0003אמר ליה\u0004 \u0005[לו],\u0006 ש\u0003אמר רב נחמן: עבדא\u0004 \u0005[העבד]\u0006 — אפילו את \u0003נהום כריסיה לא שוי\u0004 \u0005[הלחם של כריסו אינו שווה],\u0006 ואינו מחסר את הבעלים דבר כשהעבד עובד ואוכל אצלו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 בנו: \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003אמר רב נחמן\u0004 דבר זה על עבד מסויים, \u0003כגון דארו עבדיה דמרקיד בי כובי\u0004 \u0005[עבדו שהיה מרקד בין החנויות]\u0006 ולא היה עושה דבר, אבל \u0003כולהו עבדי מעבד עבדי\u0004 \u0005[כל העבדים עובדים\u0006 הם\u0005]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003כ\u0004שיטת \u0003רב דניאל סבירא לי\u0004 \u0005[סבור אני],\u0006 ש\u0003אמר רב דניאל בר רב קטינא אמר רב: התוקף בעבדו של חבירו ועשה בו מלאכה\u0004 — \u0003פטור, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003ניחא ליה\u0004 \u0005[שנוח לו]\u0006 לאדם ש\u0003לא ליסתרי עבדיה\u0004 \u0005[יתרגל עבדו להתבטל],\u0006 ואם כן אין הבעלים מפסיד בכך כשאינו משתמש בעבדיו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 בנו: \u0003הני מילי היכא דלא מסיק בהו זוזי\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005במקום שאינו נושה\u0006 התופס ומשתמש \u0005בהם\u0006 בבעלים של העבד \u0005כסף],\u0006 \u0003מר\u0004 \u0005[אדוני]\u0006 \u0003כיון דמסיק בהו זוזי מחזי\u0004 \u0005[שנושה בהם כסף נראה]\u0006 הדבר \u0003כרבית.\u0004 ש\u0003אמר רב יוסף בר מניומי אמר רב נחמן: אף על פי שאמרו הדר בחצר חבירו שלא מדעתו אין צריך להעלות לו שכר,\u0004 אבל אם \u0003הלוהו\u0004 לחבירו \u0003ודר בחצר חבירו\u0004 הלווה — \u0003צריך להעלות לו שכר,\u0004 כדי שלא ייראה הדבר כריבית! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף בר חמא לבנו: \u0003הדרי\u0004 \u0005[חוזר אני]\u0006 \u0003בי\u0004 ממעשים אלה ולא אעשה כך יותר.","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003התוקף\u0004 (תופס) \u0003ספינתו של חבירו ועשה בה מלאכה,\u0004 מה יכול בעל הספינה לתבוע? \u0003אמר רב:\u0004 הברירה בידו, אם \u0003רצה\u0004 — \u0003שכרה נוטל,\u0004 אם \u0003רצה\u0004 — \u0003פחתה\u0004 (הפחת שפחתה מחמת מלאכה זו) \u0003נוטל,\u0004 שיכול לתבוע את הסכום הגדול יותר. \u0003ושמואל אמר: אינו נוטל אלא פחתה.\u0004","\u0003אמר רב פפא: לא פליגי\u0004 \u0005[אין\u0006 הם \u0005חלוקים]\u0006 אלא כל אחד מהם דיבר במקרה אחר. \u0003הא\u0004 \u0005[זה,\u0006 רב\u0005]\u0006 דיבר בספינה \u0003דעבידא לאגרא\u0004 \u0005[שעשויה,\u0006 שעומדת, \u0005להשכרה\u0006 לעבודה\u0005],\u0006 \u0003הא\u0004 \u0005[זה,\u0006 שמואל\u0005]\u0006 דיבר בספינה ש\u0003לא עבידא לאגרא\u0004 \u0005[עשויה להשכרה].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא והא\u0004 \u0005[זה וזה]\u0006 מדובר בספינה \u0003דעבידא לאגרא\u0004 \u0005[שעשויה להשכרה],\u0006 \u0003הא דנחית ליה אדעתא דאגרא\u0004 \u0005[זה,\u0006 רב, מדבר במקרה \u0005שירד\u0006 התופס לספינה \u0005על דעת\u0006 לשלם \u0005שכר]\u0006 ולכן נותן שכר, \u0003והא דנחית ליה אדעתא דגזלנותא\u0004 \u0005[וזה,\u0006 שמואל, מדבר במקרה \u0005שירד על דעת גזלנות],\u0006 שמשתמש בה כבגזילה, שלא על מנת לשלם, ומשום כך אינו נותן אלא פחתה ולא יותר, כדין הגזלנים.","שנינו במשנתנו: \u0003גזל מטבע ונסדק\u0004 — משלם כשעת הגזילה (ששינוי הוא וקנאו בכך), אבל אם נפסל — אומר לו \"הרי שלך לפניך\" (שאין זה שינוי ולא קנאו בכך), ונחלקו חכמים בהסבר הלכה זו. \u0003אמר רב הונא:\u0004 מה ששנינו \u0003\"נסדק\"\u0004 — הכוונה ל\u0003נסדק ממש,\u0004 מה ששנינו \u0003\"נפסל\"\u0004 — הכוונה ש\u0003פסלתו\u0004 ה\u0003מלכות,\u0004 שאסרה להשתמש בו.","\u0003ורב יהודה אמר:\u0004 אם \u0003פסלתו\u0004 ה\u0003מלכות נמי\u0004 \u0005[גם כן]\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 כ\u0003נסדק\u0004 שהוא נפסד לגמרי, והרי זה שינוי של ממש. \u0003אלא היכי דמי\u0004 \u0005[כיצד בדיוק הוא]\u0006 ענין זה של \u0003\"נפסל\"?\u0004 — \u0003שפסלתו מדינה זו,\u0004 שאין בני המדינה רוצים עוד להשתמש בו, \u0003ויוצאה\u0004 המטבע ומשתמשים בה \u0003במדינה אחרת.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרב הונא: לדידך דאמרת\u0004 \u0005[ל\u0006שיטה \u0005שלך שאתה אומר]\u0006 כי \u0003\"נפסל\"\u0004 הכוונה היא ש\u0003פסלתו\u0004 ה\u0003מלכות, הרי\u0004 המקרים האחרים הנזכרים במשנתנו \u0003\"פירות והרקיבו, יין והחמיץ\", דכי\u0004 \u0005[שכמו]\u0006 \u0003פסלתו\u0004 ה\u0003מלכות דמי\u0004 \u0005[נחשב\u0006 הדבר\u0005]\u0006 שאינם ראויים לשימוש, \u0003וקתני\u0004 \u0005[ושנה]\u0006 על כך: \u0003משלם כשעת הגזילה,\u0004 שיש בכך שינוי, ומדוע כאן לא יהא הדין כן?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 במקרים אלה בזמן שמרקיב הפרי או מחמיץ היין הרי \u0003נשתנה טעמו וריחו, הכא\u0004 \u0005[כאן]\u0006 במטבע שנפסל על ידי המלכות \u0003לא נשתנה\u0004 במטבע עצמה דבר.","ומן הצד השני \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב יהודה: לדידך דאמרת\u0004 \u0005[ל\u0006שיטה \u0005שלך שאתה אומר]\u0006 כי כאשר \u0003פסלתו\u0004 ה\u0003מלכות נמי\u0004 \u0005[גם כן]\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003\"נסדק\",\u0004 ששינוי של ממש הוא, \u0003הרי\u0004 המקרה הנוסף הנזכר במשנתנו \u0003\"תרומה ונטמאת\", דכי\u0004 \u0005[שכמו]\u0006 \u0003פסלתו\u0004 ה\u0003מלכות דמי\u0004 \u0005[נחשב],\u0006 \u0003וקתני\u0004 \u0005[ושנה\u0006 על כך\u0005]:\u0006 \u0003אומר לו \"הרי שלך לפניך\"!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003לא מינכר היזיקה\u0004 \u0005[ניכר ההיזק]\u0006 ואי אפשר להבחין בין דבר טמא לטהור, \u0003הכא מינכר היזיקה\u0004 \u0005[כאן ניכר ההיזק],\u0006 שהרי רואים שמטבע בצורה זו אי אפשר לקנות בה.","ובענין זה של מטבע שנפסלה \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בבעיה הבאה: \u0003המלוה את חבירו על המטבע, ונפסלה\u0004 אותה \u0003המטבע, רב אמר:\u0004"],["\u0003נותן לו מטבע היוצא\u0004 הראוי לשימוש \u0003באותה שעה\u0004 בזמן הפרעון. \u0003ושמואל אמר: יכול לומר לו\u0004 אני נותן לך מסוג המטבע הישן, ואף על פי שאי אפשר להשתמש בו כאן \u0003לך הוציאו\u0004 (השתמש בו) \u0003במישן,\u0004 כלומר, במדינה רחוקה ששם עדיין משתמשים בו. \u0003אמר רב נחמן: מסתברא מילתיה\u0004 \u0005[מסתברים דבריו]\u0006 של \u0003שמואל\u0004 במקרה \u0003דאית ליה אורחא למיזל\u0004 \u0005[שיש לו,\u0006 למלווה, \u0005דרך\u0006 שמתכונן \u0005ללכת]\u0006 \u0003למישן,\u0004 ולכן יכול הלווה לומר לו: שימתין וישתמש במעות הללו שם. \u0003אבל\u0004 אם \u0003לית ליה אורחא\u0004 \u0005[אין לו דרך],\u0006 כוונה ללכת לשם — \u0003לא,\u0004 וצריך לתת לו מטבע היוצאת במקום הפרעון.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממה ששנינו בברייתא: \u0003אין מחללין\u0004 מעשר שני \u0003על המעות שאינם יוצאות,\u0004 שלא משתמשים בהן עתה כמטבע, \u0003כיצד?\u0004 — אם \u0003היו לו מעות כוזביות\u0004 (של בר כוכבא), או \u0003ירושלמיות, או של מלכים הראשונים\u0004 שאין משתמשים בהן — \u0003אין מחללין\u0004 עליהן. ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם היו לו מטבעות \u0003של\u0004 מלכים \u0003אחרונים,\u0004 כלומר, של עכשיו \u0003דומיא\u0004 \u0005[בדומה]\u0006 למטבעות של מלכים \u0003ראשונים,\u0004 כלומר, מטבעות ששוב אין משתמשים בהן כאן מפני שנפסלו, כיון שיכול להשתמש בהן במקום אחר — \u0003מחללין,\u0004 ומשמע אף על פי שאין הוא עומד ללכת למקום שיוכל להשתמש בהן!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כשאין מלכיות מקפידות זו על זו\u0004 שלא להוציא מתחומן מטבע שנפסלה, ובמקרה זה די באפשרות להשתמש בכסף זה במקום אחר כדי להחשיב אותו כמטבע של ממש, ואין צורך שתהא דרכו של המלווה ללכת לשם.","ושואלים: \u0003אלא\u0004 להסבר זה, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר שמואל\u0004 שאם עומד המלווה ללכת לשם יכול הלווה לשלם לו במטבע שנפסל כאן, אתה מסביר \u0003כשמלכיות מקפידות זו על זו,\u0004 אם כן \u0003היכי מצי ממטי להו\u0004 \u0005[איך\u0006 הוא \u0005יכול להביא אותם\u0006 את המטבעות הללו\u0005]\u0006 למקום אחר? והרי השלטונות יחרימו אותם! ומשיבים: \u0003דממטי לה\u0004 \u0005[שיכול להביא אותם]\u0006 \u0003על ידי הדחק,\u0004 וכגון במקרה \u0003דלא בחשי ואי משכחי קפדי\u0004 \u0005[שאין\u0006 הם \u0005בודקים ואם מוצאים מקפידים\u0006 עליו\u0005],\u0006 ולכן יכול בדוחק להוציא אותם.","ומקשים על עצם שיטתו של שמואל, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003אין מחללין\u0004 מעשר שני \u0003על מעות של כאן\u0004 (של ארץ ישראל) \u0003והן\u0004 המעות והבעלים מצויים \u0003בבבל, ו\u0004כן על מעות \u0003של בבל והן כאן,\u0004 אבל על מעות \u0003של בבל והן בבבל\u0004 — \u0003מחללין. קתני מיהת\u0004 \u0005[שנה על כל פנים]:\u0006 \u0003אין מחללין על מעות של כאן והן בבבל, אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003סופו למיסק להתם\u0004 \u0005[לעלות לשם]\u0006 לארץ ישראל, שהרי לשם כך מחלל את הכסף!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כשמלכיות מקפידות זו על זו\u0004 ביותר, ואי אפשר כלל להעביר כספים. ומשיבים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמדובר כאן שמלכויות מקפידות ביותר, אם כן \u0003של בבל והן בבבל למאי חזו\u0004 \u0005[למה ראויות]\u0006 המעות? הרי אינו יכול להביא אותן לירושלים! ומשיבים: \u0003חזו דזבין בהו\u0004 \u0005[ראויות\u0006 הן \u0005שיקנה בהן]\u0006 \u0003בהמה ומסיק\u0004 \u0005[ויעלה]\u0006 אותה \u0003לירושלים.\u0004","ואגב שהובאה ברייתא זו מתקשים במה שנאמר בה, שאין מחללים בה מעות בבליות, ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003התקינו שיהו\u0004 כל \u0003המעות יוצאות בירושלים מפני כך\u0004 שלא יהיו עיכובים בגלל החלפת ותמורת כספים! \u0003אמר ר' זירא, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן בזמן שיד ישראל תקיפה על אומות העולם,\u0004 אז היתה תקנה זו שכל המטבעות יוצאים בירושלים, \u0003כאן בזמן שיד אומות העולם תקיפה על עצמן,\u0004 כלומר, על ישראל (בלשון נקיה), ואז מקפידים שלא להביא כסף זר לירושלים.","אגב כך אומרים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזהו מטבע\u0004 עתיק \u0003של ירושלים?\u0004 — היו בו רשומים \u0003דוד ושלמה מצד אחד\u0004 של המטבע, \u0003וירושלים עיר הקודש מצד אחר\u0004 שלו. \u0003ואיזהו מטבע של אברהם אבינו?\u0004 — \u0003זקן וזקינה\u0004 (אברהם ושרה) \u0003מצד אחד, ובחור ובתולה\u0004 (יצחק ורבקה) \u0003מצד אחר.\u0004","ועוד בענין דומה, \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב חסדא: המלוה את חבירו על המטבע, והוסיפו עליו,\u0004 שהוסיפו את ערך המטבע, שמטבע בשם זה הוא עכשיו בעל משקל גבוה יותר \u0003מהו,\u0004 האם צריך להחזיר לו סכום מטבעות כעין שלקח, או שווה ערך למשקל הכסף שלווה ממנו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003נותן לו מטבע היוצא באותה שעה,\u0004 בשעת הפרעון. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ואפילו\u0004 הוגדל המטבע ביותר עד שהוא עתה \u0003כי נפיא\u0004 \u0005[כמו נפה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אפילו כי תרטיא\u0004 \u0005[כמו רובע הקב]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006","שאל אותו רבא: \u0003והא קא זיילין פירי\u0004 \u0005[והרי מוזלים הפירות]\u0006 מחמת שינוי ערך מטבע זו, שיכול הוא עתה לקנות הרבה יותר פירות במטבע זו, ונמצא תשלום זה כריבית! \u0003אמר רב אשי: חזינן\u0004 \u0005[רואים אנו],\u0006 \u0003אי מחמת טיבעא זיל\u0004 \u0005[אם מחמת\u0006 שינוי ערך \u0005המטבע הוזלו\u0006 הפירות\u0005]\u0006 — \u0003מנכינן ליה\u0004 \u0005[מנכים אנו לו]\u0006 ומחזיר רק את הסכום שווה הערך למה שלווה קודם,"]]};
